insert into public.recipes (slug, name, meal_type, diet_tags, servings, prep_minutes, batch_friendly, description, steps, photo_url, photo_credit_name, photo_credit_url, active) values
  ('air-fryer-chicken-tenders', 'Air Fryer Chicken Tenders', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 25, false, 'Crunchy breaded chicken tenders without the deep fryer.', array['Season the chicken with salt; dip each piece in beaten egg, then seasoned breadcrumbs.', 'Arrange in the air fryer basket without touching; spray or brush lightly with oil.', 'Cook at {400F} 10 to 12 minutes, flipping once, until golden and cooked through.', 'Serve with your favorite dipping sauce.']::text[], 'https://images.unsplash.com/photo-1703575571101-e15c42139544', 'Unsplash contributor', 'https://unsplash.com/photos/a-couple-of-sandwiches-sitting-on-top-of-a-plate-B338sxfM240', true),
  ('air-fryer-chicken-thighs', 'Air Fryer Crispy Chicken Thighs', 'dinner', array['gluten_free', 'dairy_free', 'high_protein', 'low_carb', 'keto']::text[], 4, 30, false, 'Crackly-skinned chicken thighs in 20 minutes, no oven needed.', array['Pat the chicken dry and season all over with salt, garlic powder and paprika.', 'Arrange skin-side down in the air fryer basket.', 'Cook at {380F} 18 to 22 minutes, flipping once, until the skin is crisp and the inside reaches 165F.', 'Rest 5 minutes and serve.']::text[], 'https://images.unsplash.com/photo-1781737857663-f1f14a60ba46', 'Unsplash contributor', 'https://unsplash.com/photos/golden-brown-pieces-of-food-baking-inside-an-oven-LgrRc0D02Mw', true),
  ('air-fryer-crispy-tofu', 'Air Fryer Crispy Tofu', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 25, false, 'Cornstarch-crisped tofu cubes — the best tofu texture, guaranteed.', array['Press the tofu 10 minutes, then cube it and toss with the cornstarch and salt.', 'Arrange in the air fryer basket in a single layer.', 'Cook at {400F} 12 to 15 minutes, shaking halfway, until golden and crisp.', 'Toss with the soy sauce and sesame oil and serve over rice.']::text[], 'https://images.unsplash.com/photo-1700406901630-be74b14dbb5e', 'Unsplash contributor', 'https://unsplash.com/photos/a-basket-of-french-fries-sitting-on-top-of-a-white-plate-Q0RGghaYexY', true),
  ('air-fryer-falafel-patties', 'Air Fryer Chickpea Patties', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 25, true, 'Crispy falafel-style patties with no frying oil.', array['Mash the chickpeas with the garlic, cumin, flour and salt into a chunky paste; form 8 patties.', 'Arrange in the air fryer basket with space between them; brush or spray lightly with oil.', 'Cook at {380F} 12 to 14 minutes, flipping once, until deep golden and crisp.', 'Serve in pitas or over salad.']::text[], 'https://images.unsplash.com/photo-1695089028114-ce28248f0ab9', 'Unsplash contributor', 'https://unsplash.com/photos/a-close-up-of-a-black-blender-on-a-table-tdUOpMLDPGo', true),
  ('air-fryer-pork-chops', 'Air Fryer Pork Chops', 'dinner', array['gluten_free', 'dairy_free', 'high_protein', 'low_carb']::text[], 4, 20, false, 'Juicy pork chops with a sweet-smoky rub, done in 12 minutes.', array['Rub the chops with the brown sugar, paprika, garlic powder and salt.', 'Arrange in the air fryer basket without overlapping.', 'Cook at {400F} 10 to 12 minutes, flipping once, until the inside reaches 145F.', 'Rest 5 minutes and serve.']::text[], 'https://images.unsplash.com/photo-1698327097684-5726266fc2d4', 'Unsplash contributor', 'https://unsplash.com/photos/a-close-up-of-a-bowl-of-food-with-chopsticks-8SqEafsALao', true),
  ('air-fryer-roasted-vegetables', 'Air Fryer Roasted Vegetables', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'low_carb']::text[], 4, 20, false, 'Crispy-edge vegetables in 15 minutes — broccoli, peppers and onion.', array['Toss the vegetables with the olive oil, garlic powder, salt and pepper.', 'Arrange in the air fryer basket — a little overlap is fine.', 'Cook at {390F} 12 to 15 minutes, shaking twice, until charred at the edges and tender.', 'Serve as a side or over rice with a fried egg.']::text[], 'https://images.unsplash.com/photo-1606791422814-b32c705e3e2f', 'Unsplash contributor', 'https://unsplash.com/photos/cooked-food-on-black-frying-pan-gUU4MF87Ipw', true),
  ('air-fryer-salmon', 'Air Fryer Salmon', 'dinner', array['pescatarian', 'gluten_free', 'dairy_free', 'high_protein', 'low_carb', 'keto']::text[], 4, 15, false, 'Perfectly flaky salmon in 8 minutes with a lemon-garlic rub.', array['Rub the salmon with the olive oil, garlic powder, paprika and salt.', 'Arrange in the air fryer basket without overlapping.', 'Cook at {400F} 7 to 9 minutes until it flakes at the thickest part.', 'Serve with lemon.']::text[], 'https://images.unsplash.com/photo-1745846664210-756817e1b19c', 'Unsplash contributor', 'https://unsplash.com/photos/tomatoes-and-kitchen-appliances-on-a-counter-GX__Pduezt4', true),
  ('albondigas-mexican-meatball-soup', 'Albondigas (Mexican Meatball Soup)', 'dinner', array['dairy_free', 'gluten_free']::text[], 4, 55, true, 'Tender beef and rice meatballs simmered with carrot, potato and zucchini in a light tomato broth.', array['In a bowl mix the ground beef, raw rice, egg, half of the cilantro, half of the garlic, the cumin, oregano and half of the salt with your hands just until combined.', 'Roll the mixture into meatballs about the size of a walnut with damp hands and set them on a plate.', 'In a large pot combine the broth, tomato sauce, onion, the rest of the garlic and the rest of the salt and bring to a boil over high heat.', 'Lower the heat to medium-low, slide in the meatballs one at a time and simmer for 10 minutes without stirring so they hold their shape.', 'Add the carrot and potato, cover and simmer for 15 minutes.', 'Add the zucchini and simmer for 8 to 10 minutes more until the vegetables are tender and the rice inside a meatball is soft when you cut one open.', 'Serve in bowls with the rest of the cilantro and lime wedges to squeeze over.']::text[], 'https://images.unsplash.com/photo-1673436977889-334fcab20436', 'Elena Leya', 'https://unsplash.com/photos/a-bowl-of-soup-with-meatballs-and-vegetables-y-wM_h_27Fg', true),
  ('albondigas-soup', 'Meatball Soup (Albondigas)', 'dinner', array['gluten_free', 'dairy_free']::text[], 4, 45, true, 'Minted beef meatballs in a tomato-vegetable broth with potatoes and carrots.', array['Mix the beef with the rice, egg, half the garlic and a pinch of salt; form small meatballs.', 'Sauté the onion in hot oil 4 minutes in a deep pot, add the remaining garlic and tomato paste and cook 1 minute.', 'Add the broth, tomatoes, potatoes and carrots; simmer 10 minutes.', 'Slide in the meatballs gently and simmer 15 minutes until cooked through.', 'Season with salt and serve with lime.']::text[], 'https://images.unsplash.com/photo-1784429611794-aecb6ebaef48', 'Unsplash contributor', 'https://unsplash.com/photos/spicy-hot-pot-broth-with-various-ingredients-on-a-table-U_jfjAxoD4g', true),
  ('apple-cinnamon-overnight-oats', 'Apple Cinnamon Overnight Oats', 'breakfast', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 480, true, 'Oats soaked overnight with oat milk and diced apple and cinnamon for four grab-and-go breakfasts.', array['Wash the apples, cut them into quarters, remove the cores and dice them small; leave the peel on.', 'In a large bowl, stir the oats, oat milk, maple syrup, cinnamon and salt until no dry oats or lumps of yogurt remain.', 'Fold in most of the diced apple, saving a handful for the top.', 'Divide among jars or containers with lids, one per serving, and scatter the saved apple on top.', 'Cover and refrigerate at least 8 hours or overnight, until the oats have soaked up the liquid and are soft and thick.', 'Stir and eat cold, loosening with a splash of oat milk if needed. The jars keep up to 4 days in the fridge.']::text[], 'https://images.unsplash.com/photo-1548427049-97fe7f296a1c', 'Naghme Kn', 'https://unsplash.com/photos/chocolate-in-clear-glass-jar-near-apple-slices-hyWqGawZ0zI', true),
  ('arepas-cheese', 'Arepas with Cheese and Avocado', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 30, false, 'Crisp corn cakes split and stuffed with melted cheese and avocado.', array['Stir the masarepa with the salt and warm water; rest 5 minutes until it firms up.', 'Knead briefly and form 8 small patties about half an inch thick.', 'Cook in a lightly oiled skillet over medium heat 5 minutes per side until golden and crusty.', 'Split them open like English muffins, stuff with cheese and return to the pan 1 minute to melt.', 'Serve with avocado and a little sour cream.']::text[], 'https://images.unsplash.com/photo-1783321324850-73cee4dc9be9', 'Unsplash contributor', 'https://unsplash.com/photos/a-hand-placing-cheese-bread-on-a-bamboo-rack-HNDFeKFtxNg', true),
  ('arroz-con-pollo', 'One-Pot Arroz con Pollo', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 50, true, 'Chicken thighs and rice cooked together in a tomato-cumin broth with peas.', array['Season the chicken with salt and brown it in hot oil in a deep pot 4 minutes per side; transfer to a plate.', 'Sauté the onion and bell pepper 4 minutes, add the garlic and cumin and cook 30 seconds.', 'Stir in the rice to coat it, add the tomatoes, broth and turmeric; bring to a simmer.', 'Nestle the chicken back in, cover and cook 20 minutes on low until the rice is tender.', 'Stir in the peas, rest 5 minutes off the heat and serve.']::text[], 'https://images.unsplash.com/photo-1762631383556-7fa1365898b7', 'Unsplash contributor', 'https://unsplash.com/photos/sliced-grilled-chicken-with-rice-and-beans-PSoXt5_8hNM', true),
  ('avocado-toast-with-fried-eggs', 'Avocado Toast', 'breakfast', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 2, 10, false, 'Toasted whole wheat bread piled with lemony mashed avocado.', array['Toast the bread until golden and crisp: use a toaster, or a dry skillet over medium heat for 1 to 2 minutes per side.', 'Halve the avocados, remove the pits and scoop the flesh into a bowl. Add the lemon juice and the salt and mash with a fork, leaving it a little chunky.', 'Spread the mashed avocado over the toast.', 'Sprinkle with the black pepper and red pepper flakes and serve at once.']::text[], 'https://images.unsplash.com/photo-1525351484163-7529414344d8', 'Ben Kolde', 'https://unsplash.com/photos/bread-with-sunny-side-up-egg-served-on-white-ceramic-plate-FFqNATH27EM', true),
  ('bacon-and-egg-breakfast-pizza', 'Bacon and Egg Breakfast Pizza', 'breakfast', array['high_protein']::text[], 4, 35, false, 'Store-bought pizza dough baked with garlic oil, mozzarella and bacon, with an egg cooked on top of each quarter.', array['Heat the oven to {450F} with a rack in the lower third. Take the dough out of the fridge so it relaxes, and lightly oil a large sheet pan with a little of the olive oil.', 'Cook the bacon in a skillet over medium heat 6 minutes, turning once, until the fat has rendered but it is still flexible; it finishes in the oven. Drain and chop.', 'Stretch the dough on a floured counter into a rectangle roughly the size of the pan and lift it onto the pan.', 'Mince the garlic, mix it with the remaining olive oil and brush it over the dough. Cover with the mozzarella and bacon, leaving 4 shallow wells for the eggs.', 'Bake 7 minutes, until the crust is set and starting to color.', 'Pull out the pan, crack an egg into each well and bake 6 to 8 minutes more, until the crust is deep golden, the whites are set and the yolks are still soft.', 'Scatter with sliced green onion and the pepper, and cut into 4 pieces so each one has an egg.']::text[], 'https://images.unsplash.com/photo-1593272280654-b56e97e002e4', 'Taylor Rooney', 'https://unsplash.com/photos/pizza-with-egg-and-cheese-on-brown-wooden-table-Vxnwk1qB8P8', true),
  ('bacon-and-egg-spaghetti-with-peas', 'Bacon and Egg Spaghetti with Peas', 'dinner', '{}'::text[], 4, 25, false, 'Spaghetti in a silky egg and parmesan sauce with crisp bacon, garlic and sweet peas.', array['Bring a large pot of water to a boil over high heat, add the salt and cook the spaghetti for the time on the package, usually 9 to 11 minutes, adding the peas for the last minute.', 'Meanwhile, cook the chopped bacon in a large skillet over medium heat 6 to 8 minutes, stirring, until crisp; stir in the garlic for 30 seconds and turn off the heat.', 'Whisk the eggs with the parmesan and pepper in a bowl until smooth.', 'Scoop out about half a cup of the pasta water, then drain the spaghetti and peas.', 'Add the pasta to the skillet with the bacon and toss over low heat 30 seconds to coat it in the fat.', 'Take the pan off the heat, pour in the egg mixture and toss constantly 1 to 2 minutes, adding pasta water a splash at a time, until the sauce is creamy and coats the pasta without scrambling.']::text[], 'https://images.unsplash.com/photo-1612548041504-659189a63246', 'logan jeffrey', 'https://unsplash.com/photos/pasta-dish-on-white-ceramic-plate-Ky12Qu8fKzM', true),
  ('bacon-egg-cheese-breakfast-quesadillas', 'Bacon, Egg and Cheese Breakfast Quesadillas', 'breakfast', array['high_protein']::text[], 2, 20, false, 'Crisp folded tortillas filled with scrambled eggs, bacon and melted cheddar, served with salsa.', array['Lay the bacon in a cold large skillet and cook over medium heat 8 minutes, turning now and then, until crisp. Drain on a paper towel, crumble it, and pour off all but a thin film of fat.', 'Beat the eggs and scramble them in the skillet over medium-low heat 2 minutes, stirring, until just set. Move them to a plate and wipe out the skillet.', 'Lay one tortilla in the skillet over medium heat. Cover half of it with a quarter of the cheddar, half of the eggs, half of the bacon and green onion, and another quarter of the cheddar, then fold the tortilla over.', 'Cook 2 minutes per side, pressing lightly with the spatula, until golden and crisp and the cheese has melted.', 'Repeat with the second tortilla, then cut each quesadilla into wedges and serve with the salsa.']::text[], 'https://images.unsplash.com/photo-1647545401800-bd8f77e670ed', 'Mikey Frost', 'https://unsplash.com/photos/a-close-up-of-a-plate-of-food-on-a-table-jzaA_v8ucGs', true),
  ('bacon-eggs-and-avocado-plates', 'Bacon, Eggs and Avocado Plates', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 2, 15, false, 'A classic low-carb plate of crisp bacon, eggs fried in butter and sliced avocado.', array['Lay the bacon in one layer in a cold large skillet and set it over medium heat; starting cold melts the fat slowly so the bacon crisps evenly.', 'Cook about 8 minutes, turning every 2 minutes, until deep golden and crisp. Move to a plate lined with paper towels.', 'Carefully pour off all but a thin film of fat into a heatproof cup and add the butter to the skillet, still over medium heat.', 'When the butter foams, crack in the eggs and fry about 3 minutes, until the whites are set and the edges are lightly crisp. Cook them in two batches if they do not fit.', 'While the eggs cook, halve the avocado, remove the pit, peel and slice it.', 'Divide the eggs, bacon and avocado between plates and season everything with the salt and pepper.']::text[], 'https://images.unsplash.com/photo-1608475861994-cf7af0f0c1be', 'James Kern', 'https://unsplash.com/photos/fried-egg-on-black-pan-aLDW0oQ0NtU', true),
  ('baked-berry-oatmeal', 'Baked Berry Oatmeal', 'breakfast', array['gluten_free', 'pescatarian', 'vegetarian']::text[], 4, 45, true, 'Oats baked with milk, egg, banana and frozen berries into soft squares you can reheat all week.', array['Heat the oven to {375F} and grease a medium square baking dish (8 inches, 20 cm) with a little of the butter. Melt the rest.', 'Mix the oats, baking powder, cinnamon and salt in a bowl.', 'In a second bowl, whisk the milk, egg, brown sugar, melted butter and vanilla until smooth.', 'Slice the banana over the bottom of the dish and scatter on half of the berries, straight from the freezer.', 'Cover with the oat mixture, pour the milk mixture evenly over the top and finish with the remaining berries.', 'Bake 35 minutes, until the top is golden and the center feels set when pressed, with no liquid pooling.', 'Let it rest 5 minutes, then scoop into bowls and serve warm.']::text[], 'https://images.unsplash.com/photo-1590906645880-46e10f104160', 'Michal Balog', 'https://unsplash.com/photos/white-and-blue-ceramic-bowl-with-sliced-strawberries-and-blueberries-luw2-JsMsv8', true),
  ('baked-chicken-parmesan-with-spaghetti', 'Baked Chicken Parmesan with Spaghetti', 'dinner', array['high_protein']::text[], 4, 40, false, 'Crispy oven-baked breaded chicken topped with marinara and melted mozzarella over spaghetti.', array['Heat the oven to {425F} and grease a sheet pan with half the oil.', 'Lay each chicken breast flat and slice it in half horizontally to make thinner cutlets.', 'Mix the breadcrumbs with the parmesan, Italian seasoning and salt on a plate; dip each cutlet in the beaten egg, then press it into the crumbs to coat both sides.', 'Set the cutlets on the pan, drizzle with the remaining oil and bake 18 minutes, flipping once, until golden and {165F} in the center.', 'While the chicken bakes, boil the spaghetti in a large pot of water over high heat for the time on the package, usually 9 to 11 minutes, until tender but firm, then drain.', 'Spoon a little marinara over each cutlet, cover with the mozzarella and bake 5 more minutes until the cheese melts and bubbles.', 'Warm the remaining marinara in the pasta pot over medium heat 2 minutes, toss in the spaghetti and serve with the chicken on top.']::text[], 'https://images.unsplash.com/photo-1632778149955-e80f8ceca2e8', 'Clark Douglas', 'https://unsplash.com/photos/a-plate-of-food-with-meat-and-broccoli-HhEfe0DeMiA', true),
  ('baked-eggplant-parmesan', 'Baked Eggplant Parmesan', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 70, true, 'Breaded eggplant slices baked until crisp, then layered with marinara and melted mozzarella.', array['Heat the oven to {425F} and brush two sheet pans with the oil.', 'Cut the eggplant into rounds about as thick as a finger, sprinkle both sides with the salt, leave for 15 minutes and pat dry with paper towels.', 'Beat the eggs in a shallow bowl and mix the breadcrumbs, half of the parmesan and the Italian seasoning in another.', 'Dip each slice in the egg, press it into the crumbs on both sides and lay it on the pans in one layer.', 'Bake for 20 to 25 minutes, turning the slices once, until golden and tender when pierced with a knife.', 'Spread a thin layer of marinara in a large baking dish, cover with half of the eggplant, half of the remaining marinara and half of the mozzarella, then repeat the layers and finish with the rest of the parmesan.', 'Bake for 15 to 20 minutes until the sauce bubbles and the cheese is browned in spots.', 'Let it rest for 10 minutes so it holds together, then serve with the bread.']::text[], 'https://images.unsplash.com/photo-1753775290758-bf6f5ab2cd43', 'Elena Leya', 'https://unsplash.com/photos/deliciously-cooked-meat-served-with-drinks-and-sauce-fC2NQAtuoDA', true),
  ('baked-macaroni-and-cheese', 'Baked Macaroni and Cheese', 'dinner', array['pescatarian', 'vegetarian']::text[], 6, 45, true, 'Elbow macaroni in a creamy cheddar sauce, baked under a crisp buttered breadcrumb topping.', array['Heat the oven to {375F} and grease a large baking dish with a little of the butter.', 'Boil the macaroni in a large pot of salted water for 1 minute less than the package says, then drain.', 'Set aside a spoonful of the butter and melt the rest in the same pot over medium heat, whisk in the flour and cook for 1 minute until it smells toasty.', 'Pour in the milk little by little while whisking, then simmer for 4 to 5 minutes, whisking often, until the sauce coats the back of a spoon.', 'Take the pot off the heat and stir in the cheddar and half of the mozzarella a handful at a time until melted, then add the salt, pepper, garlic powder and paprika.', 'Fold in the macaroni and spread it in the baking dish.', 'Melt the reserved butter, toss it with the breadcrumbs and scatter them over the top with the rest of the mozzarella.', 'Bake for 20 to 25 minutes until the edges bubble and the top is golden, then let it rest for 5 minutes before serving.']::text[], 'https://images.unsplash.com/photo-1701484185547-a71576b65e1a', 'Keith Hanson Jr', 'https://unsplash.com/photos/a-dish-of-macaroni-and-cheese-with-a-spoon-in-it-VKI3lU4GA1w', true),
  ('baked-spaghetti-casserole', 'Baked Spaghetti Casserole', 'dinner', array['high_protein']::text[], 6, 55, true, 'Spaghetti layered with a creamy cheese filling and beef marinara, baked under mozzarella until bubbling.', array['Heat the oven to {350F} and boil the spaghetti in a large pot of salted water for 1 minute less than the package says, then drain.', 'Meanwhile brown the ground beef with the onion in a large skillet over medium-high heat for 7 to 8 minutes, breaking it up, until no pink remains, then spoon off most of the fat.', 'Add the garlic and Italian seasoning, stir for 30 seconds, then add the marinara and salt and simmer for 5 minutes.', 'In a bowl mash the cream cheese with the cottage cheese and half of the parmesan until mostly smooth.', 'Spread half of the spaghetti in a large baking dish, cover with all of the cheese mixture, then the rest of the spaghetti.', 'Pour the meat sauce over the top and sprinkle with the mozzarella and the rest of the parmesan.', 'Bake for 25 to 30 minutes until the sauce bubbles at the edges and the cheese is golden, then rest for 10 minutes before cutting.']::text[], 'https://images.unsplash.com/photo-1645453015291-0a80bbdeeea6', 'Some Tale', 'https://unsplash.com/photos/a-bowl-of-spaghetti-on-a-wooden-tray-IGe6IV7S_IU', true),
  ('baked-ziti-style-penne', 'Baked Ziti-Style Penne', 'dinner', array['vegetarian']::text[], 4, 45, true, 'Pasta baked under marinara, ricotta and a golden mozzarella top.', array['Heat the oven to {375F} and cook the penne 2 minutes less than the package; drain.', 'Stir the pasta with the marinara and the ricotta in the baking dish.', 'Scatter the mozzarella and parmesan over the top.', 'Bake 25 minutes until bubbly and browned in spots; rest 5 minutes and serve.']::text[], 'https://images.unsplash.com/photo-1777333033313-e6d72e7fadc5', 'Unsplash contributor', 'https://unsplash.com/photos/a-fork-lifts-penne-pasta-coated-in-red-sauce-0CHWRa_ZqJ4', true),
  ('banana-oat-blender-pancakes', 'Banana Oat Blender Pancakes', 'breakfast', array['gluten_free', 'pescatarian', 'vegetarian']::text[], 2, 20, false, 'Flourless pancakes made by blending oats, ripe bananas and eggs, cooked until golden and served with syrup.', array['Blend the oats on high for 30 seconds, until they turn into a fine flour.', 'Add the bananas, eggs, milk, baking powder, cinnamon, vanilla and salt and blend 30 seconds more, until smooth. Let the batter stand 5 minutes to thicken.', 'Melt a little of the butter in a large nonstick skillet over medium-low heat.', 'Pour in rounds of batter about the size of your palm and cook 2 to 3 minutes, until bubbles cover the surface and the edges look dry.', 'Flip and cook 1 to 2 minutes more, until golden and springy to the touch. Repeat with the rest of the batter, adding butter as needed.', 'Stack on two plates and serve with the maple syrup.']::text[], 'https://images.unsplash.com/photo-1597249637214-a85d31f434d6', 'Kelsey Curtis', 'https://unsplash.com/photos/pancakes-on-white-ceramic-plate-OWwYniuOyiU', true),
  ('bean-tostada-stacks', 'Crunchy Bean Tostadas', 'dinner', array['vegetarian']::text[], 4, 25, false, 'Fried-crisp tortillas layered with refried beans, cheese, lettuce and salsa.', array['Fry the tortillas in shallow hot oil 1 to 2 minutes per side until crisp; drain on paper and sprinkle with salt.', 'Warm the refried beans in a small pot with a splash of water until spreadable.', 'Spread beans on each tortilla, top with cheese, lettuce, tomato and salsa.', 'Serve right away while the tortilla is still crunchy.']::text[], 'https://images.unsplash.com/photo-1771308354374-3d9ad8970483', 'Unsplash contributor', 'https://unsplash.com/photos/a-neon-sign-advertising-tacos-at-night-7UxRDi7Z9KA', true),
  ('beans-rice-sunday', 'Black Beans and Rice', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 40, true, 'Slow-simmered cumin black beans over fluffy rice with lime and avocado.', array['Cook the rice according to the package directions.', 'Sauté the onion and bell pepper in hot oil 5 minutes until soft, add the garlic, cumin and oregano and cook 1 minute.', 'Add the beans with their liquid and a splash of water; simmer 15 minutes, mashing a few beans to thicken.', 'Season with salt, stir in the lime juice and serve over rice with avocado and cilantro.']::text[], 'https://images.unsplash.com/photo-1771074168450-11e3f8b7aa53', 'Unsplash contributor', 'https://unsplash.com/photos/a-colorful-bowl-of-rice-chickpeas-and-salad-emy9Rhhn2PI', true),
  ('beef-and-broccoli-ramen-stir-fry', 'Beef and Broccoli Ramen Stir-Fry', 'dinner', array['dairy_free']::text[], 4, 20, false, 'Ground beef, broccoli and ramen noodles tossed in a sweet garlic soy sauce.', array['Bring a medium pot of water to a boil over high heat, cook the ramen noodles 3 minutes without the seasoning packets until just tender, then drain.', 'Whisk the soy sauce, brown sugar, cornstarch, ground ginger and half a cup of water in a small bowl until smooth.', 'Heat a large skillet over medium-high heat and cook the ground beef 6 minutes, breaking it up, until no pink remains; spoon off most of the fat.', 'Add the garlic and frozen broccoli, cover and cook 4 minutes until the broccoli is hot and bright green.', 'Pour in the sauce and simmer 2 minutes, stirring, until it thickens and coats the beef.', 'Add the noodles, sesame oil and green onions and toss 1 minute until the noodles are hot and coated.']::text[], 'https://images.unsplash.com/photo-1666613710166-91a0cb67fad9', 'Batkhuyag Enkhtuvshin', 'https://unsplash.com/photos/a-plate-of-food-gdDzQXTyqcE', true),
  ('beef-stew-with-potatoes-and-carrots', 'Beef Stew with Potatoes and Carrots', 'dinner', array['dairy_free']::text[], 4, 120, true, 'Slow-simmered beef with potatoes, carrots, celery and peas in a rich thyme and tomato gravy.', array['Toss the beef with the flour, salt and pepper in a bowl until coated.', 'Heat the oil in a large heavy pot over medium-high heat and brown the beef 6 to 8 minutes, turning, until dark brown on most sides; work in two batches if the pot is crowded.', 'Add the onion, celery and garlic and cook 4 minutes, stirring, until the onion softens.', 'Stir in the tomato paste and cook 1 minute until it darkens.', 'Pour in the broth and Worcestershire, add the thyme and scrape up the browned bits from the bottom.', 'Bring to a boil over high heat, then cover and simmer on low 1 hour.', 'Add the potatoes and carrots, cover and simmer 35 to 40 minutes more until the beef and vegetables are tender enough to cut with a spoon.', 'Stir in the peas, cook 3 minutes until hot and serve.']::text[], 'https://images.unsplash.com/photo-1664741662725-bd131742b7b7', 'Laura Ohlman', 'https://unsplash.com/photos/a-bowl-of-food-y_7KLDoPlAc', true),
  ('beef-taco-soup', 'Beef Taco Soup', 'dinner', array['high_protein', 'gluten_free']::text[], 6, 35, true, 'Ground beef, two kinds of beans, corn and tomatoes simmered with taco seasoning and topped with cheddar and chips.', array['Brown the ground beef with the onion in a large pot over medium-high heat for 7 to 8 minutes, breaking it up with a spoon, until no pink remains.', 'Spoon off most of the fat, sprinkle in the taco seasoning and stir for 1 minute.', 'Add the beans, corn and tomatoes with all of their liquid, the green chiles, tomato sauce and broth and stir well.', 'Bring to a boil over high heat, then lower the heat and simmer uncovered for 20 minutes, stirring now and then, until slightly thickened.', 'Taste, add salt if needed and ladle into bowls.', 'Top each bowl with the cheddar and a handful of crushed tortilla chips.']::text[], 'https://images.unsplash.com/photo-1790701909034-6c7b45c7b58a', 'Chad Montano', 'https://unsplash.com/photos/chili-bowl-with-cheese-and-cream-HNVi6m5KCr8', true),
  ('berry-banana-yogurt-smoothies', 'Berry Banana Smoothies', 'breakfast', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 2, 5, false, 'Frozen berries and banana blended with oat milk into a thick, filling smoothie.', array['Peel the bananas and break them into chunks.', 'Pour the oat milk into the blender first; liquid at the bottom helps the blades catch.', 'Add the banana chunks, the berries straight from the freezer and the maple syrup.', 'Put the lid on and blend on low for 10 seconds, then on high for about 1 minute, until completely smooth with no icy bits.', 'If it is too thick to pour, add a splash of oat milk and blend 10 seconds more.', 'Pour into glasses and serve right away.']::text[], 'https://images.unsplash.com/photo-1570696516188-ade861b84a49', 'Denis', 'https://unsplash.com/photos/pink-smoothie-hsTwPUzFegQ', true),
  ('berry-yogurt-granola-parfaits', 'Berry Yogurt Granola Parfaits', 'breakfast', array['high_protein', 'pescatarian']::text[], 2, 10, false, 'Thick Greek yogurt layered with mixed berries, crunchy granola, almonds and a drizzle of honey.', array['Thaw the berries: leave them in the fridge overnight, microwave them 1 minute on high, or rinse them in a sieve under cold water for 2 minutes, until soft but still cold. Drain well.', 'Roughly chop the almonds.', 'Spoon half of the yogurt into glasses or bowls, one per serving.', 'Add half of the berries and half of the granola, then repeat the layers with the rest.', 'Top with the almonds, drizzle with the honey and serve right away, while the granola is still crunchy.']::text[], 'https://images.unsplash.com/photo-1571230389215-b34a89739ef1', 'Tanaphong Toochinda', 'https://unsplash.com/photos/shallow-focus-photo-of-clear-drinking-glass-GbCEo-Nwyj4', true),
  ('black-bean-cheddar-enchiladas', 'Black Bean and Cheddar Enchiladas', 'dinner', array['gluten_free', 'high_protein', 'pescatarian', 'vegetarian']::text[], 4, 45, true, 'Corn tortillas rolled around black beans, corn and cheddar, baked under red enchilada sauce.', array['Heat the oven to {400F}. Wrap the tortillas in foil and put them in the oven for 8 minutes while it heats, until soft enough to bend without cracking.', 'In a bowl, roughly mash the drained beans with a fork, leaving some whole, then stir in the corn, onion, cumin, chili powder and half the cheddar.', 'Spread a thin layer of enchilada sauce over the bottom of a large baking dish.', 'Spoon a line of filling down the center of each warm tortilla, roll it up and set it seam side down in the dish, packing the rolls snugly.', 'Pour the remaining sauce over the top, covering the ends of the tortillas so they do not dry out, and sprinkle with the rest of the cheddar.', 'Bake uncovered 20 minutes, until the sauce bubbles and the cheese is melted and starting to brown.', 'Rest 5 minutes, then top with spoonfuls of yogurt and the chopped cilantro.']::text[], 'https://images.unsplash.com/photo-1534352956036-cd81e27dd615', 'Alexandra Golovac', 'https://unsplash.com/photos/person-picking-pizza-xsfX3AqLDKo', true),
  ('black-bean-corn-quesadillas', 'Black Bean and Corn Quesadillas', 'lunch', array['pescatarian', 'vegetarian']::text[], 4, 20, false, 'Crispy folded tortillas filled with melted cheddar, black beans and corn, with salsa for dipping.', array['Drain the beans in a sieve and rinse under cold water. Add the corn and run warm water over both for 1 minute to thaw the corn; shake dry.', 'Tip into a bowl, add the cumin and mash lightly with a fork so about a third of the beans break up and hold the filling together.', 'Lay out the tortillas. Sprinkle half of each one with some of the cheddar, spread the bean mixture over it, add the rest of the cheddar and fold the empty half over.', 'Heat about half of the oil in a large skillet over medium heat for 1 minute, tilting to coat the bottom.', 'Cook two quesadillas at a time, 2 to 3 minutes per side, pressing lightly with a spatula, until golden and crisp and the cheese has melted.', 'Repeat with the remaining oil and quesadillas.', 'Rest 1 minute so the cheese sets, cut each quesadilla into wedges and serve with the salsa for dipping.']::text[], 'https://images.unsplash.com/photo-1584398572810-43c36faba2ad', 'David Holifield', 'https://unsplash.com/photos/brown-and-white-dish-on-white-ceramic-plate-hsLYgXwJQW0', true),
  ('black-bean-quesadillas', 'Black Bean Quesadillas', 'dinner', array['vegetarian']::text[], 4, 20, false, 'Smashed cumin black beans and melted cheese in crisp tortillas.', array['Mash the beans with the cumin and a pinch of salt until spreadable but chunky.', 'Spread beans over half a tortilla, scatter cheese, fold in half.', 'Toast in a dry skillet 2 to 3 minutes per side until golden and melty.', 'Cut into wedges and serve with salsa and avocado.']::text[], 'https://images.unsplash.com/photo-1771074168434-95cb12896146', 'Unsplash contributor', 'https://unsplash.com/photos/a-colorful-bowl-of-food-with-rice-chickpeas-and-greens-xe5y6vD8L-M', true),
  ('black-bean-rice-and-cheese-burritos', 'Black Bean, Rice and Cheese Burritos', 'lunch', array['pescatarian', 'vegetarian']::text[], 4, 30, true, 'Freezer-friendly burritos of cumin black beans, salsa rice and cheddar, toasted in a dry skillet until crisp.', array['Put the rice in a small pot with twice its volume of water and half of the salt, bring to a boil over high heat, cover, turn the heat to low and cook 15 minutes, until the water is absorbed. Stir in half of the salsa.', 'Mince the garlic. Heat the oil in a medium skillet over medium heat and cook the garlic and cumin 30 seconds, until fragrant.', 'Add the beans with about half of their liquid and the remaining salt and simmer 5 minutes, mashing about half of them with a fork, until thick enough to hold a line when you drag a spoon through.', 'Warm the tortillas one at a time in a dry skillet over medium heat 15 seconds per side, until flexible.', 'Spoon a line of beans down the center of each tortilla, top with the rice and cheddar, fold in the sides and roll up tightly from the bottom.', 'Set the burritos seam-side down in the dry skillet over medium heat and toast 2 minutes per side, until golden and sealed. Serve with the remaining salsa.']::text[], 'https://images.unsplash.com/photo-1635107420756-9f930ed6c97b', 'Gonzalo Mendiola', 'https://unsplash.com/photos/a-green-plate-topped-with-a-burrito-and-a-cup-of-coffee-1r_k74aEK58', true),
  ('black-bean-sweet-potato-tacos', 'Black Bean and Sweet Potato Tacos', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 35, false, 'Chili-roasted sweet potatoes and black beans in corn tortillas with avocado and lime.', array['Move a rack to the middle of the oven and heat the oven to {425F}.', 'On a large sheet pan, toss the diced sweet potatoes with the oil, cumin, chili powder, smoked paprika and salt and spread them in one layer.', 'Roast 18 minutes, turning once halfway, until the edges brown and a fork slides in easily.', 'Stir the drained beans into the pan and put the tortillas, wrapped in foil, on the rack beside it; roast 5 minutes more, until the beans are hot and the tortillas are soft.', 'Fill the tortillas with the sweet potatoes and beans and top with the red onion, avocado, salsa and cilantro.', 'Cut the lime into wedges and squeeze it over the tacos at the table.']::text[], 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47', 'Chad Montano', 'https://unsplash.com/photos/cooked-tacos-lP5MCM6nZ5A', true),
  ('blackened-tilapia-chopped-salad', 'Blackened Tilapia Chopped Salad', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian']::text[], 4, 20, false, 'Spice-crusted tilapia seared in a hot skillet and served over a crunchy romaine, pepper and feta salad.', array['Mix the paprika, garlic powder, onion powder, thyme, cayenne, salt and pepper in a small bowl. Pat the thawed tilapia dry and coat both sides with the spice mix.', 'Chop the romaine, dice the bell pepper and cucumber and put them in a large bowl.', 'Heat a third of the olive oil in a large skillet over medium-high heat until it shimmers. Cook the fish 3 minutes per side, turning once, until the spices are dark and the flesh flakes easily with a fork.', 'Toss the salad with the remaining olive oil and the juice of the lemon, then add the feta.', 'Divide the salad among plates and lay the fish on top.']::text[], 'https://images.unsplash.com/photo-1755632255314-2c8b14ff0226', 'David Todd McCarty', 'https://unsplash.com/photos/grilled-fish-atop-a-fresh-green-salad-VRJpZd8i2U4', true),
  ('blender-romesco-chicken', 'Chicken with Romesco-Style Sauce', 'dinner', array['gluten_free', 'dairy_free', 'high_protein', 'low_carb']::text[], 4, 30, false, 'Seared chicken over a roasted-pepper almond sauce made in the blender.', array['Blend the peppers, almonds, tomato paste, garlic, vinegar and 3 tablespoons of olive oil into a smooth romesco sauce; season with salt.', 'Season the chicken with salt and let it come to room temperature while you heat the pan.', 'Sear the chicken in hot oil 4 minutes per side until cooked through.', 'Slice the chicken and serve it over a pool of the sauce.']::text[], 'https://images.unsplash.com/photo-1781941622549-1a54f4364845', 'Unsplash contributor', 'https://unsplash.com/photos/savory-meat-rolls-in-red-sauce-garnished-with-herbs-BagkbDPxy2c', true),
  ('blender-tomato-soup', 'Blender Tomato Soup', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 20, true, 'Silky tomato soup made entirely in the blender, with grilled-cheese-ready speed.', array['Sauté the onion and garlic in butter 4 minutes until soft.', 'Add everything to the blender with the tomatoes and cream; blend until completely smooth.', 'Pour into a pot and simmer 5 minutes; season with salt.', 'Serve hot, drizzled with more cream if you like.']::text[], 'https://images.unsplash.com/photo-1781567502827-3c671d8cae63', 'Unsplash contributor', 'https://unsplash.com/photos/delicious-caprese-salad-with-fresh-mozzarella-tomatoes-and-basil-mEH2fejA3J0', true),
  ('breakfast-chilaquiles', 'Chilaquiles Rojos', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 25, false, 'Tortilla chips simmered in red sauce, topped with fried eggs, cheese and crema.', array['Warm the enchilada sauce in a large skillet until simmering.', 'Add the chips and toss gently 2 minutes until they soften but keep some crunch.', 'Fry the eggs in a separate pan to your liking.', 'Serve the sauced chips topped with eggs, feta, onion and sour cream.']::text[], 'https://images.unsplash.com/photo-1787069789754-636ce94929e5', 'Unsplash contributor', 'https://unsplash.com/photos/breakfast-spread-with-croissants-and-fruit-wrWGGlnN3kg', true),
  ('broccoli-cheddar-cream-soup', 'Broccoli Cheddar Soup', 'dinner', array['gluten_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 35, true, 'A thick, creamy broccoli soup finished with plenty of sharp cheddar.', array['Melt the butter in a large pot over medium heat and cook the onion 5 minutes, until soft, then stir in the garlic for 1 minute.', 'Add the chopped broccoli, broth, salt and pepper and bring to a boil over high heat.', 'Lower to medium-low, cover and simmer 12 minutes, until the broccoli stems are soft enough to crush with a spoon.', 'Mash about half the soup in the pot with a potato masher, leaving some broccoli pieces for texture.', 'Turn the heat to low and stir in the cream and cream cheese for about 2 minutes, until the cream cheese melts and the soup is smooth.', 'Add the cheddar a handful at a time, stirring until each handful melts before adding the next; do not let the soup boil, or the cheese turns grainy.', 'Taste, adjust the seasoning and serve hot.']::text[], 'https://images.unsplash.com/photo-1567953921490-6f671d196d1d', 'Denise Spijker', 'https://unsplash.com/photos/white-ceramic-bowl-BA6FzJZ9IfY', true),
  ('broccoli-cheddar-stuffed-baked-potatoes', 'Broccoli Cheddar Stuffed Baked Potatoes', 'lunch', array['gluten_free', 'pescatarian', 'vegetarian']::text[], 4, 30, false, 'Microwave-baked potatoes split open and loaded with broccoli, melted cheddar, sour cream and green onion.', array['Scrub the potatoes and prick each one 6 to 8 times with a fork so steam can escape.', 'Arrange them in a circle on a microwave-safe plate and microwave on high 15 minutes, turning them over halfway. They are done when a knife slides to the center without resistance; if not, continue in 2-minute bursts.', 'Put the broccoli in a microwave-safe bowl with a spoonful of water, cover with a plate and microwave on high 3 to 4 minutes, until hot and tender. Drain and chop roughly.', 'Split each potato lengthwise, squeeze the ends to open it and fluff the inside with a fork together with the butter, salt and pepper.', 'Pile the broccoli and cheddar on the potatoes and microwave 1 minute, until the cheese melts.', 'Top with the sour cream and sliced green onion and serve.']::text[], 'https://images.unsplash.com/photo-1642522685167-cf414ea225be', 'Yolanda Djajakesukma', 'https://unsplash.com/photos/a-baked-potato-covered-in-cheese-and-broccoli-ZarbohKJIQ8', true),
  ('buffalo-chicken-cauliflower-casserole', 'Buffalo Chicken Cauliflower Casserole', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 45, true, 'Shredded chicken and roasted cauliflower baked in a creamy hot sauce and cheddar mixture.', array['Heat the oven to {425F}. Toss the cauliflower with the oil and salt in a large baking dish and roast for 15 minutes until the edges start to brown.', 'Meanwhile pull the meat off the chicken, discard the skin and bones and shred the meat with two forks.', 'In a large bowl stir the cream cheese, sour cream, hot sauce and garlic powder until smooth.', 'Fold in the chicken, celery, half of the cheddar and the roasted cauliflower, then spread the mixture back in the baking dish.', 'Top with the rest of the cheddar and bake for 15 to 20 minutes until bubbling at the edges and golden on top.', 'Scatter the green onion over the top and serve.']::text[], 'https://images.unsplash.com/photo-1626911690101-ae8f428b4468', 'Erik Mclean', 'https://unsplash.com/photos/white-ceramic-plate-with-cooked-food-6FZqY0H05zA', true),
  ('buffalo-chicken-wraps', 'Buffalo Chicken Wraps', 'lunch', array['high_protein']::text[], 4, 25, false, 'Skillet chicken tossed in hot sauce and butter, wrapped with crunchy lettuce, celery, carrot and a creamy yogurt dressing.', array['Cut the chicken into bite-size pieces and season with the salt and half of the garlic powder.', 'Heat the oil in a large skillet over medium-high heat and cook the chicken 6 to 8 minutes, stirring now and then, until golden and no longer pink inside ({165F}).', 'Lower the heat to low, add the butter and hot sauce and stir 1 minute, until the butter melts and the chicken is coated.', 'Stir the yogurt, mayonnaise and remaining garlic powder into a dressing. Shred the romaine, thinly slice the celery and grate the carrot.', 'Warm the tortillas in a dry skillet over medium heat 10 seconds per side, until flexible.', 'Spread the dressing down the center of each tortilla, pile on the romaine, celery, carrot and chicken, fold in the sides and roll up tightly.']::text[], 'https://images.unsplash.com/photo-1621334954920-9fc5f5490401', 'Khalid Boutchich', 'https://unsplash.com/photos/brown-bread-with-white-cream-EeyZZ7DBgXE', true),
  ('butternut-squash-soup', 'Butternut Squash Soup', 'dinner', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 45, true, 'Silky blended soup of butternut squash, onion and carrot with coconut milk, served with crusty bread.', array['Peel the squash, scoop out the seeds and cut the flesh into bite-size cubes.', 'Warm the olive oil in a large pot over medium heat and cook the onion and carrot for 5 minutes until the onion turns translucent.', 'Add the garlic and thyme and stir for 1 minute until fragrant.', 'Add the squash, broth and salt, bring to a boil over high heat, then cover and simmer over low heat for 20 to 25 minutes until the squash falls apart when pressed with a spoon.', 'Blend the soup in batches until completely smooth, filling the blender only halfway and holding the lid down with a towel, and return it to the pot.', 'Stir in the coconut milk and pepper, warm over low heat for 2 minutes without boiling and serve with the sliced bread.']::text[], 'https://images.unsplash.com/photo-1530734575165-ce39d996fbaa', 'Jade Aucamp', 'https://unsplash.com/photos/soup-with-sesame-seeds-and-bread-OMcrCX6wDpU', true),
  ('cabbage-smoked-sausage-soup', 'Cabbage and Smoked Sausage Soup', 'dinner', array['dairy_free', 'gluten_free', 'keto', 'low_carb']::text[], 4, 40, true, 'Browned smoked sausage, cabbage and tomatoes simmered in a paprika broth; filling, cheap and low in carbs.', array['Heat the oil in a large pot over medium-high heat and brown the sausage for 5 minutes, stirring now and then, until the edges are deep golden.', 'Add the onion and celery and cook over medium heat for 5 minutes until soft.', 'Add the garlic, smoked paprika and thyme and stir for 30 seconds until fragrant.', 'Add the cabbage, tomatoes with their juice, broth, salt and pepper and bring to a boil over high heat.', 'Lower the heat, cover and simmer for 15 to 20 minutes until the cabbage is tender.', 'Stir in the vinegar, taste, adjust the salt and serve.']::text[], 'https://images.unsplash.com/photo-1788141485442-f0d4ce4dca2e', 'Charles Chen', 'https://unsplash.com/photos/vegetable-soup-in-black-bowl-YdMbzFOxbMQ', true),
  ('cacio-e-pepe-beans', 'Cacio e Pepe Beans', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 20, false, 'White beans in a peppery parmesan-butter sauce — Rome on a budget.', array['Toast the black pepper in butter 1 minute until fragrant.', 'Add the beans with a splash of water and warm 4 minutes, mashing a few to thicken.', 'Off the heat, stir in the parmesan until creamy.', 'Serve in bowls with more pepper and parmesan on top.']::text[], 'https://images.unsplash.com/photo-1770678724670-155587ca1bb7', 'Unsplash contributor', 'https://unsplash.com/photos/a-fork-and-spoon-twirling-pasta-on-a-white-plate-FAvytOu3Cig', true),
  ('cajun-tilapia-seasoned-rice', 'Cajun Tilapia over Seasoned Rice', 'dinner', array['high_protein', 'pescatarian', 'gluten_free']::text[], 4, 30, false, 'Spice-rubbed tilapia fillets seared in butter and served over paprika rice with fresh tomato and lemon.', array['Put the rice in a pot with twice its volume of water, a third of the paprika and half the salt. Bring to a boil over high heat, then cover, turn the heat to low and cook 15 minutes until the water is absorbed; leave it covered off the heat until serving.', 'Mix the remaining paprika and salt with the garlic powder, onion powder, oregano, thyme and cayenne. Pat the thawed tilapia dry and coat both sides with the spice mix.', 'Slice the tomatoes and cut the lemon into wedges.', 'Melt the butter in a large skillet over medium-high heat until it foams. Cook the fish 3 to 4 minutes per side, turning it once with care, until the crust is dark and the flesh flakes easily with a fork.', 'Fluff the rice with a fork, divide it among plates and top with the fish.', 'Serve with the sliced tomato and lemon wedges.']::text[], 'https://images.unsplash.com/photo-1661081090172-f91124f63c51', 'Design Wala', 'https://unsplash.com/photos/a-plate-of-food-lDbGDnNe0CI', true),
  ('caprese-chicken-skillet', 'Caprese Chicken Skillet', 'dinner', array['gluten_free', 'low_carb', 'high_protein']::text[], 4, 30, false, 'Seared chicken topped with tomato, mozzarella and basil, finished under the broiler.', array['Heat the oven broiler. Season the chicken with salt and Italian seasoning.', 'Sear in hot olive oil in an oven-safe skillet 4 minutes per side until golden and nearly cooked.', 'Top each piece with tomato slices and mozzarella.', 'Broil 3 minutes until the cheese melts and bubbles.', 'Serve with basil and a drizzle of balsamic.']::text[], 'https://images.unsplash.com/photo-1769458313937-b5ad8f84942e', 'Unsplash contributor', 'https://unsplash.com/photos/caprese-salad-with-fresh-tomatoes-mozzarella-and-basil-vJ-qtXoD-V8', true),
  ('carne-asada-bowls', 'Carne Asada Bowls', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 35, false, 'Lime-cumin marinated steak over rice with beans and pico-style salsa.', array['Marinate the steak in the lime juice, half the cumin, garlic and a pinch of salt for 10 minutes.', 'Cook the rice according to the package directions.', 'Sear the steak in a very hot oiled skillet 3 to 4 minutes per side; rest 5 minutes, then slice thin.', 'Warm the beans with the remaining cumin.', 'Serve the steak over rice with beans, salsa and avocado.']::text[], 'https://images.unsplash.com/photo-1779414518295-b03b6c60921b', 'Unsplash contributor', 'https://unsplash.com/photos/carne-asada-with-salsas-tortillas-and-pickled-onions-eQ83dvlvi0E', true),
  ('carnitas-tacos', 'Easy Carnitas Tacos', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 90, true, 'Slow-braised pork shoulder, crisped under the broiler, in corn tortillas with onion and lime.', array['Heat the oven to {325F}.', 'Cut the pork into large chunks, season with salt and place in a pot with the onion, garlic, cumin, oregano and enough water to barely cover.', 'Cover and braise in the oven 1 hour until fork-tender.', 'Shred the pork, spread it on a sheet pan and broil 4 minutes until the edges crisp.', 'Serve in warm corn tortillas with chopped onion, cilantro and lime.']::text[], 'https://images.unsplash.com/photo-1599974579688-8dbdd335c77f', 'Unsplash contributor', 'https://unsplash.com/photos/beef-tacos-with-onion-and-cilantro-z_PfaGzeN9E', true),
  ('cauliflower-egg-fried-rice', 'Cauliflower Egg Fried Rice', 'dinner', array['dairy_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 20, false, 'Riced cauliflower stir-fried with scrambled eggs, mushrooms, carrot and green onion.', array['Beat the eggs in a bowl. Heat half the vegetable oil in a large skillet or wok over medium heat, pour in the eggs and stir 1 to 2 minutes, until just set; move them to a plate.', 'Raise the heat to high, add the remaining oil and cook the mushrooms and carrot 5 minutes, stirring now and then, until the mushrooms are browned and their liquid has cooked off.', 'Add the garlic, ginger and the cauliflower rice straight from the freezer and stir-fry 5 to 6 minutes, until the cauliflower is tender and the pan is dry.', 'Return the eggs to the pan, add the soy sauce and sesame oil and toss 1 minute, until everything is hot and evenly coated.', 'Serve topped with the green onion.']::text[], 'https://images.unsplash.com/photo-1716551828295-566b835db769', 'Sarabjeet Singh', 'https://unsplash.com/photos/a-bowl-of-rice-and-chopsticks-on-a-white-table-skVf2YPxrco', true),
  ('cauliflower-mac-and-cheese-bake', 'Cauliflower Mac and Cheese Bake', 'dinner', array['gluten_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 35, false, 'Tender cauliflower florets baked in a rich cheddar cream sauce with a golden parmesan top.', array['Heat the oven to {425F} and bring a large pot of water with a big pinch of salt to a boil over high heat.', 'Boil the cauliflower florets 5 minutes, until a knife slides in with a little resistance, then drain and let them steam dry in the colander for 2 minutes.', 'In a saucepan over low heat, warm the cream and cream cheese for about 3 minutes, whisking, until smooth and steaming.', 'Whisk in the mustard, garlic powder, salt, pepper and three quarters of the cheddar until melted, then take the pan off the heat.', 'Fold the cauliflower into the sauce and spread it in a medium baking dish.', 'Top with the remaining cheddar, the parmesan and the paprika.', 'Bake 15 minutes, until the sauce bubbles at the edges and the top is browned.']::text[], 'https://images.unsplash.com/photo-1586032340622-a86b847e8bdb', 'micheile henderson', 'https://unsplash.com/photos/cooked-food-on-black-ceramic-plate-ECAkA9M4Rwo', true),
  ('cheesy-baked-gnocchi-with-spinach', 'Cheesy Baked Gnocchi with Spinach', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 30, false, 'Potato gnocchi and spinach in marinara, baked under bubbling mozzarella and parmesan.', array['Heat the oven to {425F} and bring a large pot of salted water to a boil.', 'Boil the gnocchi for 2 minutes, just until they float, then drain.', 'Heat the oil in a large oven-safe skillet over medium heat, add the garlic and red pepper flakes and stir for 30 seconds until fragrant.', 'Add the spinach and stir for 2 minutes until wilted, then stir in the marinara, Italian seasoning and gnocchi and bring to a simmer.', 'Scatter the mozzarella and parmesan over the top, moving everything to a baking dish first if your skillet cannot go in the oven.', 'Bake for 12 to 15 minutes until the sauce bubbles and the cheese is browned in spots, then rest for 5 minutes before serving.']::text[], 'https://images.unsplash.com/photo-1650475972369-4579ce5e8b71', 'Max Griss', 'https://unsplash.com/photos/a-casserole-dish-of-pasta-and-basil-with-a-bottle-of-olive-oil-l45QVRM79Sk', true),
  ('cheesy-chicken-broccoli-bake', 'Cheesy Chicken Broccoli Bake', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 40, true, 'Tender chicken and broccoli in a creamy garlic sauce, baked until the cheddar on top is golden and bubbling.', array['Heat the oven to {400F}. Cut the chicken into bite-size pieces and season with the pepper and half the salt.', 'Heat a large nonstick skillet over medium-high heat (no oil is needed) and cook the chicken 5 to 6 minutes, stirring, until lightly golden on the outside; it finishes cooking in the oven.', 'In a large bowl stir the softened cream cheese, sour cream, broth, garlic powder, onion powder and remaining salt until smooth.', 'Pat the thawed broccoli dry with a towel so the sauce stays thick, then add it to the bowl with the chicken and half the cheddar and mix.', 'Spread the mixture in a baking dish, top with the remaining cheddar and bake 20 minutes until the sauce bubbles and the cheese is golden.', 'Let it rest a few minutes so the sauce thickens, then serve.']::text[], 'https://images.unsplash.com/photo-1768204039572-9e62db7b39fd', 'Lee Milo', 'https://unsplash.com/photos/broccoli-and-cheese-gratin-in-a-white-dish-rShpgs9ThwI', true),
  ('cheesy-chicken-broccoli-penne-bake', 'Cheesy Chicken and Broccoli Penne Bake', 'dinner', array['high_protein']::text[], 4, 45, true, 'Penne, chicken and broccoli baked in a homemade cheddar sauce under a crisp breadcrumb topping.', array['Heat the oven to {400F} and bring a large pot of water to a boil over high heat with half the salt.', 'Boil the penne 2 minutes less than the package says, adding the broccoli for the last minute, then drain; the pasta finishes cooking in the oven.', 'Melt half the butter in a large oven-safe skillet over medium-high heat and cook the diced chicken 6 minutes, stirring, until golden and no longer pink inside; move it to a plate.', 'Lower the heat to medium, melt the remaining butter and stir in the garlic and flour for 1 minute.', 'Whisk in the milk a little at a time and simmer 3 to 4 minutes, whisking, until the sauce coats the back of a spoon.', 'Take the pan off the heat and stir in most of the cheddar, the pepper and the remaining salt until melted, then fold in the pasta, broccoli and chicken.', 'Top with the remaining cheddar and the breadcrumbs (move everything to a baking dish first if your skillet is not oven-safe) and bake 15 minutes until golden and bubbling at the edges.']::text[], 'https://images.unsplash.com/photo-1584359246645-de78f6f10850', 'Louis Hansel', 'https://unsplash.com/photos/person-in-white-and-red-plaid-shirt-standing-beside-stainless-steel-tray-DSld8czZ0Ns', true),
  ('cheesy-tuna-cauliflower-casserole', 'Cheesy Tuna Cauliflower Casserole', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian']::text[], 4, 40, true, 'Classic tuna casserole comfort with cauliflower instead of noodles, baked under a cheddar and parmesan crust.', array['Heat the oven to {400F} and bring a large pot of water to a boil over high heat. Cut the cauliflower into small florets and dice the celery.', 'Boil the cauliflower 5 minutes until a knife goes in with a little resistance, then drain it very well and let it steam dry in the colander for 2 minutes.', 'In a large bowl stir the softened cream cheese, sour cream, mustard, garlic powder, salt and pepper until smooth.', 'Fold in the drained tuna, celery, cauliflower and two thirds of the cheddar.', 'Spread the mixture in a baking dish and top with the remaining cheddar and the parmesan.', 'Bake 20 minutes until bubbling at the edges and golden on top; let it stand a couple of minutes before serving.']::text[], 'https://images.unsplash.com/photo-1654780105295-9227206f11ec', 'David Trinks', 'https://unsplash.com/photos/a-casserole-dish-sitting-on-a-stove-top-UN1mx680neg', true),
  ('chicken-and-dumplings', 'Chicken and Dumplings', 'dinner', array['high_protein']::text[], 4, 60, true, 'Shredded chicken thighs and vegetables in a thick gravy, topped with fluffy drop dumplings steamed in the pot.', array['Melt most of the butter, keeping back a spoonful, in a large wide pot over medium heat and cook the onion, carrot and celery for 6 minutes until soft.', 'Add the garlic and thyme, then sprinkle in a quarter of the flour and stir for 1 minute.', 'Pour in the broth little by little while stirring, add the chicken thighs whole with half of the salt and the pepper, bring to a boil, then cover and simmer over low heat for 20 minutes until the chicken is cooked through.', 'Meanwhile whisk the rest of the flour with the baking powder and the remaining salt, melt the reserved butter, and stir it in with two thirds of the milk just until a sticky dough forms.', 'Lift out the chicken, shred it with two forks and return it to the pot with the peas and the rest of the milk; bring back to a gentle simmer.', 'Drop heaped spoonfuls of the dough over the surface, leaving a little space between them.', 'Cover tightly and cook over low heat for 15 minutes without lifting the lid, until the dumplings are puffed and a toothpick poked into one comes out clean.']::text[], 'https://images.unsplash.com/photo-1762388371122-3ad9b573588e', 'Elijah Crouch', 'https://unsplash.com/photos/golden-brown-biscuits-baked-in-a-cast-iron-skillet-NcsdLcklhMQ', true),
  ('chicken-and-sausage-gumbo', 'Chicken and Sausage Gumbo', 'dinner', array['dairy_free', 'high_protein']::text[], 6, 90, true, 'Louisiana stew built on a dark roux with chicken thighs, smoked sausage, onion, celery and bell pepper, over rice.', array['Brown the sausage in a large heavy pot over medium-high heat for 5 minutes, then lift it out onto a plate, leaving the fat behind.', 'Add the oil and flour to the pot and cook over medium heat, stirring constantly with a wooden spoon, for 15 to 20 minutes until the roux is the color of milk chocolate; lower the heat if it smells burnt.', 'Add the onion, bell pepper and celery right away and stir for 5 minutes until soft, then add the garlic, thyme, smoked paprika and cayenne and stir for 1 minute.', 'Pour in the broth little by little while stirring until smooth, then add the chicken thighs whole, the sausage and the salt and bring to a boil.', 'Lower the heat and simmer uncovered for 40 minutes, stirring now and then, until the chicken is very tender and the gumbo coats a spoon.', 'Meanwhile rinse the rice, put it in a pot with twice its volume of water and a pinch of salt, bring to a boil, then cover and cook over low heat for 18 minutes.', 'Lift out the chicken, shred it with two forks and stir it back in, then taste and adjust the salt.', 'Serve the gumbo over a scoop of rice with the green onion on top.']::text[], 'https://images.unsplash.com/photo-1580052380706-16fcc67ee1da', 'uomo libero', 'https://unsplash.com/photos/white-ceramic-plate-with-white-cream-Zz_piqu6fqU', true),
  ('chicken-black-bean-burrito-bowls', 'Chicken & Black Bean Burrito Bowls', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 30, false, 'Taco-spiced chicken over rice with black beans, corn, peppers and salsa: a burrito you eat with a fork.', array['Put the rice in a pot with twice its volume of water. Bring to a boil over high heat, then cover, turn the heat to low and cook 15 minutes until the water is absorbed; leave it covered off the heat until serving.', 'Slice any thick chicken breasts in half horizontally so they cook evenly, then coat both sides with the taco seasoning. Cut the bell pepper into strips, slice the jalapeno, cut the lime into wedges and drain and rinse the beans.', 'Heat the olive oil in a large skillet over medium-high heat. Cook the chicken 5 to 6 minutes per side until golden and no longer pink in the thickest part ({165F}); rest it on a board 5 minutes, then slice.', 'In the same skillet cook the bell pepper over medium-high heat 4 minutes until tender but still crisp, then add the beans and corn and stir 2 to 3 minutes until hot.', 'Fluff the rice with a fork, divide it among bowls and top with the sliced chicken and the pepper, bean and corn mix.', 'Finish with the salsa, sour cream, jalapeno and a squeeze of lime.']::text[], 'https://images.unsplash.com/photo-1716392976013-66d90cac4411', 'AnaCristina Smith', 'https://unsplash.com/photos/a-plate-of-chicken-black-beans-corn-and-salsa-cIXQYJ8V0Gw', true),
  ('chicken-burrito-cauliflower-rice-skillet', 'Chicken Burrito Cauliflower Rice Skillet', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 30, false, 'Taco-seasoned chicken thighs with peppers, salsa and cauliflower rice under melted cheddar, all in one pan.', array['Cut the chicken into small bite-size pieces and toss with the taco seasoning. Dice the onion and bell pepper, chop the cilantro and cut the lime into wedges.', 'Heat the oil in a large skillet over medium-high heat. Add the chicken and cook 6 to 8 minutes, stirring a few times, until browned and cooked through.', 'Add the onion and bell pepper and cook 4 minutes until they soften.', 'Stir in the cauliflower rice and salsa, lower the heat to medium and cook 5 minutes, stirring, until the cauliflower is tender and most of the liquid has cooked off.', 'Sprinkle the cheddar over the top, cover and cook over low heat 2 minutes until the cheese melts.', 'Scatter with the cilantro and serve with the lime wedges.']::text[], 'https://images.unsplash.com/photo-1665332111329-dd9d7fa46c74', 'Keesha''s Kitchen', 'https://unsplash.com/photos/a-bowl-of-food-9VKY7SXjHXE', true),
  ('chicken-caesar-salad-no-croutons', 'Chicken Caesar Salad, No Croutons', 'lunch', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 25, false, 'Seared sliced chicken over crisp romaine with parmesan and a quick creamy Caesar dressing.', array['Pat the chicken dry. If the breasts are thicker than two fingers, slice them in half horizontally so they cook evenly. Season both sides with the garlic powder, salt and pepper.', 'Heat the olive oil in a large skillet over medium-high heat until it shimmers. Add the chicken and cook 5 to 6 minutes without moving it, until golden brown underneath.', 'Flip and cook 5 to 6 minutes more, until the thickest part reaches {165F}, the juices run clear and the center is no longer pink.', 'Move the chicken to a board and rest it 5 minutes so the juices stay in, then slice it across the grain.', 'While the chicken rests, grate the garlic finely and squeeze the lemon. In a large bowl, whisk the mayonnaise, lemon juice, garlic, mustard, Worcestershire and half of the parmesan into a creamy dressing.', 'Wash and dry the romaine, chop it into bite-size pieces and toss it in the bowl until every leaf is coated.', 'Divide among plates and top with the sliced chicken and the remaining parmesan.']::text[], 'https://images.unsplash.com/photo-1676300186659-030de568e39a', 'Orkun Orcan', 'https://unsplash.com/photos/a-white-bowl-filled-with-lettuce-and-chicken-x-YS_Z_YPns', true),
  ('chicken-cauliflower-fried-rice', 'Chicken Cauliflower Fried Rice', 'dinner', array['dairy_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 25, false, 'Golden cauliflower rice stir-fried with chicken, scrambled egg and green onion, ready faster than takeout.', array['Cut the chicken into bite-size pieces and toss with the salt and turmeric. Mince the garlic, dice the carrot small and slice the green onions.', 'Heat the vegetable oil in a large skillet or wok over medium-high heat. Add the chicken in one layer and cook 6 to 7 minutes, stirring now and then, until golden and no longer pink inside; move it to a plate.', 'Lower the heat to medium, crack the eggs into the same pan and stir 1 minute until just set, breaking them into small pieces.', 'Add the garlic and carrot and cook 1 minute. Turn the heat back to medium-high, add the cauliflower rice and cook 4 to 5 minutes, stirring, until tender and the pan looks dry.', 'Return the chicken, add the soy sauce and sesame oil and toss 1 minute until everything is hot.', 'Serve topped with the green onions.']::text[], 'https://images.unsplash.com/photo-1679735386220-e8888925676e', 'Alex Bayev', 'https://unsplash.com/photos/a-plate-of-food-with-chopsticks-next-to-it-7oER79aCOys', true),
  ('chicken-chow-mein', 'Chicken Chow Mein', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 30, false, 'Crisped noodles with chicken, cabbage and bean-sprout crunch in a light soy sauce.', array['Cook the noodles 1 minute less than the package says; drain and pat dry.', 'Heat 1 tablespoon of oil in a large skillet over high heat and fry the noodles 3 minutes until crisp in spots; transfer to a plate.', 'Add the remaining oil and cook the chicken 5 minutes until cooked through.', 'Add the cabbage, carrot and garlic; stir-fry 3 minutes until wilted.', 'Return the noodles with the soy sauce, oyster-style hoisin and sesame oil; toss 2 minutes and serve.']::text[], 'https://images.unsplash.com/photo-1772729219154-2f5d5ddd732b', 'Unsplash contributor', 'https://unsplash.com/photos/a-plate-of-delicious-noodles-with-vegetables-and-mushrooms-OPFPUjdi9BI', true),
  ('chicken-enchiladas-verdes', 'Chicken Enchiladas Verdes', 'dinner', array['gluten_free', 'high_protein']::text[], 4, 40, true, 'Corn tortillas rolled around shredded chicken, baked under salsa verde and melted cheese.', array['Heat the oven to {375F} and lightly oil a baking dish.', 'Shred the chicken and toss it with half the salsa verde and a pinch of salt.', 'Warm the tortillas in a dry skillet 20 seconds per side so they roll without cracking.', 'Fill each tortilla with chicken, roll tightly and place seam-side down in the dish.', 'Pour over the remaining salsa and scatter the cheese on top.', 'Bake 20 minutes until the cheese melts and the edges are bubbly; serve with sour cream and cilantro.']::text[], 'https://images.unsplash.com/photo-1597797061946-cb9b0d4fee88', 'Unsplash contributor', 'https://unsplash.com/photos/fried-chicken-on-stainless-steel-tray-k3I24tHFx4w', true),
  ('chicken-fajita-salad-bowls', 'Chicken Fajita Salad Bowls', 'lunch', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 25, false, 'Spiced chicken strips with charred peppers and onion over romaine, topped with avocado, sour cream and lime.', array['Slice the chicken into thin strips and toss with the chili powder, cumin, garlic powder and most of the salt. Slice the peppers and onion into strips.', 'Heat half of the oil in a large skillet over medium-high heat, add the chicken in one layer and cook 5 to 6 minutes, turning once, until browned and cooked through ({165F}). Move it to a plate.', 'Add the remaining oil, the peppers, the onion and the remaining salt and cook 5 to 6 minutes, stirring now and then, until softened and charred at the edges.', 'Return the chicken to the skillet, squeeze in the juice of half of the lime and toss for 30 seconds.', 'Chop the romaine and divide it among four bowls. Dice the avocado.', 'Top the lettuce with the chicken and vegetables, the avocado and a spoonful of sour cream, and squeeze the remaining lime over the bowls.']::text[], 'https://images.unsplash.com/photo-1564844536311-de546a28c87d', 'Louis Hansel', 'https://unsplash.com/photos/cooked-food-in-bowl-xtC0wQtt4Zo', true),
  ('chicken-mole-bowls', 'Easy Mole-Style Chicken', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 35, true, 'A simplified mole — cocoa, chili and peanut — simmered with chicken over rice.', array['Cook the rice according to the package directions.', 'Sauté the onion 4 minutes, add the garlic, chili powder and cinnamon and cook 1 minute.', 'Stir in the tomatoes and peanut butter and simmer 5 minutes.', 'Blend the sauce until smooth, return to the pan, add the chicken and simmer 10 minutes.', 'Serve over rice with sesame seeds.']::text[], 'https://images.unsplash.com/photo-1700625916627-16ad4fb0553c', 'Unsplash contributor', 'https://unsplash.com/photos/a-table-topped-with-plates-of-food-and-a-bowl-of-guacamole-w9LdceJSEu8', true),
  ('chicken-parmesan-easy', 'Easy Chicken Parmesan', 'dinner', array['high_protein']::text[], 4, 40, false, 'Breaded chicken baked with marinara and mozzarella, over spaghetti.', array['Heat the oven to {425F}. Season the chicken with salt.', 'Dip each piece in beaten egg then breadcrumbs, pressing to coat.', 'Arrange on an oiled sheet pan and bake 15 minutes.', 'Top with marinara and mozzarella and bake 5 minutes more until melted.', 'Meanwhile cook the spaghetti; serve the chicken over it with parmesan.']::text[], 'https://images.unsplash.com/photo-1774828893338-50fd6c5f3062', 'Unsplash contributor', 'https://unsplash.com/photos/gnocchi-with-meat-sauce-red-wine-and-parmesan-cheese-R_-17QeZi6U', true),
  ('chicken-quesadillas', 'Crispy Chicken Quesadillas', 'dinner', array['high_protein']::text[], 4, 25, false, 'Golden tortillas filled with seasoned chicken and melted cheese, with salsa and sour cream.', array['Toss the shredded chicken with the taco seasoning and a splash of water in a skillet; warm 3 minutes until saucy.', 'Lay a tortilla flat, scatter cheese over half, top with chicken and more cheese, then fold in half.', 'Toast in a dry skillet 2 to 3 minutes per side over medium heat until golden and the cheese melts.', 'Cut into wedges and serve with salsa and sour cream.']::text[], 'https://images.unsplash.com/photo-1768967145720-1eae9fe6ecb7', 'Unsplash contributor', 'https://unsplash.com/photos/crispy-tacos-topped-with-diced-onions-and-cilantro-tlfjDBm-fXc', true),
  ('chicken-tetrazzini', 'Chicken Tetrazzini', 'dinner', array['high_protein']::text[], 6, 55, true, 'Spaghetti, shredded chicken, mushrooms and peas in a creamy parmesan sauce, baked with a crisp crumb topping.', array['Heat the oven to {375F} and boil the spaghetti, broken in half, in a large pot of salted water for 2 minutes less than the package says, then drain.', 'Pull the meat off the chicken, discard the skin and bones and shred the meat.', 'Melt the butter in the same pot over medium-high heat and cook the mushrooms for 6 to 8 minutes until their liquid cooks off and they brown.', 'Add the garlic and thyme, stir for 30 seconds, then sprinkle in the flour and stir for 1 minute.', 'Pour in the broth and milk little by little while whisking, then simmer for 4 to 5 minutes until the sauce coats the back of a spoon.', 'Take the pot off the heat and stir in most of the parmesan, the salt, pepper, peas, chicken and spaghetti until coated.', 'Spread in a large baking dish and top with the mozzarella, the breadcrumbs and the rest of the parmesan.', 'Bake for 20 to 25 minutes until bubbling at the edges and golden on top.']::text[], 'https://images.unsplash.com/photo-1583744511860-2daadcb4666e', 'engin akyurt', 'https://unsplash.com/photos/pasta-in-white-ceramic-bowl-Y3IuHd3ztMY', true),
  ('chicken-tinga-tostadas', 'Chicken Tinga Tostadas', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 35, true, 'Shredded chicken simmered in a smoky tomato-chipotle-style sauce, piled on tostadas.', array['Sauté the onion in hot oil 4 minutes until soft, then add the garlic and cook 30 seconds.', 'Add the diced tomatoes, chili powder, cumin and a pinch of salt; simmer 5 minutes.', 'Blend or mash the sauce until mostly smooth, return it to the pan and stir in the shredded chicken.', 'Simmer 10 minutes until thick and saucy.', 'Spoon onto tostada-style chips or fried tortillas and top with avocado and cilantro.']::text[], 'https://images.unsplash.com/photo-1760322328049-91bb196d41d9', 'Unsplash contributor', 'https://unsplash.com/photos/four-gourmet-tacos-with-assorted-toppings-on-wooden-board-D0dNTxlljjo', true),
  ('chicken-tortilla-soup-with-black-beans', 'Chicken Tortilla Soup with Black Beans', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 35, true, 'Brothy tomato-chili soup with shredded chicken, black beans and corn, topped with crushed tortilla chips.', array['Heat the oil in a large pot over medium heat and cook the onion 4 minutes until soft.', 'Stir in the garlic, cumin and chili powder and cook 30 seconds until fragrant.', 'Add the broth, the diced tomatoes with their juice and the whole chicken breasts, bring to a boil over high heat, then cover and simmer on low 15 minutes until the chicken is {165F} and no longer pink in the center.', 'Lift the chicken onto a plate, shred it with two forks and return it to the pot.', 'Stir in the black beans, corn and salt and simmer 5 minutes over medium heat until everything is hot.', 'Take the pot off the heat, stir in the lime juice and serve topped with the crushed tortilla chips and cilantro.']::text[], 'https://images.unsplash.com/photo-1730409261374-6f8a89051fd2', 'Jason Leung', 'https://unsplash.com/photos/a-bowl-of-soup-on-a-table-next-to-a-glass-of-water-7uGYxSRguGQ', true),
  ('chicken-vegetable-stir-fry-with-rice', 'Chicken and Vegetable Stir-Fry with Rice', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 25, false, 'Sliced chicken breast and frozen stir-fry vegetables in a garlic-ginger soy glaze over rice.', array['Put the rice in a medium pot with twice its volume of water, bring to a boil over high heat, then cover and cook on low 15 minutes until the water is absorbed; leave it covered off the heat.', 'Whisk the soy sauce, honey, cornstarch and a quarter cup of water in a small bowl until smooth.', 'Heat half the vegetable oil in a large skillet over high heat, spread out the chicken and cook 5 to 6 minutes, stirring once or twice, until browned and no longer pink inside; move it to a plate.', 'Add the remaining vegetable oil and the frozen vegetables and stir-fry 5 minutes until hot and crisp-tender and most of the water has cooked off.', 'Stir in the garlic and ginger for 30 seconds, then return the chicken and pour in the sauce.', 'Cook 2 minutes, stirring, until the sauce bubbles and turns glossy, then stir in the sesame oil and serve over the fluffed rice.']::text[], 'https://images.unsplash.com/photo-1783196736260-dd788dff4132', 'Alexandra Dobrin', 'https://unsplash.com/photos/delicious-stir-fried-chicken-and-vegetables-with-rice-HU64ydv7xhA', true),
  ('chickpea-spinach-coconut-curry', 'Chickpea Spinach Coconut Curry', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 25, false, 'Chickpeas and spinach in a mild coconut tomato curry, spooned over white rice.', array['Put the rice in a saucepan with twice as much water as rice, bring to a boil, cover and cook over low heat for 18 minutes, until the water is absorbed.', 'Meanwhile, heat the oil in a large skillet or pot over medium heat and cook the onion 4 minutes, until soft.', 'Stir in the garlic, ginger and curry powder and cook 1 minute, until fragrant.', 'Add the tomatoes, coconut milk, drained chickpeas and salt, bring to a simmer and cook over medium-low heat for 10 minutes, until the sauce thickens slightly.', 'Stir in the spinach a handful at a time for about 1 minute, until just wilted.', 'Fluff the rice with a fork and spoon the curry over it.']::text[], 'https://images.unsplash.com/photo-1609595781576-1580ff3ee291', 'Álvaro Bernal', 'https://unsplash.com/photos/cooked-food-on-white-ceramic-plate-ReySmTMcKEQ', true),
  ('chilaquiles-rojos-with-fried-eggs', 'Chilaquiles Rojos with Fried Eggs', 'breakfast', array['gluten_free', 'pescatarian', 'vegetarian']::text[], 2, 15, false, 'Tortilla chips simmered in red salsa until just tender, topped with a fried egg, crumbled cheese and onion.', array['Finely chop the red onion and the cilantro, and crumble the feta.', 'Pour the salsa and a splash of water into a large skillet and simmer over medium heat for 3 minutes, until bubbling and slightly thickened.', 'Meanwhile, heat the oil in a second nonstick skillet over medium heat, crack in the eggs and fry 3 minutes, until the whites are set and the yolks are still runny.', 'Add the chips to the salsa and fold gently for 1 minute, until every chip is coated and the edges just begin to soften.', 'Divide between two plates right away, top each with an egg, the feta, onion, cilantro and a spoonful of sour cream, and serve before the chips go soft.']::text[], 'https://images.unsplash.com/photo-1633372363856-f2fe2669a26e', 'Alexandra Mendívil', 'https://unsplash.com/photos/a-pan-filled-with-food-next-to-two-cups-of-coffee-5sD2TgDZOxA', true),
  ('chile-relleno-casserole', 'Green Chile Egg Bake', 'dinner', array['vegetarian', 'gluten_free', 'low_carb']::text[], 4, 40, true, 'A chile-relleno-style baked egg casserole with green chiles and cheese.', array['Heat the oven to {350F} and butter a baking dish.', 'Whisk the eggs with the sour cream, half the cheese, the green chiles and a pinch of salt.', 'Pour into the dish, scatter the remaining cheese and bake 25 to 30 minutes until set in the center.', 'Rest 5 minutes, cut into squares and serve with salsa.']::text[], 'https://images.unsplash.com/photo-1792046759141-20fd71b96be5', 'Unsplash contributor', 'https://unsplash.com/photos/baked-casserole-with-tomato-wedge-oqnFAsrXTso', true),
  ('chorizo-potato-tacos', 'Chorizo and Potato Tacos', 'dinner', array['gluten_free', 'dairy_free']::text[], 4, 30, false, 'Crumbled chorizo with crispy potatoes in corn tortillas, topped with onion and cilantro.', array['Boil the potatoes in salted water 10 minutes until just tender; drain.', 'Cook the chorizo in a large dry skillet over medium-high heat 5 minutes, breaking it up; transfer with a slotted spoon.', 'Fry the potatoes in the chorizo fat 6 minutes until crisp at the edges, then return the chorizo and toss.', 'Serve in warm tortillas with onion, cilantro and salsa.']::text[], 'https://images.unsplash.com/photo-1757774551171-91143e145b0a', 'Unsplash contributor', 'https://unsplash.com/photos/crispy-corn-taco-shells-arranged-in-a-row-LZLmnoI2OZ0', true),
  ('cinnamon-french-toast', 'Cinnamon French Toast', 'breakfast', array['pescatarian', 'vegetarian']::text[], 4, 20, false, 'Bread soaked in cinnamon-vanilla custard, griddled golden in butter and served with maple syrup.', array['In a wide shallow dish, whisk the eggs, milk, cinnamon and vanilla until smooth, with no streaks of egg white.', 'Melt half of the butter in a large skillet over medium heat until it foams, about 1 minute.', 'Dip half of the bread slices in the custard one at a time, about 5 seconds per side, so they soak it up without falling apart. Let the extra drip off.', 'Lay the slices in the skillet and cook 2 to 3 minutes, until the underside is golden brown.', 'Flip and cook 2 to 3 minutes more, until golden and the center feels springy rather than wet. Move to a plate.', 'Whisk the custard again (the cinnamon floats), melt the remaining butter and cook the rest of the bread the same way.', 'Serve hot with the maple syrup.']::text[], 'https://images.unsplash.com/photo-1631707928780-153b053e09aa', 'montatip lilitsanong', 'https://unsplash.com/photos/a-grilled-cheese-sandwich-on-a-plate-with-a-fork-4NQrFtFBIaI', true),
  ('classic-beef-and-bean-chili', 'Classic Beef and Bean Chili', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 60, true, 'Thick ground beef chili with kidney and pinto beans, tomatoes and warm chili spices, topped with cheddar.', array['Heat a large pot over medium-high heat and cook the ground beef with the onion and bell pepper 8 minutes, breaking up the meat, until no pink remains and the vegetables are soft.', 'Tilt the pot and spoon off most of the fat.', 'Stir in the garlic, chili powder, cumin, oregano and salt and cook 1 minute until fragrant.', 'Add the diced tomatoes with their juice, the tomato sauce, the broth and the drained beans and bring to a boil over high heat.', 'Lower the heat to low, cover with the lid slightly ajar and simmer 40 minutes, stirring now and then, until thick.', 'Ladle into bowls and serve topped with the cheddar.']::text[], 'https://images.unsplash.com/photo-1729450412050-6c00ec592e34', 'Maria Klichik', 'https://unsplash.com/photos/a-bowl-of-chili-next-to-other-bowls-of-food-72oTVZs_730', true),
  ('classic-cobb-salad', 'Classic Cobb Salad', 'lunch', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 30, false, 'Rows of chicken, bacon, hard-boiled egg, avocado, tomato and crumbled cheese over romaine with a mustard vinaigrette.', array['Put the eggs in a small pot, cover with cold water, bring to a boil over high heat, then cover, take off the heat and let stand 10 minutes. Cool under cold water, peel and quarter.', 'Meanwhile, cook the bacon in a large skillet over medium heat 8 minutes, turning now and then, until crisp. Drain on a paper towel, crumble, and leave a thin film of fat in the skillet.', 'Slice the chicken breasts in half horizontally into thin cutlets and season with half of the salt and the pepper.', 'Cook the chicken in the same skillet over medium-high heat 4 to 5 minutes per side, until golden and cooked through ({165F}). Rest 5 minutes, then dice.', 'Mince the garlic and whisk it with the olive oil, vinegar, mustard and remaining salt to make the vinaigrette.', 'Chop the romaine and spread it on a platter or in four bowls. Dice the tomatoes and avocados.', 'Arrange the chicken, bacon, eggs, tomato, avocado and crumbled feta in rows over the lettuce and drizzle with the vinaigrette just before serving.']::text[], 'https://images.unsplash.com/photo-1562634117-6645bf4a9136', 'sheri silver', 'https://unsplash.com/photos/sliced-tomato-cabbage-and-avocado-fruits-AibVl6o117k', true),
  ('classic-meatloaf-with-mashed-potatoes', 'Classic Meatloaf with Mashed Potatoes', 'dinner', array['high_protein']::text[], 4, 70, true, 'Ketchup-glazed beef meatloaf with buttery mashed potatoes and peas.', array['Heat the oven to {375F} and line a sheet pan with foil.', 'In a large bowl, mix the ground beef with the breadcrumbs, egg, onion, garlic, Worcestershire, about a third of the milk, half the ketchup and most of the salt, using your hands just until combined.', 'Shape the mixture into a loaf about as wide as your hand on the pan.', 'Stir the brown sugar into the remaining ketchup and brush it over the top and sides.', 'Bake 50 minutes until the glaze is dark and sticky and the center reaches {160F}, then rest 10 minutes before slicing.', 'About 25 minutes before the meatloaf is done, cover the potatoes with cold water in a large pot, bring to a boil over high heat and simmer 15 minutes until a knife slides in easily; drain.', 'Mash the potatoes with the butter, the remaining milk, the pepper and the remaining salt until smooth.', 'Simmer the peas in a small pot with a splash of water over medium heat 3 minutes until hot, drain, and serve with the sliced meatloaf and mashed potatoes.']::text[], 'https://images.unsplash.com/photo-1705945021699-7374c3fd34cb', 'Martinet Sinan', 'https://unsplash.com/photos/a-loaf-of-meatloaf-on-a-cutting-board-with-a-sprig-of-u0gs_AzC9CQ', true),
  ('classic-tuna-salad-sandwiches', 'Classic Tuna Salad Sandwiches', 'lunch', array['dairy_free', 'high_protein', 'pescatarian']::text[], 2, 10, false, 'Creamy tuna salad with crunchy celery and lemon on whole wheat bread with crisp lettuce.', array['Open the tuna and press the lid down over the sink to squeeze out as much liquid as you can; wet tuna makes soggy sandwiches.', 'Tip the tuna into a bowl and flake it with a fork.', 'Finely dice the celery and squeeze the lemon, catching the seeds.', 'Add the celery, mayonnaise, lemon juice, salt and pepper to the tuna and stir until creamy and evenly mixed. Taste and adjust the seasoning.', 'Wash and dry the romaine leaves. Spread the tuna salad over half of the bread slices and top with the leaves.', 'Close with the remaining bread, press gently and cut each sandwich in half.']::text[], 'https://images.unsplash.com/photo-1558985250-27a406d64cb3', 'Youjeen Cho', 'https://unsplash.com/photos/sandwich-on-table-sBKLiRiunK0', true),
  ('coconut-chicken-soup', 'Coconut Chicken Soup', 'dinner', array['gluten_free', 'dairy_free']::text[], 4, 30, true, 'A fragrant coconut-lime soup with chicken and mushrooms, like a simple tom kha.', array['Bring the broth, ginger and lemongrass-free aromatics (garlic) to a simmer in a pot over medium heat.', 'Add the coconut milk and mushrooms; simmer 5 minutes.', 'Add the chicken and simmer 6 to 8 minutes until cooked through.', 'Stir in the fish sauce, sugar and lime juice; season to taste.', 'Ladle into bowls and top with cilantro.']::text[], 'https://images.unsplash.com/photo-1618449840665-9ed506d73a34', 'Unsplash contributor', 'https://unsplash.com/photos/black-ceramic-bowl-with-soup-0wn-DdavPa4', true),
  ('cold-sesame-noodles', 'Cold Sesame Noodles', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 20, true, 'Chilled noodles in a creamy sesame-peanut sauce with cucumber — great make-ahead.', array['Cook the noodles according to the package directions, drain and rinse under cold water until chilled.', 'Whisk the peanut butter, soy sauce, sesame oil, vinegar, sugar and 3 tablespoons of warm water into a smooth sauce.', 'Toss the noodles with the sauce and half the cucumber.', 'Top with the rest of the cucumber, green onion and sesame seeds; serve cold.']::text[], 'https://images.unsplash.com/photo-1791620050949-cb89234fbb42', 'Unsplash contributor', 'https://unsplash.com/photos/cold-somen-noodles-in-bamboo-basket-qdkg7DbnSl4', true),
  ('cottage-cheese-baked-penne', 'Cottage Cheese Baked Penne', 'dinner', array['high_protein', 'pescatarian', 'vegetarian']::text[], 4, 50, true, 'Penne baked with marinara, spinach and a creamy cottage cheese layer under melted mozzarella.', array['Bring a large pot of water with a big pinch of salt to a boil over high heat.', 'Heat the oven to {400F}. Boil the penne for 2 minutes less than the package says, until bendable but still firm in the center, then drain.', 'While the pasta cooks, squeeze the thawed spinach in your hands over the sink until no more water runs out.', 'Stir the spinach into the cottage cheese with the egg, garlic, Italian seasoning, salt, pepper and half the mozzarella.', 'Toss the drained penne with the marinara in the pot and spread half of it in a large baking dish.', 'Spoon the cottage cheese mixture over the pasta in an even layer and cover with the rest of the penne.', 'Sprinkle the remaining mozzarella and the parmesan over the top.', 'Bake uncovered 20 to 25 minutes, until the sauce bubbles at the edges and the cheese is golden, then rest 5 minutes before serving.']::text[], 'https://images.unsplash.com/photo-1522784081430-8ac6a122cbc8', 'Jonathan Pielmayer', 'https://unsplash.com/photos/bake-mac-on-brown-ceramic-bowl-beside-fork-and-knife-RKJElwIyCQw', true),
  ('cream-of-mushroom-soup', 'Cream of Mushroom Soup', 'dinner', array['keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 35, true, 'Deeply browned mushrooms simmered with garlic and thyme and finished with cream and cream cheese, no flour.', array['Melt half of the butter in a large pot over medium-high heat, add half of the mushrooms and cook for 6 to 8 minutes, stirring only now and then, until their liquid cooks off and they brown; tip them into a bowl.', 'Repeat with the remaining butter and mushrooms, then return the first batch to the pot.', 'Lower the heat to medium, add the onion and cook for 4 minutes until soft, then add the garlic and thyme and stir for 1 minute.', 'Pour in the broth and soy sauce, scrape up the browned bits from the bottom and simmer for 10 minutes.', 'Lower the heat, add the cream cheese in pieces and whisk until it melts into the broth.', 'Stir in the cream, salt and pepper, warm for 2 minutes without boiling and serve sprinkled with the parsley.']::text[], 'https://images.unsplash.com/photo-1659603851579-17755833517e', 'Green And Great', 'https://unsplash.com/photos/a-bowl-of-food-auTqcVC96X4', true),
  ('creamy-broccoli-cheddar-soup', 'Creamy Broccoli Cheddar Soup', 'lunch', array['gluten_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 25, true, 'A thick, cheesy broccoli soup made with frozen florets and no flour; reheats well for lunches.', array['Dice the onion and mince the garlic.', 'Melt the butter in a large pot over medium heat. Add the onion and cook 4 minutes, stirring, until soft and translucent but not browned.', 'Stir in the garlic for 30 seconds, until fragrant, then add the broth and the broccoli straight from the freezer.', 'Turn the heat to high and bring to a boil, then turn it down to medium-low and simmer 8 minutes, until the broccoli is soft enough to crush with a spoon.', 'Take the pot off the heat and mash the broccoli right in it with a potato masher or a fork, leaving some small pieces for texture.', 'Return the pot to low heat and stir in the cream. Add the cheddar a handful at a time, stirring until each handful melts before adding the next; do not let it boil or the cheese turns grainy.', 'Season with the salt and pepper, taste and serve hot.']::text[], 'https://images.unsplash.com/photo-1578859318509-62790b079366', 'Samee Anderson', 'https://unsplash.com/photos/bowl-of-vegetable-soup-x4l4U-pHF9s', true),
  ('creamy-chicken-gnocchi-soup', 'Creamy Chicken Gnocchi Soup', 'dinner', array['high_protein']::text[], 4, 40, true, 'Chicken, potato gnocchi, carrots and spinach in a creamy thyme broth, like the restaurant favorite.', array['Melt the butter in a large pot over medium-high heat, add the chicken with half of the salt and cook for 5 to 6 minutes, stirring, until white on all sides; lift it out onto a plate.', 'Add the onion, carrot and celery to the pot and cook over medium heat for 6 minutes until soft.', 'Add the garlic and thyme, sprinkle in the flour and stir for 1 minute.', 'Pour in the broth and milk little by little while stirring, return the chicken to the pot and simmer for 10 minutes, stirring now and then, until slightly thickened.', 'Add the gnocchi and cook for 3 to 4 minutes until they float and are tender.', 'Stir in the spinach, cream, pepper and the rest of the salt and cook for 1 minute until the spinach wilts, then serve.']::text[], 'https://images.unsplash.com/photo-1679556221456-bde72ab024a1', 'Bakd&Raw by Karolin Baitinger', 'https://unsplash.com/photos/two-bowls-of-food-on-a-marble-table-FnhZXKOgL6M', true),
  ('creamy-lemon-garlic-chicken-skillet', 'Creamy Lemon Garlic Chicken Skillet', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 30, false, 'Pan-seared chicken breasts simmered in a lemon, garlic and parmesan cream sauce, served with steamed broccoli.', array['Slice each chicken breast in half horizontally into two thinner cutlets so they cook evenly, and season both sides with the Italian seasoning, salt and pepper. Mince the garlic, juice half the lemon and slice the other half.', 'Heat the olive oil and butter in a large skillet over medium-high heat until the butter foams. Cook the chicken 4 to 5 minutes per side until golden and firm to the touch ({165F} inside), then move it to a plate.', 'Lower the heat to medium, add the garlic and stir 30 seconds until fragrant. Pour in the broth, cream and lemon juice, scraping up the browned bits from the pan.', 'Simmer 4 minutes until the sauce coats the back of a spoon, then stir in the parmesan.', 'Meanwhile, put the frozen broccoli in a pot with a splash of water, cover and steam over medium-high heat 4 to 5 minutes until bright green and tender; drain.', 'Return the chicken and its juices to the skillet with the lemon slices and warm through 1 minute.', 'Serve the chicken with the broccoli and spoon the sauce over both.']::text[], 'https://images.unsplash.com/photo-1586530844517-791ce35ad21d', 'Eiliv Aceron', 'https://unsplash.com/photos/cooked-food-on-black-ceramic-plate-ashL5eH-osc', true),
  ('creamy-mushroom-soup', 'Creamy Mushroom Soup', 'lunch', array['gluten_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 35, true, 'Deeply browned mushrooms simmered with onion, garlic and thyme, finished with cream and cream cheese, no flour.', array['Slice the mushrooms, dice the onion and mince the garlic.', 'Melt the butter in a large pot over medium-high heat, add the mushrooms and half of the salt and cook 8 to 10 minutes, stirring now and then, until their liquid has evaporated and they are well browned.', 'Add the onion and cook 4 minutes, until soft, then stir in the garlic and thyme for 30 seconds.', 'Pour in the broth and scrape up the browned bits from the bottom. Bring to a boil, lower the heat to medium-low and simmer 10 minutes.', 'Turn the heat to low, add the cream cheese in small pieces and the cream, and stir 2 minutes, until the cream cheese melts and the soup is smooth. Do not let it boil.', 'Season with the remaining salt and the pepper and ladle into bowls.']::text[], 'https://images.unsplash.com/photo-1636044994100-5728ed506526', 'nrd', 'https://unsplash.com/photos/a-bowl-of-soup-on-a-plate-with-a-spoon-TiKeTt7GpyQ', true),
  ('creamy-tomato-penne', 'Creamy Tomato Penne', 'dinner', array['vegetarian']::text[], 4, 25, false, 'Penne in a silky tomato-cream sauce with garlic and parmesan.', array['Cook the penne in salted water according to the package; save a cup of the water before draining.', 'Sauté the garlic in olive oil 1 minute, add the crushed tomatoes and simmer 8 minutes.', 'Stir in the cream and simmer 2 minutes until it turns coral.', 'Toss in the pasta with a splash of its water until coated, then the parmesan and basil.', 'Season with salt and serve.']::text[], 'https://images.unsplash.com/photo-1776810250123-119d15036790', 'Unsplash contributor', 'https://unsplash.com/photos/penne-pasta-with-tomato-sauce-and-herbs-on-a-plate-DiA_t7Fz7lw', true),
  ('creamy-tomato-tortellini-soup', 'Creamy Tomato Tortellini Soup', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 25, false, 'Cheese tortellini and spinach in a creamy tomato broth, ready in one pot.', array['Heat the oil in a large pot over medium heat and cook the onion 4 minutes, until soft.', 'Stir in the garlic and Italian seasoning and cook 1 minute, until fragrant.', 'Add the crushed tomatoes and broth, raise the heat to high and bring to a simmer.', 'Add the tortellini and cook over medium heat 5 to 7 minutes, until they float and are tender when you bite one.', 'Turn the heat to low and stir in the cream and spinach for about 1 minute, until the spinach wilts.', 'Ladle into bowls and sprinkle with the parmesan.']::text[], 'https://images.unsplash.com/photo-1746632794965-cf4b75fd5f92', 'Carlos Davila Cepeda', 'https://unsplash.com/photos/a-bowl-of-soup-is-topped-with-cheese-C2iYbHL9PRQ', true),
  ('crustless-spinach-feta-quiche', 'Crustless Spinach Feta Quiche', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 50, true, 'An easy no-crust quiche with spinach, feta and mozzarella that slices and reheats well all week.', array['Heat the oven to {375F} with a rack in the middle. Grease a standard pie dish or a small baking dish with the butter.', 'Thaw the spinach in a sieve under warm running water for 2 to 3 minutes. Squeeze it by the handful, or wring it in a clean towel, until no more water comes out; wet spinach makes a watery quiche.', 'Finely dice the onion.', 'In a large bowl, whisk the eggs, cream, salt and pepper for 30 seconds, until smooth and even in color.', 'Stir in the spinach, breaking up the clumps, then the onion, feta and mozzarella.', 'Pour into the dish and bake 30 to 35 minutes, until puffed, golden at the edges and set in the center: it should not jiggle when you nudge the dish, and a knife poked in the middle comes out clean.', 'Cool 5 minutes so it firms up, then cut into wedges and serve warm.']::text[], 'https://images.unsplash.com/photo-1636044990861-a540e33f9c5f', 'nrd', 'https://unsplash.com/photos/a-white-plate-topped-with-a-quiche-next-to-a-cup-of-coffee-RVPjkE7gKZo', true),
  ('cuban-style-black-bean-soup', 'Cuban-Style Black Bean Soup', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 40, true, 'Black beans simmered with a sofrito of onion, pepper, garlic and cumin, finished with vinegar and served over rice.', array['Rinse the rice, put it in a small pot with twice its volume of water and a pinch of salt, bring to a boil, then cover and cook over low heat for 18 minutes until tender.', 'Heat the oil in a large pot over medium heat and cook the onion and bell pepper for 6 to 8 minutes, stirring now and then, until soft and lightly golden.', 'Add the garlic, cumin and oregano and stir for 1 minute until fragrant.', 'Pour in the beans with their liquid and the broth, bring to a boil over high heat, then lower the heat and simmer uncovered for 20 minutes until slightly thickened.', 'Mash about a third of the beans against the side of the pot with a potato masher or the back of a spoon so the soup turns creamy.', 'Stir in the vinegar, salt and pepper, taste and adjust, then ladle over the rice and top with the cilantro.']::text[], 'https://images.unsplash.com/photo-1568182602251-496c110627a0', 'Ilya Mirnyy', 'https://unsplash.com/photos/white-ceramic-bowl-with-soup-1URYA5bEnb4', true),
  ('curried-lentil-dal-with-rice', 'Curried Lentil Dal with Rice', 'dinner', array['dairy_free', 'gluten_free', 'high_protein', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 45, true, 'Lentils simmered soft with tomatoes, ginger and curry spices, served over rice with a swirl of coconut milk.', array['Heat the oil in a large pot over medium heat and cook the onion for 5 minutes, stirring, until soft and translucent.', 'Stir in the garlic, ginger, curry powder, cumin and turmeric and cook 1 minute, until fragrant.', 'Add the rinsed lentils, tomatoes, broth and salt, then pour in enough water to cover everything by about two finger widths.', 'Bring to a boil over high heat, then lower to medium-low and simmer partly covered for 25 to 30 minutes, stirring now and then, until the lentils are soft and the dal is thick.', 'Meanwhile, put the rice in a saucepan with twice as much water as rice, bring to a boil, cover and cook over low heat for 18 minutes, until the water is absorbed.', 'Mash some of the lentils against the side of the pot with a spoon to make the dal creamier, adding a splash of water if it is too thick.', 'Spoon the dal over the rice and top with a swirl of coconut milk and the chopped cilantro.']::text[], 'https://images.unsplash.com/photo-1714062105923-5cb2a3a07499', 'Joanna Stołowicz', 'https://unsplash.com/photos/a-table-topped-with-bowls-filled-with-different-types-of-food-QfuQ2qGMDmI', true),
  ('deli-style-egg-salad-sandwiches', 'Deli-Style Egg Salad Sandwiches', 'lunch', array['dairy_free', 'pescatarian']::text[], 4, 25, false, 'Chopped hard-boiled eggs in a creamy mustard dressing with celery, on whole wheat bread.', array['Put the eggs in a pot in one layer and cover with cold water by about a finger''s width. Bring to a full boil over high heat, about 6 minutes.', 'As soon as the water boils, cover the pot, turn off the heat and let the eggs stand 11 minutes for firm yolks.', 'While the eggs stand, finely dice the celery and thinly slice the green onions.', 'Drain the eggs and cover them with cold water for 3 minutes, until cool enough to handle. Tap each one on the counter, roll it to crack the shell all over and peel.', 'Chop the eggs and put them in a bowl with the mayonnaise, mustard, celery, green onions, paprika, salt and pepper. Stir gently until creamy but still chunky.', 'Wash and dry the romaine leaves. Spread the egg salad over half of the bread slices, add the leaves and close with the remaining bread.', 'Cut the sandwiches in half and serve.']::text[], 'https://images.unsplash.com/photo-1733105658196-44b3c597bb41', 'Tadahiro Higuchi', 'https://unsplash.com/photos/a-white-plate-topped-with-a-slice-of-cake-next-to-a-bowl-of-salad-TYvO1gGKyYQ', true),
  ('denver-omelets', 'Denver Omelets', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 2, 15, false, 'The diner classic: folded omelets filled with sautéed ham, bell pepper, onion and melted cheddar.', array['Cut the ham, bell pepper and onion into small dice. Beat the eggs with the salt and pepper.', 'Melt half of the butter in a medium nonstick skillet over medium heat and cook the ham, pepper and onion 4 minutes, until the vegetables are soft and the ham is lightly browned. Scrape into a bowl.', 'Melt half of the remaining butter in the skillet over medium-low heat and pour in half of the eggs.', 'As the eggs set, push the edges toward the center and tilt the skillet so the raw egg runs underneath, about 2 minutes, until the top is barely moist.', 'Spoon half of the ham mixture and half of the cheddar over one side, fold the other side over and cook 30 seconds, until the cheese melts. Slide onto a plate.', 'Repeat with the remaining butter, eggs, filling and cheddar for the second omelet.']::text[], 'https://images.unsplash.com/photo-1709754521379-00166805eea4', 'Dinuka Lankaloka', 'https://unsplash.com/photos/a-white-plate-topped-with-an-omelet-next-to-a-glass-of-orange-juice-M5IajiQxoeo', true),
  ('easy-chicken-fried-rice', 'Easy Chicken Fried Rice', 'dinner', array['dairy_free']::text[], 4, 25, true, 'Day-old rice wok-fried with chicken, eggs, peas and carrots in soy sauce.', array['Heat 1 tablespoon of oil in a large skillet over high heat and scramble the eggs 1 minute until just set; transfer to a plate.', 'Add the remaining oil and cook the chicken 5 to 6 minutes until cooked through; transfer to the plate.', 'Stir-fry the onion, carrot and peas 3 minutes, then add the garlic and cook 30 seconds.', 'Add the rice, breaking up clumps, and fry 3 minutes until hot and a little crisp.', 'Return the chicken and eggs, add the soy sauce and sesame oil, toss 1 minute and serve.']::text[], 'https://images.unsplash.com/photo-1603496987674-79600a000f55', 'Unsplash contributor', 'https://unsplash.com/photos/fried-chicken-on-yellow-rice-77ItGP98s6g', true),
  ('easy-risotto-mushroom', 'Easy Mushroom Risotto', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 45, false, 'Creamy stovetop risotto with golden mushrooms and parmesan.', array['Warm the broth in a pot and keep it at a low simmer.', 'Sear the mushrooms in olive oil 5 minutes until golden; set aside.', 'Soften the onion in butter 4 minutes, add the rice and toast 1 minute.', 'Add broth one ladle at a time, stirring, letting each absorb before the next — about 20 minutes until creamy and al dente.', 'Stir in the mushrooms and parmesan, season with salt and serve.']::text[], 'https://images.unsplash.com/photo-1767974971366-6f8483512f84', 'Unsplash contributor', 'https://unsplash.com/photos/a-small-bowl-of-food-with-green-garnish-vZjNuZmHNVU', true),
  ('egg-and-cheese-bagel-sandwiches', 'Egg and Cheese Bagel Sandwiches', 'breakfast', array['high_protein', 'pescatarian', 'vegetarian']::text[], 2, 10, false, 'Pan-toasted bagels filled with soft folded eggs, melted cheese, spinach and tomato.', array['Split the bagels and toast them cut-side down in a large dry skillet over medium heat 2 minutes, until golden. Set them on two plates.', 'Beat the eggs with the salt and pepper. Melt the butter in the same skillet over medium-low heat.', 'Pour in the eggs and let them set 1 minute, then pull the edges toward the center with a spatula for 1 minute more, until just set but still glossy.', 'Fold the eggs into two bagel-size portions, lay a slice of cheese on each, cover the skillet and cook 30 seconds, until the cheese melts.', 'Slice the tomato. Pile the spinach and tomato on the bottom halves, add the eggs and close with the tops.']::text[], 'https://images.unsplash.com/photo-1707144289499-8903dc4929c7', 'Andrea Lacasse', 'https://unsplash.com/photos/a-person-holding-a-sandwich-in-their-hand-AECi7xJlmsg', true),
  ('egg-drop-soup', 'Egg Drop Soup with Noodles', 'dinner', array['dairy_free']::text[], 4, 15, false, 'Silky egg ribbons in a ginger-scallion broth with quick noodles.', array['Bring the broth to a simmer with the ginger, garlic and soy sauce.', 'Add the ramen noodles and cook 2 minutes.', 'Stir the broth in a circle and drizzle the beaten eggs in slowly — they form ribbons as they set.', 'Add the spinach and sesame oil, cook 30 seconds and serve with green onion.']::text[], 'https://images.unsplash.com/photo-1701480253822-1842236c9a97', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-soup-with-noodles-meat-and-vegetables-_33r6H_hiz4', true),
  ('egg-drop-soup-with-mushrooms-and-spinach', 'Egg Drop Soup with Mushrooms and Spinach', 'lunch', array['dairy_free', 'keto', 'low_carb']::text[], 2, 15, false, 'Ginger-scented chicken broth with silky ribbons of egg, mushrooms and spinach, ready in 15 minutes.', array['Slice the mushrooms and green onions and grate the ginger. Stir the cornstarch with a splash of cold water until smooth. Beat the eggs in a cup with a spout.', 'Bring the broth, ginger, soy sauce and mushrooms to a boil in a medium pot over high heat, then lower the heat to medium and simmer 3 minutes, until the mushrooms are tender.', 'Stir the cornstarch mixture again, pour it in while stirring and simmer 1 minute, until the soup thickens slightly and looks glossy.', 'Add the spinach and stir 30 seconds, until wilted. Turn the heat to low so the soup is barely moving.', 'Stir the soup slowly in one direction and pour in the eggs in a thin stream, then stop stirring and let the ribbons set for 30 seconds.', 'Take off the heat, stir in the sesame oil and pepper, and serve topped with the green onions.']::text[], 'https://images.unsplash.com/photo-1652088079703-38f4a8d6b981', 'Alex Bayev', 'https://unsplash.com/photos/a-bowl-of-soup-with-a-spoon-OPeL-54iYOU', true),
  ('egg-in-a-hole-toast', 'Egg in a Hole Toast', 'breakfast', array['low_carb', 'pescatarian', 'vegetarian']::text[], 2, 10, false, 'Buttery pan-toasted bread with an egg fried right in the middle, plus the toasted cut-outs for dipping.', array['Cut a hole in the center of each slice of bread with the rim of a small glass, and keep the cut-out rounds.', 'Melt half of the butter in a large nonstick skillet over medium heat.', 'Add two slices of bread and their rounds and toast 1 minute, until the underside starts to turn golden.', 'Crack an egg into each hole, season with salt and pepper and cook 2 minutes, until the white is mostly set underneath.', 'Flip the bread and the rounds carefully with a wide spatula and cook 1 minute more for a runny yolk or 2 minutes for a firm one.', 'Repeat with the remaining butter, bread and eggs, and serve with the toasted rounds for dipping in the yolk.']::text[], 'https://images.unsplash.com/photo-1635345144460-d0c1200bc96a', 'Dmitry Dreyer', 'https://unsplash.com/photos/a-pan-with-toast-and-an-egg-on-it-lTtmWp95FJw', true),
  ('eggplant-parmesan-skillet', 'Skillet Eggplant Parmesan', 'dinner', array['vegetarian']::text[], 4, 45, true, 'Layered eggplant, marinara and mozzarella baked in one skillet.', array['Heat the oven to {400F}.', 'Salt the eggplant slices and fry in batches in hot olive oil 3 minutes per side until golden; drain on paper.', 'In an oven-safe skillet, layer sauce, eggplant, mozzarella and parmesan, repeating twice.', 'Bake 20 minutes until bubbly and browned; rest 10 minutes and serve.']::text[], 'https://images.unsplash.com/photo-1779738193253-3a271577f723', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-gnocchi-with-eggplant-sage-and-creamy-sauce-L7i7rEKc9Ng', true),
  ('empanadas-beef', 'Baked Beef Empanadas', 'dinner', array['high_protein']::text[], 4, 50, true, 'Flaky rounds filled with cumin-beef picadillo, baked golden instead of fried.', array['Sauté the onion in hot oil 4 minutes, add the beef and cook 6 minutes, breaking it up, until browned.', 'Stir in the cumin, paprika, olives and raisins-free seasoning with salt; cook 2 minutes and let cool slightly.', 'Heat the oven to {400F} and line a sheet pan with parchment.', 'Separate the dough into 8 small balls (or use store rounds), roll each into a circle, fill with beef and fold into a half-moon, crimping the edge.', 'Brush the tops with beaten egg and bake 20 minutes until golden.']::text[], 'https://images.unsplash.com/photo-1774971343509-d575ec6bd3af', 'Unsplash contributor', 'https://unsplash.com/photos/rows-of-assorted-empanadas-on-display-wyOmd8z2Uws', true),
  ('enchiladas-rojas-beef', 'Beef Enchiladas Rojas', 'dinner', array['high_protein']::text[], 4, 40, true, 'Ground beef and cheese enchiladas under red sauce, baked until bubbly.', array['Heat the oven to {375F}.', 'Brown the beef with the onion in a skillet 6 minutes; stir in the cumin and a pinch of salt.', 'Warm the tortillas so they roll without cracking, spread a spoonful of sauce in the dish.', 'Fill each tortilla with beef and a little cheese, roll and place seam-side down.', 'Cover with the rest of the sauce and cheese and bake 20 minutes until bubbly.']::text[], 'https://images.unsplash.com/photo-1786052600217-992704210ff8', 'Unsplash contributor', 'https://unsplash.com/photos/plate-of-meat-in-red-sauce-rice-and-a-side-6NtsTM2LsuQ', true),
  ('falafel-style-chickpea-patties', 'Chickpea Patties with Yogurt', 'dinner', array['vegetarian', 'dairy_free', 'vegan']::text[], 4, 30, true, 'Crispy falafel-style chickpea patties in pitas with lemon yogurt.', array['Mash the chickpeas with the garlic, cumin, flour and salt into a chunky paste; form 8 patties.', 'Fry in hot oil 3 to 4 minutes per side until crisp and golden.', 'Whisk the tahini with the lemon juice and 2 tablespoons of water into a creamy sauce; season with salt.', 'Serve the patties in pitas with the sauce, tomato and cucumber.']::text[], 'https://images.unsplash.com/photo-1603360946369-dc9bb6258143', 'Unsplash contributor', 'https://unsplash.com/photos/grilled-meat-skewers-with-fries-WHtVB-RiW2I', true),
  ('fish-tacos-cabbage', 'Fish Tacos with Lime Slaw', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 30, false, 'Spiced white fish in warm tortillas with crunchy lime slaw.', array['Toss the slaw mix with the lime juice and a pinch of salt; set aside.', 'Season the fish with the chili powder, cumin, garlic powder and salt.', 'Cook in hot oiled skillet 3 minutes per side until it flakes; break into large pieces.', 'Warm the tortillas and serve the fish inside with the slaw and avocado.']::text[], 'https://images.unsplash.com/photo-1768716575089-7ba787da9afb', 'Unsplash contributor', 'https://unsplash.com/photos/three-tacos-with-lime-wedges-in-a-white-box-4xwEQ6IIubA', true),
  ('five-spice-pork-tenderloin', 'Soy-Glazed Pork Tenderloin', 'dinner', array['high_protein', 'dairy_free', 'low_carb']::text[], 4, 35, true, 'Roasted pork tenderloin with a five-spice style soy glaze and roasted broccoli.', array['Heat the oven to {425F} and line a sheet pan with parchment.', 'Whisk the soy sauce, honey, garlic, ginger and chili powder into a glaze.', 'Place the pork on the pan with the broccoli alongside, toss the broccoli with oil and salt.', 'Roast 18 to 22 minutes, brushing the pork with glaze twice, until the thickest part reaches 145F inside.', 'Rest 5 minutes, slice and serve with the broccoli and pan juices.']::text[], 'https://images.unsplash.com/photo-1784902540665-f6ab6dfef921', 'Unsplash contributor', 'https://unsplash.com/photos/cooked-chicken-rice-and-vegetables-with-various-spices-P53oXx7TcXI', true),
  ('fluffy-pancakes-with-maple-syrup', 'Fluffy Pancakes with Maple Syrup', 'breakfast', array['pescatarian', 'vegetarian']::text[], 4, 25, true, 'Tall from-scratch pancakes made with pantry staples; extras freeze well for toaster mornings.', array['Melt the butter in a large skillet over low heat, about 1 minute, then pour it into a cup. Wipe the skillet lightly; you will cook in it.', 'In a large bowl, whisk the flour, baking powder, sugar and salt together.', 'In a second bowl, whisk the milk, the egg and about two thirds of the melted butter until blended.', 'Pour the wet mixture into the dry and stir just until no dry flour shows. A few small lumps are fine; overmixing makes tough pancakes. Let the batter rest 2 minutes.', 'Heat the skillet over medium heat for 2 minutes and brush it with a little of the remaining butter. It is ready when a drop of water sizzles on contact.', 'Pour in small ladlefuls of batter, leaving space between them, and cook about 2 minutes, until bubbles pop on the surface and the edges look dry.', 'Flip with a spatula and cook 1 to 2 minutes more, until golden on both sides and springy in the center.', 'Repeat with the remaining batter, brushing the skillet with butter between batches and lowering the heat a little if they brown too fast.', 'Serve stacked, with the maple syrup poured over.']::text[], 'https://images.unsplash.com/photo-1620108091863-55147620ddaf', 'Anna Zaro', 'https://unsplash.com/photos/brown-cookies-on-white-ceramic-plate-9qpXI_mujpk', true),
  ('fried-egg-blt-sandwiches', 'Fried Egg BLT Sandwiches', 'breakfast', array['dairy_free']::text[], 2, 15, false, 'Toasted bread stacked with crisp bacon, lettuce, tomato and a fried egg with a soft yolk.', array['Lay the bacon in a cold large skillet and cook over medium heat 8 minutes, turning now and then, until crisp. Drain on a paper towel and pour off all but a thin film of fat.', 'Toast the bread in the skillet over medium heat 1 to 2 minutes per side, until golden, then set it on two plates.', 'Crack the eggs into the skillet, season with the salt and pepper and fry over medium heat 2 minutes. Flip and cook 30 seconds more for a soft yolk, or 1 minute for a firm one.', 'Slice the tomato and separate the romaine leaves.', 'Spread the mayonnaise on the toast and stack two of the slices with the lettuce, tomato, bacon and an egg. Close with the remaining toast and cut in half.']::text[], 'https://images.unsplash.com/photo-1624383804003-44d04b668775', 'Peter Bravo de los Rios', 'https://unsplash.com/photos/burger-with-vegetable-and-meat-on-white-ceramic-plate-nOoaFCsnkvo', true),
  ('garlic-butter-shrimp-mushroom-skillet', 'Garlic Butter Shrimp & Mushroom Skillet', 'dinner', array['gluten_free', 'keto', 'low_carb', 'pescatarian']::text[], 4, 20, false, 'Shrimp, mushrooms and zucchini sauteed in garlic butter with lemon and a pinch of red pepper.', array['Thaw the shrimp in a bowl of cold water for about 10 minutes, then drain and pat very dry. Meanwhile slice the mushrooms, dice the zucchini and mince the garlic.', 'Heat the olive oil in a large skillet over medium-high heat. Add the mushrooms and zucchini in one layer and cook 5 to 6 minutes, stirring only twice, until browned.', 'Push the vegetables to the edges, lower the heat to medium and melt the butter in the middle with the garlic and pepper flakes for 30 seconds.', 'Add the shrimp in one layer and cook 2 minutes per side until pink and curled into a loose C shape.', 'Squeeze in the juice of the lemon, add the salt, toss everything together and serve right away.']::text[], 'https://images.unsplash.com/photo-1659951226926-a75791782250', 'Durenne Loris', 'https://unsplash.com/photos/a-pan-of-food-aEHCeaGSgKA', true),
  ('garlic-butter-shrimp-pasta', 'Garlic Butter Shrimp Pasta', 'dinner', array['pescatarian', 'high_protein']::text[], 4, 20, false, 'Spaghetti with shrimp seared in garlic butter, lemon and parsley.', array['Cook the spaghetti in salted water; save a cup of the water before draining.', 'Sear the shrimp in hot olive oil 2 minutes per side until pink; transfer to a plate.', 'Melt the butter with the garlic and red pepper flakes 1 minute.', 'Return the shrimp with the pasta, lemon juice and a splash of pasta water; toss 1 minute.', 'Finish with parsley and serve.']::text[], 'https://images.unsplash.com/photo-1781086917723-dbe2d7ef85dc', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-creamy-shrimp-pasta-with-parsley-abi8eXOlUUg', true),
  ('garlic-herb-drumsticks-green-beans', 'Garlic Herb Drumsticks with Green Beans', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 45, false, 'Crispy oven-roasted drumsticks rubbed with garlic, paprika and herbs, with buttery lemon green beans.', array['Heat the oven to {425F} and line a sheet pan with foil. Pat the drumsticks dry with paper towels so the skin crisps.', 'Toss the drumsticks on the pan with the olive oil, garlic powder, paprika, Italian seasoning, pepper and most of the salt until evenly coated, then space them apart.', 'Roast 35 to 40 minutes, turning once halfway, until the skin is crisp and the juices run clear when you pierce the meat near the bone ({165F}).', 'About 10 minutes before the chicken is done, bring a pot of water to a boil over high heat. Add the trimmed green beans and cook 5 minutes until bright green and tender but still snappy, then drain.', 'Return the pot to low heat and melt the butter with the minced garlic for 30 seconds, then toss in the beans with the juice of the lemon and the remaining salt.', 'Serve the drumsticks with the green beans.']::text[], 'https://images.unsplash.com/photo-1588767768106-1b20e51d9d68', 'Ekaterina Novitskaya', 'https://unsplash.com/photos/fried-chicken-on-clear-glass-plate-jMKxaakIKfQ', true),
  ('ginger-beef-broccoli-stir-fry', 'Ginger Beef & Broccoli Stir-Fry', 'dinner', array['dairy_free', 'keto', 'low_carb']::text[], 4, 20, false, 'Seared sirloin with broccoli, green beans and bell pepper in a garlic, ginger and soy sauce; no rice required.', array['Cut the steak across the grain into thin bite-size slices and toss with a third of the soy sauce. Cut the broccoli into small florets, trim the green beans, cut the bell pepper into chunks, mince the garlic and grate the ginger.', 'Heat the vegetable oil in a large skillet or wok over high heat until it just starts to smoke. Add the beef in one layer and sear 2 to 3 minutes, turning once, until browned outside but still a little pink inside; move it to a plate.', 'Add the broccoli, green beans and bell pepper to the same pan with a splash of water and stir-fry over high heat 5 minutes until bright and tender but still crisp.', 'Add the garlic and ginger and stir 30 seconds until fragrant.', 'Return the beef and its juices, pour in the remaining soy sauce and the sesame oil and toss 1 minute until glossy and hot.']::text[], 'https://images.unsplash.com/photo-1760504526069-ff0f8bf6e4ca', 'Davis Dai', 'https://unsplash.com/photos/beef-and-broccoli-stir-fry-with-vegetables-on-a-red-plate-qKPKDb4_W24', true),
  ('ginger-scallion-chicken', 'Ginger Scallion Chicken', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 30, false, 'Poached-style skillet chicken with a bright ginger-scallion sauce over rice.', array['Cook the rice according to the package directions.', 'Season the chicken with salt and sear in hot oil 4 minutes per side until cooked through; let it rest, then slice.', 'Combine the ginger, green onion, soy sauce, sesame oil and vinegar in a heatproof bowl.', 'Heat 2 tablespoons of oil until shimmering and pour it carefully over the ginger mixture — it will sizzle.', 'Serve the sliced chicken over rice, spooned with the ginger sauce.']::text[], 'https://images.unsplash.com/photo-1787691684812-365ed2c7daf4', 'Unsplash contributor', 'https://unsplash.com/photos/cook-preparing-street-food-in-shanghai-rJHnZX2FH9s', true),
  ('gnocchi-pesto', 'Gnocchi with Pesto', 'dinner', array['vegetarian']::text[], 4, 15, false, 'Pillowy gnocchi tossed in basil pesto with cherry tomatoes and parmesan.', array['Boil the gnocchi in salted water; they float when done, about 2 to 3 minutes.', 'Sauté the cherry tomatoes in olive oil 3 minutes until they slump.', 'Toss the gnocchi with the pesto and a splash of the cooking water until glossy.', 'Add the tomatoes and serve with parmesan on top.']::text[], 'https://images.unsplash.com/photo-1786918518069-5794f204a520', 'Unsplash contributor', 'https://unsplash.com/photos/caprese-salad-stack-with-pesto-UNxf3gqxs7s', true),
  ('greek-chicken-bowls', 'Greek Chicken Bowls', 'dinner', array['gluten_free', 'high_protein']::text[], 4, 30, true, 'Lemon-oregano chicken over rice with cucumber, tomato, olives and feta.', array['Cook the rice according to the package directions.', 'Toss the chicken with the olive oil, lemon juice, oregano, garlic and salt; rest 10 minutes.', 'Sear in a hot skillet 5 to 6 minutes until golden and cooked through; slice.', 'Serve over rice with cucumber, tomato, olives, feta and a drizzle of olive oil.']::text[], 'https://images.unsplash.com/photo-1782177261793-823b94aa0555', 'Unsplash contributor', 'https://unsplash.com/photos/outdoor-table-with-breakfast-fresh-fruit-and-iced-coffee-0jVZkTGmRNs', true),
  ('greek-chicken-rice-bowls-with-tzatziki', 'Greek Chicken Rice Bowls with Tzatziki', 'lunch', array['high_protein', 'gluten_free']::text[], 4, 30, true, 'Lemon-oregano chicken over rice with cucumber, tomato, red onion, feta and a quick yogurt tzatziki.', array['Put the rice in a medium pot with twice its volume of water and a pinch of the salt, bring to a boil over high heat, cover, turn the heat to low and cook 15 minutes, until the water is absorbed. Leave covered off the heat.', 'Cut the chicken into bite-size pieces. Mince the garlic. Toss the chicken with half of the olive oil, half of the lemon juice, the oregano, half of the garlic, the pepper and most of the remaining salt.', 'Grate half of the cucumber, squeeze out the water with your hands and stir it into the yogurt with the remaining garlic, lemon juice and salt to make the tzatziki.', 'Dice the rest of the cucumber and the tomatoes, and thinly slice the onion.', 'Heat the remaining olive oil in a large skillet over medium-high heat, add the chicken in one layer and cook 6 to 8 minutes, turning once or twice, until browned and cooked through ({165F}).', 'Divide the rice among four bowls and top with the chicken, cucumber, tomato, onion, crumbled feta and a large spoonful of tzatziki.']::text[], 'https://images.unsplash.com/photo-1593787614841-5d53fca8a33d', 'Louis Hansel', 'https://unsplash.com/photos/brown-wooden-tray-with-food-ZK63tYsvyM8', true),
  ('greek-chickpea-salad', 'Greek Chickpea Salad', 'lunch', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 15, true, 'Chickpeas tossed with cucumber, tomato, red onion in a lemon-oregano dressing.', array['Drain the chickpeas in a sieve, rinse under cold water and shake dry.', 'Dice the cucumber and the tomatoes into pieces about the size of a chickpea, and slice the red onion as thinly as you can.', 'Squeeze the lemon into a large bowl, catching the seeds. Add the olive oil, oregano, salt and pepper and whisk with a fork until blended.', 'Add the chickpeas, cucumber, tomatoes and onion and toss until everything is coated.', 'Pour over the dressing and fold gently so everything is coated.', 'Let the salad stand 5 minutes for the flavors to blend, then serve; or refrigerate in a sealed container up to 4 days.']::text[], 'https://images.unsplash.com/photo-1688923130941-889a41f4439c', 'Imad 786', 'https://unsplash.com/photos/a-bowl-of-food-with-a-spoon-in-it-nFkC9zJv0pk', true),
  ('greek-chickpea-salad-pitas', 'Greek Chickpea Salad with Warm Pita', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 15, false, 'Chickpeas, cucumber, tomatoes and feta in a lemon oregano dressing over romaine with warm pita.', array['In a large bowl, whisk the oil, the juice of the lemon, oregano, salt and pepper until blended.', 'Add the drained chickpeas, cucumber, halved tomatoes and red onion and toss until everything is coated.', 'Gently fold in the feta so it stays in pieces.', 'Warm the pitas one at a time in a dry skillet over medium heat, about 1 minute per side, until soft and lightly toasted, then cut them into wedges.', 'Divide the chopped romaine among plates, spoon the salad over it and serve with the warm pita.']::text[], 'https://images.unsplash.com/photo-1568803776598-57e3cf2f90fc', 'dimitri.photography', 'https://unsplash.com/photos/sliced-vegetable-dish-JDP_yzauSYg', true),
  ('greek-lemon-potatoes-chicken', 'Greek Lemon Potatoes and Chicken', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 60, true, 'Chicken thighs roasted over lemon-oregano potatoes — a taverna classic.', array['Heat the oven to {400F}.', 'Toss the potato wedges with the olive oil, lemon juice, oregano, garlic and salt in a baking dish.', 'Season the chicken with salt and nestle it on top of the potatoes.', 'Roast 45 to 50 minutes until the chicken is browned and the potatoes are tender and glazed.', 'Serve with the pan juices spooned over.']::text[], 'https://images.unsplash.com/photo-1782174177294-872d77096f77', 'Unsplash contributor', 'https://unsplash.com/photos/sunset-dinner-table-with-food-by-the-water-in-fira-tZSOcPXsA8s', true),
  ('greek-turkey-pitas', 'Greek Turkey Pitas', 'dinner', array['high_protein']::text[], 4, 25, false, 'Spiced ground turkey in warm pitas with cucumber-yogurt sauce and salad.', array['Stir the yogurt with half the garlic, the lemon juice, cucumber and a pinch of salt for the sauce.', 'Cook the turkey in hot oil 6 minutes, breaking it up; add the remaining garlic, cumin, oregano and salt and cook 2 minutes.', 'Warm the pitas 20 seconds per side in a dry skillet.', 'Fill each pita with turkey, sauce, tomato and onion.']::text[], 'https://images.unsplash.com/photo-1777716003985-68fed08d0c7e', 'Unsplash contributor', 'https://unsplash.com/photos/a-platter-of-grilled-meats-with-rice-and-pita-bread-2j17J8psiTw', true),
  ('greek-yogurt-alfredo-penne-peas', 'Greek Yogurt Alfredo Penne with Peas', 'dinner', array['high_protein', 'pescatarian', 'vegetarian']::text[], 4, 25, false, 'Penne and peas in a creamy garlic parmesan sauce made with Greek yogurt instead of cream.', array['Bring a large pot of water to a boil over high heat and cook the penne as the package says, until tender but still firm to the bite.', 'Add the frozen peas to the pot for the last 2 minutes of cooking.', 'Scoop out a mugful of the cooking water, then drain the pasta and peas.', 'Melt the butter in the empty pot over low heat and cook the garlic 1 minute, until fragrant but not browned.', 'Take the pot off the heat and whisk in the yogurt, milk, parmesan, salt and pepper until smooth; the yogurt curdles if it boils.', 'Add the pasta and peas and toss, adding cooking water a splash at a time, until the sauce is creamy and coats the penne. Serve right away.']::text[], 'https://images.unsplash.com/photo-1625128726788-3fee36746aaa', 'Bakd&Raw by Karolin Baitinger', 'https://unsplash.com/photos/sliced-cucumber-on-white-ceramic-plate-4MX7xLAiWBc', true),
  ('grilled-cheese-with-tomato-soup', 'Grilled Cheese with Tomato Soup', 'lunch', array['pescatarian', 'vegetarian']::text[], 4, 30, false, 'Buttery griddled cheese sandwiches with a quick creamy tomato soup for dunking.', array['Dice the onion and mince the garlic. Heat the olive oil in a medium pot over medium heat and cook the onion 4 minutes, stirring, until soft; add the garlic and stir 30 seconds.', 'Add the crushed tomatoes, broth, Italian seasoning, salt and pepper. Bring to a boil over high heat, then turn down to medium-low and simmer 10 minutes, stirring now and then, until slightly thickened.', 'While the soup simmers, butter one side of each bread slice. Sandwich two slices of cheese between each pair of bread slices, buttered sides facing out.', 'Heat a large skillet over medium-low heat. Cook the sandwiches two at a time, about 3 minutes per side, pressing lightly with a spatula, until deep golden and the cheese has melted. Repeat with the rest.', 'Take the soup off the heat. For a smooth soup, blend it in the pot with an immersion blender if you have one; otherwise mash it with a potato masher and leave it rustic.', 'Stir the cream into the soup and warm it 1 minute over low heat without letting it boil.', 'Cut the sandwiches in half and serve with bowls of soup for dunking.']::text[], 'https://images.unsplash.com/photo-1762647420988-5080acf33988', 'David Trinks', 'https://unsplash.com/photos/tomato-soup-with-grilled-cheese-sandwich-kF2DHADo9Bo', true),
  ('ground-beef-shepherds-pie', 'Ground Beef Shepherd''s Pie', 'dinner', array['high_protein']::text[], 4, 60, true, 'Ground beef, carrots and peas in a rich gravy, baked under a golden layer of buttery mashed potatoes.', array['Heat the oven to {400F}. Cover the potatoes with cold salted water in a pot, bring to a boil and cook for 15 minutes until they fall apart when pierced with a fork.', 'Drain the potatoes and mash them with the butter, milk and half of the salt until smooth.', 'While the potatoes cook, brown the ground beef with the onion and carrot in a large skillet over medium-high heat for 8 minutes, breaking up the meat, then spoon off most of the fat.', 'Add the garlic, tomato paste, thyme and flour and stir for 1 minute.', 'Pour in the broth and Worcestershire sauce, add the rest of the salt and the pepper and simmer for 5 minutes until the gravy thickens, then stir in the peas.', 'Spread the beef mixture in a large baking dish, spoon the mashed potatoes on top and rough up the surface with a fork.', 'Bake for 20 to 25 minutes until the filling bubbles at the edges and the potato peaks are golden, then rest for 5 minutes before serving.']::text[], 'https://images.unsplash.com/photo-1696935257293-9ec4f03074a1', 'The Fry Family Food Co.', 'https://unsplash.com/photos/a-casserole-dish-on-a-plate-with-a-fork-next-to-it-LHr6EN-B8NQ', true),
  ('ground-beef-tacos-with-lime-cabbage-slaw', 'Ground Beef Tacos with Lime Cabbage Slaw', 'dinner', array['gluten_free']::text[], 4, 20, false, 'Seasoned ground beef in warm corn tortillas, topped with a crunchy lime cabbage slaw, cheddar and salsa.', array['Toss the shredded cabbage with the lime juice, cilantro and salt in a bowl and set it aside to soften while you cook.', 'Heat a large skillet over medium-high heat, add the ground beef and cook 6 to 8 minutes, breaking it up with a spoon, until no pink remains.', 'Tilt the pan and spoon off most of the fat.', 'Stir in the taco seasoning and half a cup of water, lower the heat to medium and simmer 3 minutes until the sauce thickens and coats the meat.', 'While the beef simmers, warm the tortillas a few at a time in a second, dry skillet over medium-high heat, about 20 seconds per side, until soft and lightly toasted; keep them wrapped in a clean towel.', 'Fill each tortilla with beef, slaw, cheddar and salsa and serve right away.']::text[], 'https://images.unsplash.com/photo-1690874684451-92358e91b14c', 'Max Griss', 'https://unsplash.com/photos/three-tacos-on-a-plate-with-limes-and-cilantro-ZAW0C46XvSo', true),
  ('ground-turkey-egg-roll-bowls', 'Ground Turkey Egg Roll Bowls', 'lunch', array['dairy_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 20, true, 'All the flavor of an egg roll without the wrapper: turkey and cabbage stir-fried with ginger, garlic and soy.', array['Mince the garlic, peel and mince the ginger, and thinly slice the green onions, setting aside a handful of the green tops for serving.', 'Heat the vegetable oil in a large, deep skillet or wok over medium-high heat until it shimmers.', 'Add the turkey and cook 6 minutes, breaking it into small crumbles, until browned with no pink left ({165F}).', 'Stir in the garlic and ginger and cook 1 minute, until fragrant.', 'Add the coleslaw mix and the soy sauce and cook 4 minutes, tossing constantly, until the cabbage has wilted but still has some crunch.', 'Take off the heat and stir in the sesame oil and the sliced green onions.', 'Divide among bowls or containers, top with the reserved green onion tops and drizzle with the sriracha.']::text[], 'https://images.unsplash.com/photo-1630409350018-0e06ea178b92', 'Mario Raj', 'https://unsplash.com/photos/vegetable-salad-on-white-ceramic-plate-UhwdAcjk_zo', true),
  ('ground-turkey-teriyaki-rice-bowls', 'Ground Turkey Teriyaki Rice Bowls', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 25, false, 'Ground turkey, broccoli and carrots in a homemade honey-soy teriyaki sauce over rice.', array['Put the rice in a medium pot with twice its volume of water, bring to a boil over high heat, then cover and cook on low 15 minutes until the water is absorbed; leave it covered off the heat.', 'Whisk the soy sauce, honey, rice vinegar, cornstarch, ground ginger and a third of a cup of water in a small bowl until smooth.', 'Heat the oil in a large skillet over medium-high heat and cook the turkey 6 minutes, breaking it up, until browned with no pink left.', 'Add the garlic, carrots and broccoli, cover and cook 5 minutes, stirring once, until the carrots are crisp-tender.', 'Pour in the sauce and simmer 2 minutes, stirring, until thick and glossy.', 'Spoon over the fluffed rice and top with the green onions.']::text[], 'https://images.unsplash.com/photo-1791386804677-815379da3e2e', 'Travis Palma', 'https://unsplash.com/photos/teriyaki-chicken-bowl-with-rice-vtTqQJ0hfZc', true),
  ('ham-and-white-bean-soup', 'Ham and White Bean Soup', 'dinner', array['dairy_free']::text[], 4, 35, true, 'Diced ham and cannellini beans simmered with carrot, celery and thyme into a thick, comforting soup.', array['Heat the oil in a large pot over medium heat and cook the onion, carrot and celery for 7 minutes until soft.', 'Add the ham, garlic and thyme and cook for 2 minutes, stirring, until the ham starts to brown.', 'Add the beans, broth and pepper and bring to a boil over high heat.', 'Lower the heat and simmer uncovered for 15 minutes until the carrots are tender.', 'Mash about a quarter of the beans against the side of the pot so the broth turns creamy.', 'Taste before adding any salt, since the ham is salty, then stir in the parsley and serve with the bread.']::text[], 'https://images.unsplash.com/photo-1698917467449-08bcd1d9014b', 'David de Andrés Martín', 'https://unsplash.com/photos/a-white-plate-topped-with-a-stew-of-beans-and-meat-9iJPST6E1-M', true),
  ('ham-cheddar-egg-muffin-cups', 'Ham and Cheddar Egg Muffin Cups', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 35, true, 'Baked egg cups with ham, cheddar and bell pepper: twelve from one muffin tin for the week.', array['Heat the oven to {375F} with a rack in the middle. Grease the cups of a 12-cup muffin tin generously with the butter, sides included, so the eggs release.', 'Dice the ham and the bell pepper small and thinly slice the green onions.', 'Divide the ham, bell pepper, green onions and cheddar evenly among the cups.', 'Beat the eggs with the salt and pepper in a bowl or a jug until smooth, then pour over the fillings, filling each cup about three quarters full.', 'Bake 18 to 20 minutes, until puffed and set in the center, with no liquid egg showing when you press the top.', 'Cool 5 minutes (they sink a little), run a knife around each cup and lift them out.', 'Serve warm, or cool completely and refrigerate in a sealed container up to 4 days.']::text[], 'https://images.unsplash.com/photo-1518310532637-f5225f94f3c3', 'Kaitlyn Chow', 'https://unsplash.com/photos/grilled-patties-with-tomato-toppings-tIElrLKqdjo', true),
  ('ham-hash-brown-casserole', 'Ham and Cheddar Hash Brown Casserole', 'dinner', array['gluten_free']::text[], 6, 65, true, 'Shredded hash browns baked with diced ham, cheddar, sour cream and onion until golden and crisp at the edges.', array['Heat the oven to {375F}. Put the butter in a large baking dish and set it in the oven for 3 to 4 minutes until melted.', 'In a large bowl stir together the sour cream, milk, garlic powder, salt and pepper.', 'Add the hash browns, ham, onion and two thirds of the cheddar, pour in most of the melted butter and mix until evenly coated.', 'Tilt the baking dish so the remaining butter coats it, then spread the mixture in the dish and top with the rest of the cheddar.', 'Bake uncovered for 45 to 50 minutes until the center is bubbling and the edges are deep golden and crisp.', 'Rest for 5 minutes, then scatter the green onion over the top and serve.']::text[], 'https://images.unsplash.com/photo-1645453014403-4ad5170a386c', 'Some Tale', 'https://unsplash.com/photos/a-casserole-dish-with-cheese-and-parsley-lqRfdLcZm_w', true),
  ('hamburger-vegetable-soup', 'Hamburger Vegetable Soup', 'dinner', array['dairy_free', 'gluten_free']::text[], 6, 45, true, 'Ground beef, potatoes and mixed vegetables in a tomato-beef broth: a big, cheap pot that feeds everyone.', array['Brown the ground beef with the onion and celery in a large pot over medium-high heat for 8 minutes, breaking up the meat, until no pink remains, then spoon off most of the fat.', 'Add the garlic, tomato paste and Italian seasoning and stir for 1 minute until the paste darkens.', 'Add the potatoes, tomatoes with their juice, broth, Worcestershire sauce, salt and pepper and bring to a boil over high heat.', 'Lower the heat, cover and simmer for 15 minutes until the potatoes are almost tender.', 'Stir in the frozen vegetables and simmer uncovered for 8 to 10 minutes until everything is tender.', 'Taste, adjust the salt and serve.']::text[], 'https://images.unsplash.com/photo-1611068120813-eca5a8cbf793', 'Nathan Dumlao', 'https://unsplash.com/photos/soup-in-white-ceramic-bowl-5eROVOJW2bA', true),
  ('hoisin-chicken-lettuce-wraps', 'Hoisin Chicken Lettuce Wraps', 'dinner', array['dairy_free', 'low_carb', 'high_protein']::text[], 4, 25, false, 'Savory ground chicken with hoisin and water-crisp vegetables, served in crunchy lettuce cups.', array['Heat the oil in a large skillet over medium-high heat and cook the chicken 5 to 6 minutes, breaking it up, until browned.', 'Add the garlic, ginger and carrot; cook 3 minutes until the carrot softens.', 'Stir in the hoisin, soy sauce and vinegar and cook 1 minute until glossy.', 'Spoon the filling into lettuce leaves and top with green onion and peanuts.']::text[], 'https://images.unsplash.com/photo-1787273670681-b1886c2807a3', 'Unsplash contributor', 'https://unsplash.com/photos/fried-spring-rolls-on-plate-5L-7s-OSjlo', true),
  ('homestyle-chicken-noodle-soup', 'Homestyle Chicken Noodle Soup', 'dinner', '{}'::text[], 4, 45, true, 'Chicken thighs simmered with carrots, celery and onion in broth, finished with egg noodles and parsley.', array['Melt the butter in a large pot over medium heat and cook the onion, carrots and celery 5 minutes, stirring, until the onion is soft.', 'Stir in the garlic and thyme for 30 seconds, then add the broth and the chicken thighs.', 'Bring to a boil over high heat, then cover and simmer on low 15 minutes until the chicken is {165F} and no longer pink in the center.', 'Lift the chicken onto a plate, shred it with two forks and return it to the pot.', 'Raise the heat to medium-high, add the egg noodles and cook 6 to 8 minutes until tender.', 'Season with the salt and pepper, stir in the parsley and serve.']::text[], 'https://images.unsplash.com/photo-1612966948332-81d747414a8f', 'Karolina Kołodziejczak', 'https://unsplash.com/photos/soup-in-white-ceramic-bowl--m0du_taY4g', true),
  ('honey-garlic-chicken-thighs-with-rice', 'Honey Garlic Chicken Thighs with Rice', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 25, false, 'Seared chicken thighs glazed in honey, garlic and soy sauce, served with rice and steamed broccoli.', array['Put the rice in a medium pot with twice its volume of water, bring to a boil over high heat, then cover and cook on low 15 minutes until the water is absorbed; leave it covered off the heat.', 'Pat the chicken dry and season both sides with the salt and pepper.', 'Heat the oil in a large skillet over medium-high heat and sear the chicken 5 to 6 minutes per side until deep golden and {165F} in the thickest part.', 'Stir together the honey, soy sauce, vinegar and garlic, lower the heat to medium and pour the mixture over the chicken.', 'Simmer 3 to 4 minutes, turning the chicken, until the glaze is thick and sticky.', 'Meanwhile, put the broccoli in a small pot with a splash of water, cover and steam over medium heat 4 to 5 minutes until hot and bright green, then drain.', 'Serve the chicken over the fluffed rice with the broccoli and spoon the extra glaze on top.']::text[], 'https://images.unsplash.com/photo-1583579366395-c0a857d2182a', 'Markus Winkler', 'https://unsplash.com/photos/cooked-food-on-white-ceramic-plate-8U3MxqPEmJI', true),
  ('honey-garlic-salmon-rice-broccoli', 'Honey Garlic Salmon with Rice & Broccoli', 'dinner', array['dairy_free', 'high_protein', 'pescatarian']::text[], 4, 25, false, 'Pan-seared salmon glazed with honey, garlic and soy, served with fluffy white rice and steamed broccoli.', array['Put the rice in a pot with twice its volume of water. Bring to a boil over high heat, then cover, turn the heat to low and cook 15 minutes until the water is absorbed; leave it covered off the heat until serving.', 'Cut the broccoli into florets and mince the garlic. Stir the honey, soy sauce and garlic together in a small bowl.', 'Heat the oil in a large skillet over medium-high heat. Pat the salmon dry, lay it in the pan skin side up and cook 4 minutes until golden underneath, then flip and cook 3 minutes more.', 'Lower the heat to medium-low, pour in the honey mixture and spoon it over the fish 1 to 2 minutes, until it thickens into a glossy glaze and the salmon flakes easily with a fork.', 'Meanwhile put the broccoli in a pot with a splash of water, cover and steam over medium-high heat 4 to 5 minutes until bright green and a knife slides into the stems.', 'Fluff the rice with a fork and serve it with the salmon and broccoli, drizzled with the glaze from the pan.']::text[], 'https://images.unsplash.com/photo-1675209705883-7aec595f5aa8', 'Camara Negra', 'https://unsplash.com/photos/a-black-plate-topped-with-salmon-and-broccoli-RZV1-tNbHy4', true),
  ('honey-sesame-chicken-stir-fry', 'Honey Sesame Chicken Stir-Fry', 'dinner', array['high_protein', 'dairy_free']::text[], 4, 30, false, 'Crispy chicken bites tossed in a glossy honey-soy sauce with broccoli, served over rice with sesame seeds.', array['Cook the rice according to the package directions and keep it warm.', 'Toss the chicken pieces with the cornstarch, salt and pepper until evenly coated.', 'Heat the oil in a large skillet over medium-high heat and cook the chicken 6 to 8 minutes until golden and cooked through; transfer to a plate.', 'Stir-fry the broccoli in the same pan 3 minutes with a splash of water until crisp-tender.', 'Return the chicken, add the soy sauce, honey, vinegar, garlic and ginger, and toss 2 minutes until the sauce coats everything.', 'Serve over rice, drizzled with sesame oil and sprinkled with sesame seeds.']::text[], 'https://images.unsplash.com/photo-1788601299617-3052a7c8fa70', 'Unsplash contributor', 'https://unsplash.com/photos/noodles-with-vegetables-in-black-bowl-t2XScZ1IGH0', true),
  ('huevos-a-la-mexicana', 'Huevos a la Mexicana', 'breakfast', array['dairy_free', 'gluten_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 2, 15, false, 'Soft scrambled eggs cooked with sautéed tomato, onion and jalapeño, served with sliced avocado.', array['Dice the onion and the tomatoes, seed and finely chop the jalapeño, and chop the cilantro. Beat the eggs with half of the salt.', 'Heat the oil in a large nonstick skillet over medium heat and cook the onion and jalapeño 3 minutes, until soft and translucent.', 'Add the tomatoes and the remaining salt and cook 3 minutes, until they break down and most of their juice has evaporated.', 'Lower the heat to medium-low, pour in the eggs and let them sit 20 seconds.', 'Stir gently with a spatula 2 to 3 minutes, until large soft curds form and no liquid egg remains.', 'Take off the heat, sprinkle with the cilantro and serve with the sliced avocado.']::text[], 'https://images.unsplash.com/photo-1740313498464-971eb7d2066d', 'Markus Winkler', 'https://unsplash.com/photos/a-pot-of-food-sitting-on-top-of-a-wooden-table-tFdtuDNNc7A', true),
  ('hummus-veggie-pita-pockets', 'Hummus Veggie Pita Pockets', 'lunch', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 2, 10, false, 'Warm pita halves spread with hummus and stuffed with spinach, cucumber, tomato, and carrot.', array['Wash the vegetables. Thinly slice the cucumber and the tomato, and peel the carrot and shred it on the large holes of a grater.', 'If you like the pitas warm, heat them 30 seconds per side in a dry skillet over medium heat, or 15 seconds in the microwave, until soft and flexible.', 'Cut each pita in half and gently open the pockets with your fingers, taking care not to tear them.', 'Spread the hummus over the inside of each pocket.', 'Fill each pocket with the spinach first, then the cucumber, tomato and carrot.', 'Serve right away, or wrap tightly and keep cold for up to 4 hours.']::text[], 'https://images.unsplash.com/photo-1534352211968-8d25dbe0e951', 'Alexandra Golovac', 'https://unsplash.com/photos/vegetable-sandwich-MAbhhj3QCXQ', true),
  ('hungarian-beef-goulash', 'Hungarian Beef Goulash with Egg Noodles', 'dinner', array['high_protein']::text[], 4, 140, true, 'Beef slowly braised with plenty of onion and sweet paprika until fork-tender, served over buttered egg noodles.', array['Pat the beef dry and season it with half of the salt and the pepper. Heat the oil in a heavy pot over medium-high heat and brown the beef in two batches, 5 minutes per batch, until dark on two sides; set it aside on a plate.', 'Lower the heat to medium, add the onions and cook for 10 minutes, stirring and scraping the bottom, until soft and golden.', 'Add the garlic, bell pepper and tomato paste and stir for 2 minutes.', 'Take the pot off the heat, stir in the paprika so it does not scorch, then pour in the broth and return the beef with its juices and the rest of the salt.', 'Bring to a boil, then cover and cook over low heat for 1 hour 30 minutes to 1 hour 45 minutes, stirring now and then, until the beef falls apart when pressed with a fork.', 'Uncover and simmer for 10 minutes to thicken the sauce while you boil the egg noodles in salted water until tender; drain and toss them with the butter.', 'Serve the goulash over the noodles with a spoonful of sour cream.']::text[], 'https://images.unsplash.com/photo-1551889579-8acb3f14a917', 'Michael Uebler', 'https://unsplash.com/photos/stew-in-white-and-blue-ceramic-bowl-LERjH8KPTco', true),
  ('italian-sausage-and-pepper-penne', 'Italian Sausage and Pepper Penne', 'dinner', '{}'::text[], 4, 25, false, 'Penne with browned Italian sausage, sweet bell peppers and onion in a garlicky tomato sauce.', array['Bring a large pot of water to a boil over high heat, add the salt and cook the penne for the time on the package, usually 10 to 12 minutes, until tender but still firm.', 'Scoop out about half a cup of the pasta water, then drain the penne.', 'Meanwhile, heat the oil in a large skillet over medium-high heat and cook the sausage 6 minutes, breaking it into bite-size pieces, until browned with no pink left.', 'Add the peppers and onion and cook 5 minutes, stirring, until soft and lightly browned at the edges.', 'Stir in the garlic, Italian seasoning and diced tomatoes with their juice, lower the heat to medium and simmer 5 minutes until slightly thickened.', 'Add the penne and a splash of the pasta water, toss 1 minute until the sauce clings to the pasta, and serve topped with the parmesan.']::text[], 'https://images.unsplash.com/photo-1621996346565-e3dbc646d9a9', 'Ben Lei', 'https://unsplash.com/photos/penne-pasta-with-meat-sauce-flFd8L7_B3g', true),
  ('italian-sausage-zucchini-pepper-skillet', 'Italian Sausage, Zucchini & Pepper Skillet', 'dinner', array['gluten_free', 'keto', 'low_carb']::text[], 4, 30, true, 'Browned Italian sausage with zucchini, bell peppers and onion in one skillet; it reheats well for lunches.', array['Slice the sausage into thick coins (it is easier while the sausage is very cold). Cut the zucchini into half-moons and the bell peppers into strips, slice the onion and mince the garlic.', 'Heat the olive oil in a large skillet over medium-high heat. Add the sausage and cook 6 to 8 minutes, turning the pieces, until browned on both sides.', 'Add the onion and bell peppers and cook 5 minutes, stirring, until they start to soften.', 'Add the zucchini, garlic, Italian seasoning and pepper flakes and lower the heat to medium.', 'Cook 6 to 8 minutes, stirring now and then, until the vegetables are tender and the sausage shows no pink in the center.', 'Sprinkle with the parmesan and serve.']::text[], 'https://images.unsplash.com/photo-1698843813577-db28459556b0', 'Elena Leya', 'https://unsplash.com/photos/a-pan-filled-with-food-sitting-on-top-of-a-table-H-D-0UOgzMc', true),
  ('italian-veggie-pasta-salad', 'Italian Veggie Pasta Salad', 'lunch', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 25, true, 'Penne tossed with tomatoes, cucumber, bell pepper in a tangy Italian vinaigrette.', array['Bring a large pot of water to a rolling boil over high heat, about 8 minutes, and add a generous pinch of salt.', 'Add the penne and cook for the time on the package, usually 10 to 12 minutes, stirring now and then, until tender but still firm when you bite a piece.', 'While the pasta cooks, halve the cherry tomatoes, dice the cucumber and the bell pepper, and slice the red onion as thinly as you can.', 'In a large bowl, whisk the olive oil, vinegar, Italian seasoning, garlic powder, salt and pepper until blended.', 'Drain the pasta and rinse it under cold water for 1 minute, tossing, until completely cool. Shake off the water well.', 'Add the pasta and vegetables to the bowl and toss until everything is coated with the dressing.', 'Serve now, or cover and refrigerate up to 4 days; stir before serving.']::text[], 'https://images.unsplash.com/photo-1630492782892-74f99406dc59', 'engin akyurt', 'https://unsplash.com/photos/pasta-dish-on-white-ceramic-bowl-X4QCAodTlh0', true),
  ('jalapeno-popper-chicken-casserole', 'Jalapeño Popper Chicken Casserole', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 50, true, 'Chicken breasts baked under a cream cheese, cheddar and jalapeño topping with crisp bacon.', array['Heat the oven to {400F}. Lay the bacon on a foil-lined sheet pan and bake for 12 to 15 minutes until crisp, then drain on paper towels and crumble.', 'Slice each chicken breast in half horizontally into two thin cutlets, season both sides with the salt, pepper, garlic powder and onion powder and arrange in one layer in a large baking dish.', 'Halve the jalapeños, scrape out the seeds for less heat and dice them.', 'Mix the cream cheese with half of the cheddar and most of the jalapeños and spread it over the chicken.', 'Sprinkle with the rest of the cheddar, the bacon and the remaining jalapeños.', 'Bake for 22 to 25 minutes until the cheese is golden and the thickest piece of chicken reaches {165F} or shows no pink when cut.', 'Rest for 5 minutes, then serve with the green onion on top.']::text[], 'https://images.unsplash.com/photo-1719317607191-4161a7c9eeff', 'Alina Chernysheva', 'https://unsplash.com/photos/a-plate-of-food-on-a-table-next-to-a-bowl-of-food-xAPVmaNqvMg', true),
  ('kimchi-fried-rice', 'Kimchi-Style Fried Rice', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 20, true, 'Spicy-sour fried rice with quick-pickled cabbage standing in for kimchi.', array['Toss the cabbage with the vinegar, half the sugar and a pinch of salt; squeeze it gently and set aside 10 minutes.', 'Stir-fry the onion and carrot in hot oil 3 minutes.', 'Add the rice and the cabbage with its juices; fry 4 minutes until hot and a little crisp at the edges.', 'Stir in the gochujang, soy sauce and remaining sugar; toss 2 minutes.', 'Serve with a fried egg on top if you like, and green onion.']::text[], 'https://images.unsplash.com/photo-1771384552858-feb0574f958d', 'Unsplash contributor', 'https://unsplash.com/photos/a-delicious-meal-of-grilled-salmon-with-rice-and-vegetables-fahnPDK0GQA', true),
  ('king-ranch-chicken-casserole', 'King Ranch Chicken Casserole', 'dinner', array['high_protein']::text[], 6, 60, true, 'Texas casserole of shredded chicken, corn tortillas, tomatoes and green chiles in a creamy sauce under melted cheddar.', array['Heat the oven to {375F}. Pull the meat off the chicken, discard the skin and bones and shred the meat.', 'Melt the butter in a large skillet over medium heat and cook the onion and bell pepper for 6 minutes until soft, then add the garlic, chili powder and cumin and stir for 1 minute.', 'Sprinkle in the flour, stir for 1 minute, then pour in the broth while stirring and simmer for 3 minutes until thickened.', 'Take the skillet off the heat and stir in the tomatoes with their juice, the green chiles, sour cream, salt and shredded chicken.', 'Tear the tortillas into quarters and cover the bottom of a large baking dish with a third of them.', 'Spread a third of the chicken mixture on top, sprinkle with a third of the cheddar, and repeat twice more, ending with cheddar.', 'Bake for 25 to 30 minutes until bubbling at the edges and golden on top, then rest for 10 minutes before cutting.']::text[], 'https://images.unsplash.com/photo-1586032340735-01a5bc5495e9', 'micheile henderson', 'https://unsplash.com/photos/brown-and-black-round-plate-with-food-d-MYIZBu44c', true),
  ('korean-style-beef-bowls', 'Korean-Style Beef Bowls', 'dinner', array['high_protein', 'dairy_free']::text[], 4, 25, true, 'Ground beef in a quick bulgogi-style sauce with cucumber kimchi over rice.', array['Cook the rice according to the package directions.', 'Toss the cucumber with the vinegar, half the sugar and a pinch of salt; set aside.', 'Heat the oil in a large skillet over high heat and cook the beef 5 to 6 minutes, breaking it up, until browned.', 'Stir in the soy sauce, gochujang, remaining sugar, garlic and ginger and cook 2 minutes until glossy.', 'Serve over rice with the cucumber and green onion, drizzled with sesame oil.']::text[], 'https://images.unsplash.com/photo-1635363638580-c2809d049eee', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-food-with-a-spoon-in-it-w_2vlvTgk7E', true),
  ('korean-style-beef-rice-bowls', 'Korean-Style Ground Beef Rice Bowls', 'lunch', array['dairy_free', 'high_protein']::text[], 4, 30, true, 'Ground beef glazed with soy, garlic, ginger and brown sugar over rice, with a fried egg and quick-pickled cucumber.', array['Put the rice in a medium pot with twice its volume of water, bring to a boil over high heat, cover, turn the heat to low and cook 15 minutes, until the water is absorbed. Leave covered off the heat.', 'Thinly slice the cucumber and toss it with the rice vinegar and a pinch of the salt. Mince the garlic and ginger and slice the green onions.', 'Stir the soy sauce, brown sugar, sesame oil and red pepper flakes together in a cup.', 'Brown the beef in a large skillet over medium-high heat 6 to 7 minutes, breaking it up, until no pink remains and the edges crisp. Spoon off the excess fat.', 'Add the garlic and ginger and stir 30 seconds, until fragrant, then pour in the soy mixture and simmer 2 minutes, until glossy and mostly absorbed.', 'Heat the vegetable oil in a nonstick skillet over medium heat and fry the eggs 3 minutes, until the whites are set.', 'Divide the rice among four bowls and top with the beef, an egg, the cucumber and the green onions.']::text[], 'https://images.unsplash.com/photo-1706288586306-b40e8fd3c711', 'Jason Leung', 'https://unsplash.com/photos/a-plate-of-rice-cucumbers-and-meat-on-a-table-VsSLnEO2Jxo', true),
  ('lasagna-soup', 'Lasagna Soup', 'dinner', array['high_protein']::text[], 4, 40, true, 'Italian sausage and broken lasagna noodles in a tomato broth, topped with cottage cheese, mozzarella and parmesan.', array['Squeeze the sausage out of its casings into a large pot over medium-high heat and cook with the onion for 7 to 8 minutes, breaking it up, until browned with no pink left.', 'Spoon off most of the fat, add the garlic, tomato paste, Italian seasoning and red pepper flakes and stir for 1 minute until the paste darkens.', 'Add the crushed tomatoes, broth and salt and bring to a boil over high heat.', 'Break the lasagna noodles into bite-size pieces, stir them in and cook at a steady simmer over medium heat for 12 to 14 minutes, stirring often so they do not stick, until tender.', 'Meanwhile mix the cottage cheese with the parmesan in a small bowl.', 'Ladle the soup into bowls, add a big spoonful of the cottage cheese mixture and sprinkle with the mozzarella so it melts on top.']::text[], 'https://images.unsplash.com/photo-1680420572234-1acdf5b8fb89', 'Corryn Burtenshaw', 'https://unsplash.com/photos/a-bowl-of-pasta-soup-with-a-spoon-in-it-gw83j8eNPg4', true),
  ('lemon-chicken-orzo', 'Lemon Chicken Orzo', 'dinner', array['high_protein']::text[], 4, 30, false, 'One-pan orzo with chicken, lemon, spinach and feta.', array['Season the chicken with salt and sear in hot olive oil 4 minutes per side until golden; set aside.', 'Toast the orzo in the same pan 2 minutes, add the garlic and cook 30 seconds.', 'Pour in the broth and simmer 8 minutes, stirring, until the orzo is tender.', 'Return the chicken to the pan, stir in the lemon juice, spinach and feta and cook 2 minutes until the chicken is cooked through; slice and serve on top.']::text[], 'https://images.unsplash.com/photo-1757972367438-581ad5e299f5', 'Unsplash contributor', 'https://unsplash.com/photos/creamy-gnocchi-with-chicken-and-herbs-JQMGHY9KLFU', true),
  ('lemon-chicken-thigh-potato-bake', 'Lemon Chicken Thigh & Potato Bake', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 45, false, 'Chicken thighs roasted in one dish with potatoes, cherry tomatoes, garlic, oregano and lemon slices.', array['Heat the oven to {425F}. Cut the potatoes into bite-size chunks (no need to peel them), smash the garlic cloves with the flat of a knife, slice the lemons and chop the parsley.', 'In a large baking dish toss the potatoes, cherry tomatoes and garlic with half the olive oil, half the oregano and half the salt.', 'Rub the chicken with the pepper and the remaining oil, oregano and salt and nestle it on top of the vegetables in one layer.', 'Tuck the lemon slices around the chicken and roast 35 minutes, until the chicken is browned and cooked through ({165F}) and a knife slides easily into the potatoes.', 'Spoon the juices from the dish over everything and scatter with the parsley.']::text[], 'https://images.unsplash.com/photo-1680098021573-b9402ee336ec', 'Babs Gorniak', 'https://unsplash.com/photos/two-bowls-of-food-with-lemons-meat-and-vegetables-xgDsiUC5p-w', true),
  ('lemon-garlic-cod', 'Lemon Garlic Cod', 'dinner', array['pescatarian', 'gluten_free', 'dairy_free', 'high_protein']::text[], 4, 25, false, 'Cod fillets baked with lemon, garlic and olives — light and fast.', array['Heat the oven to {400F} and line a sheet pan with parchment.', 'Arrange the cod on the pan, drizzle with olive oil and top with the garlic, lemon slices and olives.', 'Season with salt and bake 12 to 14 minutes until the fish flakes.', 'Serve over rice with the pan juices and parsley.']::text[], 'https://images.unsplash.com/photo-1707056503922-91c9ebaf0774', 'Unsplash contributor', 'https://unsplash.com/photos/a-pan-filled-with-meat-and-vegetables-next-to-garlic-nLdvS9zn4x4', true),
  ('lemon-garlic-tuna-pasta', 'Lemon Garlic Tuna Pasta', 'dinner', array['high_protein', 'pescatarian']::text[], 4, 20, false, 'Pantry pasta with canned tuna, peas, garlic, lemon and parmesan that comes together while the water boils.', array['Bring a large pot of water to a boil over high heat. Meanwhile mince the garlic, slice the green onions, drain the tuna and juice the lemon.', 'Add the pasta to the boiling water and cook for the time on the package, about 8 minutes, until tender but still firm to the bite; add the peas for the last 2 minutes.', 'Scoop out a mugful of the cooking water, then drain the pasta and peas.', 'Return the empty pot to medium-low heat, add the olive oil, garlic and pepper flakes and cook 1 minute until the garlic smells sweet but has not browned.', 'Add the tuna, pasta, peas, lemon juice and a splash of the cooking water and toss 1 minute until glossy, adding more water if it looks dry.', 'Take the pot off the heat and stir in the parmesan, salt and green onions.']::text[], 'https://images.unsplash.com/photo-1666724283327-a9cd945fd5c5', 'Danielle Townsend', 'https://unsplash.com/photos/a-plate-of-food-qzyzPxeKiRA', true),
  ('lemongrass-style-chicken', 'Lemongrass-Style Chicken Thighs', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 30, false, 'Caramelized chicken thighs with a fragrant garlic-lime-soy marinade.', array['Whisk the soy sauce, sugar, fish sauce, lime juice, garlic, ginger and turmeric into a marinade; toss with the chicken and rest 10 minutes.', 'Cook the rice according to the package directions.', 'Heat the oil in a large skillet over medium-high heat and cook the chicken 6 to 7 minutes, letting the marinade caramelize into browned bits.', 'Serve over rice with cucumber and cilantro.']::text[], 'https://images.unsplash.com/photo-1617636423451-0db0119c14cd', 'Unsplash contributor', 'https://unsplash.com/photos/roasted-chicken-on-brown-wooden-chopping-board-lUPk_iciOA4', true),
  ('lemony-lentil-vegetable-soup', 'Lemony Lentil Vegetable Soup', 'lunch', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 45, true, 'A thick lentil soup with carrots, celery and tomatoes, brightened with lemon; reheats well all week.', array['Dice the onion, carrots and celery into small, even pieces and mince the garlic. Rinse the lentils in a sieve and pick out any small stones.', 'Heat the olive oil in a large pot over medium heat. Add the onion, carrots and celery and cook 6 minutes, stirring now and then, until softened and the onion is translucent.', 'Stir in the garlic and cumin and cook 30 seconds, until fragrant.', 'Add the lentils, the tomatoes with their juice, the broth, half as much water as broth, the salt and the pepper. Turn the heat to high and bring to a boil.', 'Turn the heat down to low, cover with the lid slightly ajar and simmer 25 minutes, stirring once or twice, until the lentils are tender and the soup has thickened.', 'Take the pot off the heat, squeeze the lemon and stir in the juice. Taste and add a pinch more salt if needed.', 'Ladle into bowls and serve hot.']::text[], 'https://images.unsplash.com/photo-1552298013-de2af4b94854', 'Steve Tsang', 'https://unsplash.com/photos/soup-in-maroon-ceramic-pot-MP_A0OK_O60', true),
  ('lentil-bolognese-spaghetti', 'Lentil Bolognese with Spaghetti', 'dinner', array['dairy_free', 'high_protein', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 50, true, 'A thick tomato and lentil ragu with carrot and celery tossed with spaghetti.', array['Heat the oil in a large pot over medium heat and cook the onion, carrot and celery for 6 minutes, stirring, until soft.', 'Stir in the garlic, tomato paste and Italian seasoning and cook 1 minute, until the paste darkens.', 'Add the rinsed lentils, crushed tomatoes, broth, salt and pepper and bring to a boil over high heat.', 'Lower to medium-low, cover and simmer 30 minutes, stirring every 10 minutes, until the lentils are tender and the sauce is thick; add a splash of water if it starts to stick.', 'When the sauce has 15 minutes left, bring a large pot of water to a boil over high heat and cook the spaghetti as the package says, until tender but still firm to the bite.', 'Scoop out a mugful of the cooking water, then drain the spaghetti.', 'Toss the spaghetti with the sauce over low heat for 1 minute, adding cooking water a splash at a time until the sauce clings to the noodles.', 'Serve with a crack of black pepper.']::text[], 'https://images.unsplash.com/photo-1562370345-d64b69d8f824', 'Paula Hayes', 'https://unsplash.com/photos/cooked-pasta-SbLAg_zzDuI', true),
  ('lentils-and-rice-with-caramelized-onions', 'Lentils and Rice with Caramelized Onions', 'lunch', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 50, true, 'Mujadara: cumin-scented lentils and rice cooked together and topped with deeply browned onions.', array['Rinse the lentils, put them in a medium pot with plenty of water, bring to a boil and simmer over medium heat 12 minutes, until just starting to soften but still firm. Drain.', 'Meanwhile, halve and thinly slice the onions. Heat the olive oil in a large pot over medium-high heat, add the onions with a pinch of the salt and cook 20 minutes, stirring often and lowering the heat to medium if they scorch, until deep brown and crisp at the edges.', 'Lift half of the onions onto a plate for the topping. Stir the cumin and the rice into the onions left in the pot for 1 minute.', 'Add the drained lentils, the remaining salt, the pepper and 2 cups (480 ml) of water. Bring to a boil, cover, turn the heat to low and cook 17 minutes, until the rice is tender and the water is absorbed.', 'Take off the heat and leave covered 5 minutes, then fluff with a fork.', 'Serve topped with the reserved onions, the chopped parsley.']::text[], 'https://images.unsplash.com/photo-1601214533705-9f24a51b1c2e', 'Nvr Endng Anupam', 'https://unsplash.com/photos/stainless-steel-spoon-on-white-ceramic-plate-WeBNnRbIdKA', true),
  ('lettuce-wrap-cheeseburgers', 'Lettuce-Wrap Cheeseburgers', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 20, false, 'Juicy skillet cheeseburgers wrapped in crisp lettuce with tomato, onion and a quick burger sauce.', array['Mix the beef with the garlic powder, salt and pepper with your hands just until combined, then shape it into 4 flat patties a little wider than your palm.', 'Slice the tomato and onion, separate the largest lettuce leaves, and stir the mayo and mustard together for the sauce.', 'Heat a large skillet over medium-high heat for 2 minutes; no oil is needed because the beef releases its own fat.', 'Cook the patties 4 minutes without moving them until a dark crust forms, then flip and cook 3 to 4 minutes more until no pink remains in the center ({160F}).', 'Lay a cheese slice on each patty, cover the skillet and cook 1 minute until the cheese melts.', 'Stack 2 lettuce leaves per burger, add the patty, tomato, onion and a spoonful of sauce, and fold the leaves around it.']::text[], 'https://images.unsplash.com/photo-1764018601476-e5fac1f27893', 'Barcello''s fusion', 'https://unsplash.com/photos/a-lettuce-wrapped-burger-with-tomato-and-onion-rMs9zl7Ckuc', true),
  ('loaded-baked-potato-soup', 'Loaded Baked Potato Soup', 'dinner', '{}'::text[], 4, 45, true, 'Thick potato soup with bacon, cheddar, sour cream and green onion, like a loaded baked potato in a bowl.', array['Cook the bacon in a large pot over medium heat for 8 minutes, stirring, until crisp; lift it out onto paper towels and leave a thin layer of fat in the pot.', 'Add the butter and onion to the pot and cook for 5 minutes until soft, then add the garlic and stir for 30 seconds.', 'Sprinkle in the flour and stir for 1 minute, then pour in the broth and milk little by little while whisking so no lumps form.', 'Add the potatoes, salt and pepper, bring to a boil over high heat, then lower the heat and simmer for 15 to 20 minutes, stirring now and then, until the potatoes are very tender.', 'Mash about half of the potatoes in the pot with a potato masher so the soup is thick but still chunky.', 'Take the pot off the heat and stir in the sour cream and most of the cheddar until melted.', 'Serve topped with the bacon, green onion and the rest of the cheddar.']::text[], 'https://images.unsplash.com/photo-1612815160130-ff641f5bf967', 'Nathan Dumlao', 'https://unsplash.com/photos/person-holding-white-ceramic-bowl-with-soup-0dqLSBDEcdg', true),
  ('meal-prep-chicken-burrito-bowls', 'Meal-Prep Chicken Burrito Bowls', 'lunch', array['high_protein', 'gluten_free']::text[], 4, 30, true, 'Taco-seasoned chicken thighs over rice with black beans, corn, salsa and cheddar, packed for four lunches.', array['Rinse the rice in a sieve until the water runs almost clear. Put it in a pot with twice its volume of water and bring to a boil over high heat.', 'Cover, turn the heat down to low and cook 15 minutes without lifting the lid, until the water is absorbed. Take off the heat, let stand covered 5 minutes and fluff with a fork.', 'While the rice cooks, cut the chicken into bite-size pieces and toss them with the taco seasoning until coated.', 'Heat the oil in a large skillet over medium-high heat until it shimmers. Add the chicken in one layer and cook 8 minutes, stirring every 2 minutes, until browned and cooked through: {165F} inside, with no pink in the largest piece. Move to a plate.', 'Drain and rinse the beans. Add them and the corn to the same skillet over medium heat and cook 3 minutes, stirring and scraping up the browned bits, until hot.', 'Divide the rice among containers, one per serving, and top with the chicken, the beans and corn, the salsa and the cheddar.', 'Cut the lime into wedges and squeeze them over the bowls, or pack a wedge in each one. Cool, cover and refrigerate up to 4 days.']::text[], 'https://images.unsplash.com/photo-1668665771757-4d42737d295a', 'Andrew Relf', 'https://unsplash.com/photos/a-plate-of-food-iku1zhSNRU8', true),
  ('mediterranean-chickpea-bowls', 'Mediterranean Chickpea Bowls', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 25, true, 'Warm spiced chickpeas over rice with cucumber, tomato, olives and tahini drizzle.', array['Cook the rice according to the package directions.', 'Whisk the tahini with the lemon juice, half the garlic, 3 tablespoons of water and a pinch of salt into a drizzle.', 'Warm the chickpeas in olive oil with the cumin, paprika and remaining garlic 5 minutes until coated.', 'Serve over rice with cucumber, tomato, olives and the tahini drizzle.']::text[], 'https://images.unsplash.com/photo-1680405531955-8b4981bb1b0c', 'Unsplash contributor', 'https://unsplash.com/photos/a-white-bowl-filled-with-food-on-top-of-a-wooden-table-V3OnqusloQE', true),
  ('mexican-street-corn-chicken', 'Elote-Style Chicken Skillet', 'dinner', array['gluten_free', 'high_protein']::text[], 4, 30, false, 'Chicken with charred corn, lime, cotija-style cheese and chili in one skillet.', array['Heat the oil in a large skillet over high heat and char the corn 5 minutes until browned in spots; transfer to a bowl.', 'Season the chicken with salt and chili powder, sear 4 minutes per side until cooked through; slice.', 'Toss the corn with the sour cream, feta, lime juice and cilantro.', 'Serve the sliced chicken topped with the street corn.']::text[], 'https://images.unsplash.com/photo-1787084888948-a57fd00fff47', 'Unsplash contributor', 'https://unsplash.com/photos/man-serving-herbal-drinks-in-hoi-an-7snnYIQSLbo', true),
  ('microwave-baked-potatoes', 'Microwave Loaded Baked Potatoes', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 20, false, 'Fluffy baked potatoes in 12 minutes, loaded with cheese, broccoli and sour cream.', array['Pierce the potatoes all over with a fork and microwave 10 to 12 minutes, turning halfway, until a knife slides in easily.', 'Split them open and fluff the insides with a fork.', 'Top with the butter, cheddar and warmed broccoli; microwave 1 minute more to melt.', 'Finish with sour cream, green onion and salt.']::text[], 'https://images.unsplash.com/photo-1761315414483-54b8e53fa44d', 'Unsplash contributor', 'https://unsplash.com/photos/roasted-potatoes-with-herbs-and-skewers-eW-d8O6a-DM', true),
  ('microwave-mug-meals', 'Microwave Egg Fried Rice Mug', 'dinner', array['dairy_free']::text[], 4, 15, false, 'Leftover rice turned into a hot lunch with an egg and frozen veg — all microwave.', array['Microwave the frozen vegetables 2 minutes in a large bowl.', 'Add the rice, soy sauce and sesame oil; stir and microwave 2 more minutes.', 'Push the rice to the sides, crack the eggs into the center and stir them in.', 'Microwave 1 to 2 minutes more until the egg sets; serve with green onion.']::text[], 'https://images.unsplash.com/photo-1723691802798-fa6efc67b2c9', 'Unsplash contributor', 'https://unsplash.com/photos/a-plate-of-rice-and-peas-on-a-stove-42UmsPkOETM', true),
  ('microwave-salmon-cups', 'Microwave Lemon Rice with Salmon', 'dinner', array['pescatarian', 'gluten_free', 'dairy_free', 'high_protein']::text[], 4, 20, false, 'Steamed salmon over lemon rice — the whole meal cooks in the microwave.', array['Microwave the rice with 2.5 cups of water and a pinch of salt, covered, 12 minutes until tender; rest 5.', 'Season the salmon with salt, garlic powder and lemon slices on top; place it over the rice.', 'Cover and microwave 4 to 5 minutes until the salmon flakes.', 'Fluff the rice with the lemon juice and serve the salmon on top.']::text[], 'https://images.unsplash.com/photo-1591814468924-caf88d1232e1', 'Unsplash contributor', 'https://unsplash.com/photos/white-ceramic-bowl-with-rice-and-sliced-lemon-GXhmQt6MFX8', true),
  ('milanesa-chicken', 'Crispy Chicken Milanesa', 'dinner', array['high_protein']::text[], 4, 30, false, 'Breaded chicken cutlets, shallow-fried golden, with lime and a quick salad.', array['Season the chicken with salt and garlic powder; pound to even thickness if thick.', 'Set up two plates: beaten egg on one, breadcrumbs mixed with a pinch of salt on the other.', 'Dip each piece in egg, then breadcrumbs, pressing so it sticks.', 'Fry in hot oil 3 to 4 minutes per side until deep golden and cooked through; drain on paper.', 'Serve with lime wedges and the tomato salad.']::text[], 'https://images.unsplash.com/photo-1788603907419-c4cac479edc0', 'Unsplash contributor', 'https://unsplash.com/photos/fried-rice-with-vegetables-dinner-aLRcLRJdro4', true),
  ('minestrone-easy', 'Easy Minestrone', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 40, true, 'A hearty tomato-bean-vegetable soup with small pasta.', array['Sauté the onion, carrot and celery in olive oil 6 minutes until soft, add the garlic and cook 1 minute.', 'Add the tomatoes, broth, beans, oregano and a pinch of salt; simmer 15 minutes.', 'Add the pasta and cook 8 minutes until tender.', 'Stir in the spinach until it wilts, season and serve.']::text[], 'https://images.unsplash.com/photo-1725483990685-820291c0fca1', 'Unsplash contributor', 'https://unsplash.com/photos/a-pot-of-vegetable-soup-sitting-on-a-stove-top-TDKvBUSkcTs', true),
  ('miso-glazed-salmon', 'Miso-Glazed Salmon', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 25, false, 'Broiled salmon with a sweet miso glaze, served with rice and cucumbers.', array['Stir the miso, brown sugar, vinegar and soy sauce into a glaze in a small bowl.', 'Place the salmon on a lined baking sheet, brush with half the glaze and let it sit 5 minutes.', 'Broil 5 to 7 minutes, brushing once more with glaze, until the salmon flakes and the top is caramelized.', 'Serve over rice with the cucumber dressed in a little rice vinegar.']::text[], 'https://images.unsplash.com/photo-1780805664262-c0845e033149', 'Unsplash contributor', 'https://unsplash.com/photos/fresh-poke-bowl-and-sushi-rolls-on-a-dark-counter-WSOEjfTZwQY', true),
  ('molletes-with-pico-de-gallo', 'Molletes with Pico de Gallo', 'breakfast', array['pescatarian', 'vegetarian']::text[], 4, 20, false, 'Mexican open-faced toasts: buttered bread spread with refried beans, covered in melted cheese and fresh pico.', array['Heat the oven to {425F}. Dice the tomatoes, finely chop the onion, jalapeño and cilantro, and mix them with the lime juice and half of the salt to make the pico de gallo.', 'Cut the bread in half crosswise, then split each piece lengthwise to make 4 pieces. Butter the cut sides and set them cut-side up on a sheet pan.', 'Bake 5 minutes, until lightly toasted at the edges.', 'Stir the beans with the remaining salt to loosen them, spread them thickly over each piece all the way to the edges and cover with the mozzarella.', 'Bake 6 to 8 minutes more, until the beans are hot and the cheese is bubbling and starting to brown.', 'Spoon the pico de gallo over the top and serve right away.']::text[], 'https://images.unsplash.com/photo-1722239311914-973d8f206074', 'Alimentos Fotogénicos', 'https://unsplash.com/photos/a-piece-of-cake-sitting-on-top-of-a-white-plate-lhwRcyUCuaQ', true),
  ('mongolian-beef-noodles', 'Mongolian Beef Noodles', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 30, false, 'Crisp-edged beef and noodles in a sweet soy-garlic glaze.', array['Cook the noodles according to the package directions, drain and rinse.', 'Toss the beef with the cornstarch and let it sit 5 minutes.', 'Heat the oil in a large skillet over high heat and sear the beef 3 to 4 minutes until crisp at the edges; transfer to a plate.', 'Stir the soy sauce, brown sugar, garlic, ginger and half a cup of water, add to the pan and simmer 2 minutes.', 'Return the beef and add the noodles, toss until coated and serve with green onion.']::text[], 'https://images.unsplash.com/photo-1780246330541-f4e329c5b588', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-stir-fried-noodles-and-a-chocolate-milkshake-b_zDR-OuCcQ', true),
  ('monte-cristo-sandwiches', 'Monte Cristo Sandwiches', 'breakfast', array['high_protein']::text[], 2, 15, false, 'Ham, turkey and cheese sandwiches dipped in egg and pan-fried like French toast until golden and melted.', array['Spread the mustard on two slices of bread. Layer each with a slice of cheese, the ham and the turkey, close with the remaining bread and press firmly.', 'Whisk the eggs, milk and salt in a shallow dish until no streaks remain.', 'Melt the butter in a large nonstick skillet over medium-low heat.', 'Dip each sandwich in the egg mixture about 10 seconds per side, letting the excess drip back into the dish.', 'Cook the sandwiches 3 to 4 minutes per side, until deep golden and the cheese has melted; lower the heat if the bread browns too fast.', 'Cut each sandwich in half on the diagonal and serve hot.']::text[], 'https://images.unsplash.com/photo-1670403474909-90849aa25834', 'sehoon ye', 'https://unsplash.com/photos/a-tray-of-food-VIp_q7wNjZk', true),
  ('moroccan-style-chickpea-stew', 'Moroccan-Style Chickpea Stew', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 40, true, 'Chickpeas, sweet potato and spinach stewed in a tomato broth spiced with cumin, cinnamon and paprika, over rice.', array['Rinse the rice, put it in a small pot with twice its volume of water and a pinch of salt, bring to a boil, then cover and cook over low heat for 18 minutes until tender.', 'Heat the oil in a large pot over medium heat and cook the onion for 5 minutes until soft.', 'Add the garlic, cumin, cinnamon and smoked paprika and stir for 1 minute until fragrant.', 'Add the sweet potato, carrot, chickpeas, tomatoes with their juice, broth and salt and bring to a boil over high heat.', 'Lower the heat, cover and simmer for 20 minutes until a knife slides easily into the sweet potato.', 'Stir in the spinach and cook for 2 minutes until wilted, then squeeze in the lemon juice.', 'Taste, adjust the salt and serve over the rice.']::text[], 'https://images.unsplash.com/photo-1708782343809-0050c38b3a1a', 'Rimsha Noor', 'https://unsplash.com/photos/a-bowl-of-stew-with-a-spoon-and-spoons-next-to-it-ON36i-YCFTM', true),
  ('mushroom-spinach-cheddar-omelets', 'Mushroom Spinach Cheddar Omelets', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 2, 15, false, 'Three-egg omelets folded around sauteed mushrooms, wilted spinach and melted cheddar.', array['Wipe the mushrooms clean and slice them. Crack the eggs into a bowl, add the salt and pepper and beat with a fork for 30 seconds, until no streaks of white remain.', 'Melt half of the butter in a nonstick skillet over medium-high heat. Add the mushrooms in one layer and cook 4 minutes, stirring once or twice, until browned and their liquid has cooked off.', 'Add the spinach and stir about 1 minute, until just wilted. Move the vegetables to a plate and wipe out the skillet.', 'Turn the heat down to medium, melt half of the remaining butter and pour in half of the eggs.', 'Cook about 2 minutes, lifting the cooked edges with a spatula and tilting the skillet so the raw egg runs underneath, until the top is just set but still glossy.', 'Spoon half of the vegetables and half of the cheddar over one side, fold the other side over and cook 30 seconds more, until the cheese starts to melt. Slide onto a plate.', 'Make the second omelet the same way with the remaining butter, eggs, vegetables and cheddar.']::text[], 'https://images.unsplash.com/photo-1677844592730-ce9c936d8f1a', 'Bakd&Raw by Karolin Baitinger', 'https://unsplash.com/photos/a-white-plate-topped-with-an-omelet-and-greens-SCZP5rvZINk', true),
  ('mushroom-stroganoff-egg-noodles', 'Mushroom Stroganoff with Egg Noodles', 'dinner', array['dairy_free', 'pescatarian', 'vegetarian']::text[], 4, 30, false, 'Browned mushrooms in a creamy coconut sauce over egg noodles.', array['Bring a large pot of water to a boil over high heat, cook the egg noodles as the package says until tender, and drain.', 'Meanwhile, warm the olive oil in a large skillet over medium-high heat and cook the mushrooms 8 minutes, stirring only now and then, until their liquid cooks off and they are deep brown.', 'Add the onion and cook 4 minutes, until soft.', 'Stir in the garlic, paprika and thyme for 1 minute, then sprinkle in the flour and stir 30 seconds, until no dry flour shows.', 'Pour in the broth, soy sauce and mustard, stirring, and simmer over medium heat for 5 minutes, until the sauce coats the back of a spoon.', 'Take the skillet off the heat and stir in the coconut milk, salt and pepper; do not boil it again, or the coconut milk can separate.', 'Spoon over the noodles and sprinkle with the parsley.']::text[], 'https://images.unsplash.com/photo-1611608927216-ca294fa86bee', 'Vladimir Gladkov', 'https://unsplash.com/photos/pasta-dish-on-white-ceramic-plate-ioXOnu-furc', true),
  ('new-england-fish-chowder', 'New England Fish Chowder', 'dinner', '{}'::text[], 4, 40, true, 'Chunks of cod and potato in a milky broth flavored with bacon, onion and thyme.', array['Cook the bacon in a large pot over medium heat for 8 minutes, stirring, until crisp; lift it out onto paper towels and leave the fat in the pot.', 'Add the butter, onion and celery and cook for 6 minutes until soft, then add the thyme and flour and stir for 1 minute.', 'Pour in the broth little by little while stirring, then add the potatoes, salt and pepper and bring to a boil over high heat.', 'Lower the heat, cover and simmer for 12 to 15 minutes until the potatoes are tender when pierced with a fork.', 'Stir in the milk and cream and heat until steaming but not boiling, then lay the cod pieces in the pot.', 'Cook over low heat for 5 to 7 minutes without stirring hard, until the fish turns white and flakes easily with a fork.', 'Serve sprinkled with the bacon and parsley.']::text[], 'https://images.unsplash.com/photo-1652408414631-f09eae7cc1db', 'Alexey Demidov', 'https://unsplash.com/photos/a-bowl-of-food-GpKTnnfnM50', true),
  ('one-pan-chicken-thighs-and-rice-with-peas', 'One-Pan Chicken Thighs and Rice with Peas', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 40, false, 'Paprika chicken thighs cooked on top of garlicky rice in one pan, finished with sweet peas.', array['Pat the chicken dry and season both sides with the paprika, thyme, pepper and half the salt.', 'Heat the oil in a large deep skillet with a lid over medium-high heat and sear the chicken 3 minutes per side until golden, then move it to a plate; it finishes cooking later.', 'Lower the heat to medium, melt the butter in the same pan and cook the onion 4 minutes until soft.', 'Stir in the garlic and rice and cook 1 minute until the rice smells toasty.', 'Pour in the broth with the remaining salt, scrape up the browned bits from the bottom and bring to a boil over high heat.', 'Nestle the chicken on top, cover, lower the heat to low and simmer 18 to 20 minutes until the rice is tender, the liquid is absorbed and the chicken reaches {165F}.', 'Scatter the peas over the top, cover 3 minutes until they are hot and bright green, then fluff the rice and serve.']::text[], 'https://images.unsplash.com/photo-1577110633798-8d4439305952', 'Faris Mohammed', 'https://unsplash.com/photos/frying-pan-of-chicken-O8OZsmNWSsg', true),
  ('one-pot-beef-penne-skillet', 'One-Pot Beef & Penne Skillet', 'dinner', array['high_protein']::text[], 4, 25, false, 'Penne cooked right in a ground beef and tomato sauce, then finished with melted mozzarella and parmesan.', array['Dice the onion and mince the garlic.', 'Heat a large deep skillet over medium-high heat. Add the beef and onion and cook 6 minutes, breaking up the meat, until it is browned and the onion is soft; spoon off the extra fat if there is a lot.', 'Stir in the garlic and Italian seasoning and cook 30 seconds until fragrant.', 'Add the crushed tomatoes, broth, salt and dry penne, stir so the pasta is covered by liquid and bring to a boil.', 'Cover, lower the heat to medium-low and simmer 12 to 14 minutes, stirring twice so nothing sticks, until the pasta is tender and the sauce has thickened.', 'Take the skillet off the heat, stir in the mozzarella until it melts and sprinkle with the parmesan.']::text[], 'https://images.unsplash.com/photo-1630151318557-1b2b20cc8cff', 'Konstantinas Ladauskas', 'https://unsplash.com/photos/pasta-dish-on-white-ceramic-bowl-OCccmmmZxhU', true),
  ('one-pot-turkey-taco-rice', 'One-Pot Turkey Taco Rice', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 30, false, 'Ground turkey, rice, black beans and corn simmered in salsa and taco seasoning, finished with melted cheddar.', array['Heat a large deep skillet or pot over medium-high heat and cook the turkey with the onion 6 minutes, breaking up the meat, until no pink remains and the onion is soft.', 'Stir in the taco seasoning and rice and cook 1 minute until the rice is coated.', 'Add the salsa, broth, black beans and corn and bring to a boil over high heat.', 'Cover, lower the heat to low and simmer 18 minutes without lifting the lid, until the rice is tender and the liquid is absorbed.', 'Sprinkle the cheddar over the top, cover 2 minutes until melted, and serve.']::text[], 'https://images.unsplash.com/photo-1512058533999-106ee01bf777', 'Annie Spratt', 'https://unsplash.com/photos/black-frying-pan-with-food-on-top-x-R8jcm2ors', true),
  ('orange-chicken', 'Easy Orange Chicken', 'dinner', array['dairy_free']::text[], 4, 35, false, 'Crispy chicken tossed in a sticky orange glaze with rice and steamed broccoli.', array['Cook the rice according to the package directions.', 'Toss the chicken with the cornstarch and a pinch of salt until coated.', 'Whisk the soy sauce, sugar, vinegar, garlic and ginger with the juice squeezed from the lime (or an orange if you have one).', 'Heat the oil in a large skillet over medium-high heat and cook the chicken 7 minutes until golden and cooked through.', 'Pour in the sauce and toss 2 minutes until thick and sticky.', 'Serve over rice with broccoli and green onion.']::text[], 'https://images.unsplash.com/photo-1758979690131-11e2aa0b142b', 'Unsplash contributor', 'https://unsplash.com/photos/chicken-stir-fry-with-noodles-and-vegetables-in-a-bowl-kTROrGtnm7U', true),
  ('pan-seared-pork-chops-buttered-cabbage', 'Pan-Seared Pork Chops with Buttered Cabbage', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 25, false, 'Paprika-rubbed pork chops seared until golden and served over cabbage wilted in butter, garlic and a splash of vinegar.', array['Mix the smoked paprika, garlic powder, thyme, salt and pepper and rub the mix over both sides of the chops. Thinly slice the cabbage and onion and mince the garlic.', 'Heat the olive oil in a large skillet over medium-high heat until it shimmers. Sear the chops 4 to 5 minutes per side until deep golden and just firm ({145F} inside), then rest them on a plate.', 'Lower the heat to medium, melt the butter in the same pan and cook the onion 2 minutes, scraping up the browned bits.', 'Add the cabbage and garlic and cook 6 to 8 minutes, tossing often, until the cabbage is tender and lightly browned.', 'Stir in the vinegar and the juices from the plate of chops.', 'Serve the chops over the cabbage.']::text[], 'https://images.unsplash.com/photo-1612871689527-2a6145cc9e86', 'Junior REIS', 'https://unsplash.com/photos/fried-food-on-white-ceramic-plate-G3giNPjjB18', true),
  ('parmesan-crusted-cod-green-beans', 'Parmesan-Crusted Cod with Green Beans', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian']::text[], 4, 25, false, 'Cod fillets baked under a golden parmesan crust next to garlicky roasted green beans.', array['Heat the oven to {425F}. Trim the ends off the green beans and cut the lemon into wedges.', 'Toss the green beans on a large sheet pan with the olive oil, half the garlic powder and half the salt; spread them out and roast 8 minutes.', 'Meanwhile pat the thawed cod dry and season it with the remaining salt. Mix the parmesan with the paprika and the remaining garlic powder.', 'Spread the mayo over the top of each fillet and press the parmesan mixture onto it.', 'Push the beans aside, add the cod to the pan and bake 12 minutes until the crust is golden and the fish flakes easily with a fork.', 'Serve with the lemon wedges.']::text[], 'https://images.unsplash.com/photo-1595936126366-6e85b4812ca2', 'Edward Howell', 'https://unsplash.com/photos/fried-fish-with-green-vegetable-on-white-ceramic-bowl-mvlWXqxjaJ4', true),
  ('pasta-aglio-olio-broccoli', 'Pasta Aglio e Olio with Broccoli', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 20, false, 'Garlic-oil spaghetti with chili flakes and roasted-flavored broccoli.', array['Cook the spaghetti in salted water; save a cup of the water before draining.', 'Sear the broccoli in olive oil 5 minutes until charred at the edges; set aside.', 'Warm the garlic and red pepper flakes in the remaining oil 1 minute until golden.', 'Toss in the pasta and broccoli with a splash of pasta water; serve with more pepper flakes.']::text[], 'https://images.unsplash.com/photo-1770351203577-501cf0b074f9', 'Unsplash contributor', 'https://unsplash.com/photos/two-servings-of-macaroni-and-cheese-with-salad-JtQBpcam1hQ', true),
  ('pasta-e-fagioli', 'Pasta e Fagioli', 'dinner', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 40, true, 'Thick Italian soup of white beans, small pasta and vegetables in a tomato broth, finished with a drizzle of olive oil.', array['Heat the oil in a large pot over medium heat and cook the onion, carrot and celery for 8 minutes, stirring now and then, until soft.', 'Add the garlic, tomato paste and Italian seasoning and stir for 2 minutes until the paste darkens.', 'Mash one can of the beans with a fork, then add both the mashed and the whole beans, the tomatoes with their juice, the broth and the salt.', 'Bring to a boil over high heat, then lower the heat and simmer for 10 minutes.', 'Stir in the macaroni and cook for 8 to 10 minutes, stirring often so it does not stick, until the pasta is tender and the soup is thick.', 'Season with the pepper, let it rest off the heat for 5 minutes and serve.']::text[], 'https://images.unsplash.com/photo-1715702397057-2f7eebc86f2b', 'Jovan Vasiljević', 'https://unsplash.com/photos/a-woman-sitting-at-a-table-with-a-bowl-of-soup-fcOaa6j4cUo', true),
  ('pastel-de-choclo', 'Corn and Beef Pie', 'dinner', array['high_protein']::text[], 4, 60, true, 'Sweet corn topping over cumin beef, baked until golden — a South American classic.', array['Sauté the onion in hot oil 4 minutes, add the beef and cook 6 minutes until browned; stir in the cumin, paprika and salt and set aside.', 'Blend the corn with the cream until mostly smooth, season with salt.', 'Heat the oven to {375F} and butter a baking dish.', 'Spread the beef in the dish, scatter the olives and egg slices over it, then pour the corn mixture on top.', 'Bake 35 minutes until golden and set; rest 10 minutes before serving.']::text[], 'https://images.unsplash.com/photo-1792354441702-572e1ffaca2b', 'Unsplash contributor', 'https://unsplash.com/photos/lasagna-in-glass-baking-dish-RvAmjTUTx5U', true),
  ('peanut-butter-banana-oatmeal', 'Peanut Butter Banana Oatmeal', 'breakfast', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 2, 10, false, 'Creamy stovetop oats cooked in oat milk, topped with sliced banana and a spoonful of peanut butter.', array['Pour the oat milk into a small pot with the same amount of water and the salt. Bring to a gentle simmer over medium heat, about 3 minutes, until small bubbles form around the edge.', 'Stir in the oats and cinnamon and turn the heat down to medium-low.', 'Cook 5 minutes, stirring often so the bottom does not catch, until the oats are soft and the porridge is thick and creamy.', 'While the oats cook, peel and slice the bananas.', 'Take the pot off the heat and let it stand 1 minute; stir in a splash of oat milk or water if it is thicker than you like.', 'Divide between bowls, top with the banana slices and a spoonful of peanut butter, and serve hot.']::text[], 'https://images.unsplash.com/photo-1599450307683-16b29464da5c', 'Lucie Rangel', 'https://unsplash.com/photos/red-strawberries-on-white-ceramic-plate-vdvzWVw6YKw', true),
  ('peanut-chicken-noodles', 'Peanut Chicken Noodles', 'dinner', array['high_protein', 'dairy_free']::text[], 4, 25, false, 'Noodles and chicken in a creamy peanut-lime sauce with crunchy vegetables.', array['Cook the noodles according to the package directions, drain and rinse.', 'Whisk the peanut butter, soy sauce, lime juice, sugar and a quarter cup of warm water into a sauce.', 'Heat the oil in a large skillet over medium-high heat and cook the chicken 6 minutes until cooked through.', 'Add the vegetables and stir-fry 3 minutes until crisp-tender.', 'Add the noodles and sauce, toss 2 minutes until coated and hot, then serve with peanuts and cilantro.']::text[], 'https://images.unsplash.com/photo-1783196736270-d08d63485303', 'Unsplash contributor', 'https://unsplash.com/photos/a-plate-of-shrimp-noodles-with-red-bell-peppers-0HHs0Etbq24', true),
  ('peanut-noodles-cabbage-carrots', 'Peanut Noodles with Cabbage and Carrots', 'dinner', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 20, false, 'Spaghetti tossed with crunchy cabbage and carrots in a creamy peanut, soy and lime sauce.', array['Bring a large pot of water to a boil over high heat and cook the spaghetti as the package says, until tender.', 'While it cooks, whisk the peanut butter, soy sauce, vinegar, maple syrup, sesame oil, sriracha, garlic and ginger in a large bowl, adding hot water from the pot a spoonful at a time until the sauce is smooth and pourable.', 'Add the coleslaw mix to the pot for the last minute of cooking, just until the cabbage softens slightly, then drain everything.', 'Toss the hot noodles and cabbage with the sauce until evenly coated.', 'Top with the green onion and chopped peanuts and serve with the lime cut into wedges.']::text[], 'https://images.unsplash.com/photo-1609690963718-0b55905aef78', 'Melissia Ohol', 'https://unsplash.com/photos/sliced-vegetables-in-white-ceramic-bowl-o77dNRrgcn0', true),
  ('peanut-tofu-broccoli-rice-bowls', 'Peanut Tofu and Broccoli Rice Bowls', 'dinner', array['dairy_free', 'high_protein', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 30, false, 'Crisp pan-fried tofu and broccoli over rice with a quick peanut-soy sauce.', array['Put the rice in a saucepan with twice as much water as rice, bring to a boil, cover and cook over low heat for 18 minutes, until the water is absorbed.', 'Press the tofu between paper towels to dry it, cut it into bite-size cubes and toss with the cornstarch until coated.', 'Heat the oil in a large nonstick skillet over medium-high heat and fry the tofu 8 to 10 minutes, turning every couple of minutes, until golden and crisp on most sides; move it to a plate.', 'Add the broccoli florets and a splash of water to the same pan, cover and steam over medium heat for 4 minutes, until bright green and just tender.', 'Whisk the peanut butter, soy sauce, maple syrup, vinegar, sriracha, garlic and ginger with a few spoonfuls of hot water until smooth and pourable.', 'Return the tofu to the pan, pour in the sauce and toss over low heat for 1 minute, until everything is coated and hot.', 'Serve over the rice, topped with the chopped peanuts and green onion.']::text[], 'https://images.unsplash.com/photo-1631255325918-1ca2886508a5', 'Bakd&Raw by Karolin Baitinger', 'https://unsplash.com/photos/cooked-food-on-white-ceramic-plate-LBJZDJvStJc', true),
  ('peruvian-chicken-rice', 'Peruvian-Style Chicken and Rice', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 50, true, 'Green cilantro rice with seasoned chicken thighs — a simplified arroz verde.', array['Blend the cilantro, spinach and half a cup of broth into a green purée.', 'Season the chicken with salt and cumin and brown it in hot oil 4 minutes per side; set aside.', 'Sauté the onion and garlic 4 minutes, stir in the rice to coat, add the green purée and remaining broth.', 'Nestle the chicken back in, cover and cook 20 minutes until the rice is tender; rest 5 and serve.']::text[], 'https://images.unsplash.com/photo-1762631383378-115f2d4cbe07', 'Unsplash contributor', 'https://unsplash.com/photos/healthy-bowl-with-chicken-rice-beans-and-corn-6XDDOrCMs64', true),
  ('pesto-chicken-pasta', 'Pesto Chicken Pasta', 'dinner', array['high_protein']::text[], 4, 25, false, 'Seared chicken and penne tossed in basil pesto with cherry tomatoes.', array['Cook the penne in salted water; save a cup of the water before draining.', 'Season the chicken with salt and sear in hot olive oil 4 minutes per side; slice.', 'Toss the pasta with the pesto and a splash of pasta water until glossy.', 'Add the chicken and tomatoes and serve with parmesan.']::text[], 'https://images.unsplash.com/photo-1767065583952-e932c354bca6', 'Unsplash contributor', 'https://unsplash.com/photos/cheesy-lasagna-being-lifted-with-a-fork--BHFKS0kk-U', true),
  ('picadillo', 'Cuban-Style Picadillo', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 35, true, 'Sweet-savory ground beef with olives and warm spices over rice.', array['Cook the rice according to the package directions.', 'Sauté the onion and bell pepper in hot oil 5 minutes, add the garlic and cook 1 minute.', 'Add the beef and cook 6 minutes, breaking it up, until browned.', 'Stir in the tomatoes, cumin, cinnamon and olives; simmer 10 minutes until thick.', 'Season with salt and serve over rice.']::text[], 'https://images.unsplash.com/photo-1771074168439-0083aaac48e7', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-rice-chickpeas-and-salad-with-meat-g7WrssBb1Ak', true),
  ('pinto-bean-huevos-rancheros', 'Pinto Bean Huevos Rancheros', 'dinner', array['gluten_free', 'pescatarian', 'vegetarian']::text[], 4, 20, false, 'Fried eggs on crisp corn tortillas with mashed pinto beans, warm salsa, cheddar and avocado.', array['Put the drained beans in a small pot with the cumin and a splash of water, warm over medium heat for 3 minutes and mash roughly with a fork; cover to keep warm.', 'Warm the salsa in a small saucepan over low heat for about 3 minutes, until it steams.', 'Heat a thin film of the oil in a large skillet over medium-high heat and fry the tortillas two at a time, about 30 seconds per side, until just crisp at the edges; drain on paper towels.', 'Lower the heat to medium, add the remaining oil and crack in the eggs, in batches if needed; fry 2 to 3 minutes, until the whites are set and the yolks are as runny or firm as you like.', 'Spread beans on each tortilla and top with an egg, warm salsa, cheddar, avocado and cilantro.']::text[], 'https://images.unsplash.com/photo-1650330151304-5db3ca9b3b6c', 'Alexandra Mendívil', 'https://unsplash.com/photos/a-bowl-of-food-with-an-egg-avocado-and-rice-rNriCVGMVgQ', true),
  ('pinto-bean-taco-salad', 'Crunchy Pinto Bean Taco Salad', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 15, false, 'Romaine piled with seasoned pinto beans, corn, tomato, avocado and crushed tortilla chips.', array['Put the drained beans in a small pot with the taco seasoning and a splash of water and warm over medium heat for 3 minutes, stirring, until hot and coated.', 'In a small bowl, stir the salsa and the juice of the lime into a dressing.', 'Divide the chopped romaine among four bowls.', 'Top with the warm beans, corn, tomato and avocado.', 'Spoon the dressing over each bowl and crush the tortilla chips on top just before serving so they stay crisp.']::text[], 'https://images.unsplash.com/photo-1543339127-b02a6d983980', 'Hermes Rivera', 'https://unsplash.com/photos/fruit-dish-on-plate-dZuHkZwryyI', true),
  ('polenta-mushroom-ragu', 'Polenta with Mushroom Ragu', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 35, true, 'Creamy polenta topped with a rich tomato-mushroom ragu.', array['Sear the mushrooms in olive oil 6 minutes until browned; add the onion and cook 4 minutes.', 'Stir in the garlic and tomato paste 1 minute, add the tomatoes and simmer 15 minutes until thick; season with salt.', 'Meanwhile cook the polenta in boiling salted water following the package ratio (about 4 cups of water per cup of polenta), simmering and whisking until thick.', 'Serve the ragu over the polenta.']::text[], 'https://images.unsplash.com/photo-1778851182989-ea3f9d2d280b', 'Unsplash contributor', 'https://unsplash.com/photos/polenta-with-creamy-spinach-and-tomato-sauce-42X1cpCtSQA', true),
  ('pork-egg-roll-bowls-with-rice', 'Pork Egg Roll Bowls with Rice', 'dinner', array['dairy_free']::text[], 4, 25, false, 'Ground pork stir-fried with coleslaw mix, garlic, ginger and soy sauce, served over white rice.', array['Put the rice in a medium pot with twice its volume of water, bring to a boil over high heat, then cover and cook on low 15 minutes until the water is absorbed; leave it covered off the heat.', 'Meanwhile, heat the vegetable oil in a large skillet over medium-high heat and cook the pork 6 minutes, breaking it up, until browned with no pink left.', 'Add the garlic and ginger and stir 30 seconds until fragrant.', 'Add the coleslaw mix, soy sauce and rice vinegar and stir-fry 4 minutes until the cabbage is wilted but still has a little crunch.', 'Take the pan off the heat and stir in the sesame oil and half the green onions.', 'Fluff the rice with a fork, spoon the pork over it and top with the remaining green onions and sriracha to taste.']::text[], 'https://images.unsplash.com/photo-1745123129024-d97c4b71ed4d', 'Kouji Tsuru', 'https://unsplash.com/photos/meat-and-vegetables-served-with-rice-EgIB9a8B6UU', true),
  ('pork-egg-roll-in-a-bowl', 'Pork Egg Roll in a Bowl', 'dinner', array['dairy_free', 'keto', 'low_carb']::text[], 4, 20, false, 'Everything inside an egg roll, minus the wrapper: ground pork and cabbage stir-fried with ginger, garlic and soy.', array['Mince the garlic, grate the ginger, shred the carrot on the large holes of a grater and slice the green onions.', 'Heat a large skillet or wok over medium-high heat and add the pork; cook 5 to 6 minutes, breaking it up with a spoon, until browned with no pink left.', 'Stir in the garlic, ginger and carrot and cook 1 minute until fragrant.', 'Add the coleslaw mix, soy sauce and rice vinegar and toss 4 to 5 minutes until the cabbage wilts but still has some crunch.', 'Take the pan off the heat, drizzle with the sesame oil and sriracha and toss once more.', 'Divide among bowls and top with the green onions.']::text[], 'https://images.unsplash.com/photo-1597130869926-224e85944619', 'ABHISHEK HAJARE', 'https://unsplash.com/photos/green-and-brown-vegetable-salad-6XcZ2NQmRqY', true),
  ('pork-gyoza-salad-bowls', 'Pork and Cabbage Skillet', 'dinner', array['dairy_free', 'low_carb', 'high_protein']::text[], 4, 25, false, 'Ground pork stir-fried with cabbage, garlic and ginger — all the flavors of dumplings without the folding.', array['Heat the oil in a large skillet over medium-high heat and cook the pork 5 to 6 minutes, breaking it up, until browned.', 'Add the garlic, ginger and cabbage; stir-fry 5 minutes until the cabbage wilts.', 'Pour in the soy sauce, vinegar and sesame oil and toss 1 minute.', 'Top with green onion and serve as is or over rice.']::text[], 'https://images.unsplash.com/photo-1564834724105-918b73d1b9e0', 'Unsplash contributor', 'https://unsplash.com/photos/bowl-of-cooked-food-H6iSwrAOMG0', true),
  ('pork-tenderloin-sweet-potato-skillet', 'Pork Tenderloin & Sweet Potato Skillet', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 35, false, 'Strips of smoky pork tenderloin tossed with caramelized sweet potato cubes and red onion.', array['Peel the sweet potatoes and cut them into small cubes about the width of your thumb. Slice the red onion and mince the garlic.', 'Heat half the olive oil in a large skillet over medium heat. Add the sweet potatoes, cover and cook 12 minutes, stirring every few minutes, until tender when pierced and browned in spots.', 'Meanwhile slice the pork into thin strips and toss with the smoked paprika, cumin, thyme, salt and pepper.', 'Move the sweet potatoes to a plate. Raise the heat to medium-high, add the remaining oil and sear the pork 5 to 6 minutes, stirring a few times, until browned and no longer pink inside.', 'Add the garlic and half the red onion and cook 1 minute.', 'Return the sweet potatoes, add the vinegar and toss 1 minute until everything is hot.', 'Serve topped with the remaining raw red onion.']::text[], 'https://images.unsplash.com/photo-1636407715708-a097fdcef57a', 'Nico M.', 'https://unsplash.com/photos/a-plate-of-food-on-a-wooden-table-yicKRIphU1c', true),
  ('potato-corn-chowder', 'Potato Corn Chowder', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 40, true, 'Creamy chowder of potatoes and sweet corn thickened with a light roux and topped with cheddar and green onion.', array['Melt the butter in a large pot over medium heat and cook the onion and celery for 6 minutes until soft.', 'Add the garlic and thyme, stir for 30 seconds, then sprinkle in the flour and stir for 1 minute.', 'Pour in the broth little by little while stirring so no lumps form, then add the potatoes, salt and pepper.', 'Bring to a boil over high heat, then lower the heat, cover and simmer for 12 to 15 minutes until the potatoes are tender when pierced with a fork.', 'Add the corn and milk and simmer gently for 5 minutes without letting it boil hard.', 'Mash a few of the potatoes against the side of the pot to thicken the chowder, then serve topped with the cheddar and green onion.']::text[], 'https://images.unsplash.com/photo-1660899227222-b9fd7fe2e060', 'ALLAN LAINEZ', 'https://unsplash.com/photos/a-plate-of-food-FX_vvVtEAnw', true),
  ('potato-egg-cheese-breakfast-tacos', 'Potato, Egg and Cheese Breakfast Tacos', 'breakfast', array['pescatarian', 'vegetarian']::text[], 4, 25, false, 'Crispy diced potatoes folded into soft scrambled eggs, tucked into warm flour tortillas with cheddar and salsa.', array['Scrub the potatoes and cut them into small cubes about the width of a fingertip; there is no need to peel them.', 'Heat the oil in a large nonstick skillet over medium-high heat, add the potatoes with half of the salt in one layer and cook 12 to 14 minutes, stirring every few minutes, until golden and a fork slides in easily.', 'Beat the eggs with the remaining salt and the pepper. Push the potatoes to one side, lower the heat to medium-low and melt the butter in the empty space.', 'Pour in the eggs and stir gently 2 minutes, until softly set, then fold them into the potatoes and take the skillet off the heat.', 'Warm the tortillas one at a time in a dry skillet over medium heat, 20 seconds per side, until soft and flexible.', 'Fill each tortilla with the potato and egg mixture, top with the cheddar and salsa, and serve two tacos per person.']::text[], 'https://images.unsplash.com/photo-1667499707432-0524fcfb63ba', 'Leanna Myers', 'https://unsplash.com/photos/a-plate-of-food-mypgWO69XDY', true),
  ('potato-pea-curry-with-naan', 'Potato and Pea Curry with Naan', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 40, false, 'Potatoes and peas simmered in a spiced tomato sauce and scooped up with warm naan.', array['Heat the oil in a large pot over medium heat and cook the onion 5 minutes, stirring, until soft.', 'Stir in the garlic, ginger, curry powder, cumin and turmeric and cook 1 minute, until fragrant.', 'Add the potatoes, tomatoes, broth and salt and bring to a boil over high heat.', 'Lower to medium-low, cover and simmer 20 minutes, stirring once or twice, until a knife slides easily into a potato.', 'Stir in the peas and cook 3 minutes, crushing a few potato cubes against the side of the pot to thicken the sauce.', 'Warm the naan one at a time in a dry skillet over medium heat, about 1 minute per side, until soft and hot.', 'Serve the curry sprinkled with the cilantro, with the naan on the side.']::text[], 'https://images.unsplash.com/photo-1789990642036-e10c2df4fc81', 'Zoshua Colah', 'https://unsplash.com/photos/poori-and-potato-curry-breakfast-LBknd0DOoRk', true),
  ('potato-pepper-breakfast-hash-with-eggs', 'Potato Pepper Breakfast Hash with Eggs', 'breakfast', array['dairy_free', 'gluten_free', 'pescatarian', 'vegetarian']::text[], 4, 35, false, 'Crispy skillet potatoes with bell pepper and onion, finished with eggs cooked right in the pan.', array['Scrub the potatoes and cut them, skin on, into small cubes about as wide as your fingertip so they cook through. Dice the bell pepper and the onion.', 'Heat the oil in a large skillet that has a lid over medium-high heat for 1 minute, until it shimmers.', 'Add the potatoes in one layer and cook 12 to 15 minutes, turning them every 3 to 4 minutes, until golden and crisp outside and a fork slides in easily.', 'Add the bell pepper, onion, smoked paprika, garlic powder, salt and black pepper and cook 5 minutes, stirring, until the vegetables soften.', 'Turn the heat down to medium-low. Make a well in the hash for each egg and crack an egg into each one.', 'Cover and cook 4 to 5 minutes, until the whites are set and the yolks are still soft; leave 2 minutes longer for firm yolks.', 'Serve straight from the skillet.']::text[], 'https://images.unsplash.com/photo-1601579112521-5d6badb0bf3c', 'Megan Bucknall', 'https://unsplash.com/photos/black-round-plate-with-cooked-food-hzxxLzqaEjU', true),
  ('pozole-blanco', 'Quick Chicken Pozole', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 35, true, 'A fast hominy soup with shredded chicken, cabbage, radish-free crunch and lime.', array['Bring the broth to a simmer with the garlic, cumin and chili powder.', 'Add the hominy and chicken and simmer 10 minutes.', 'Season with salt and the lime juice.', 'Serve in bowls topped with shredded cabbage, onion and more lime.']::text[], 'https://images.unsplash.com/photo-1767032916116-2460bbd4a27d', 'Unsplash contributor', 'https://unsplash.com/photos/baskets-overflowing-with-colorful-fresh-vegetables-and-fruits-7J9i4Damd2I', true),
  ('pressure-cooker-beans', 'Pressure Cooker Beans and Rice', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 45, true, 'Smoky beans in 30 minutes — no overnight soak, no canned taste.', array['Sauté the onion, pepper and garlic 4 minutes on sauté mode with the cumin and oregano.', 'Add the beans, broth and bay-free seasonings with a pinch of salt.', 'Seal and cook on high pressure 25 minutes; natural release 10.', 'Mash a few beans to thicken and serve over rice.']::text[], 'https://images.unsplash.com/photo-1770164678239-89706708a496', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-food-with-meat-eggs-and-onions-OzyzMJc1bVk', true),
  ('pressure-cooker-chicken-rice', 'Pressure Cooker Chicken and Rice', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 35, true, 'Seasoned chicken thighs and fluffy rice in 12 minutes of pressure.', array['Season the chicken with salt and paprika; sear on sauté mode 3 minutes per side and set aside.', 'Sauté the onion and garlic 3 minutes, add the rice and coat it.', 'Pour in the broth, place the chicken on top, seal and cook 10 minutes on high pressure.', 'Natural release 10 minutes, fluff the rice and serve.']::text[], 'https://images.unsplash.com/photo-1708782344490-9026aaa5eec7', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-chicken-curry-next-to-a-bowl-of-rice-tsQhEvzU6MQ', true),
  ('pressure-cooker-pasta-marinara', 'Pressure Cooker Pasta Marinara', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 20, false, 'One-pot pasta where the sauce cooks itself — no straining.', array['Place the pasta, marinara and 2.5 cups of water in the cooker with a pinch of salt; stir well.', 'Seal and cook on high pressure 5 minutes; quick release carefully.', 'Stir everything — the starchy liquid becomes the sauce.', 'Rest 3 minutes to thicken and serve with olive oil.']::text[], 'https://images.unsplash.com/photo-1750396628434-ba9a3e1a265c', 'Unsplash contributor', 'https://unsplash.com/photos/delicious-pasta-with-tomato-sauce-is-ready-tL0CPgvRPy8', true),
  ('pressure-cooker-pot-roast', 'Pressure Cooker Pot Roast', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 6, 90, true, 'Sunday pot roast in 90 minutes instead of all afternoon.', array['Season the beef with salt and sear it in the cooker on sauté mode, 4 minutes per side; set aside.', 'Sauté the onion and garlic 3 minutes, pour in the broth and scrape up the browned bits.', 'Return the beef, seal and cook on high pressure 60 minutes; natural release 10.', 'Add the potatoes and carrots, cook 5 more minutes on pressure.', 'Serve the beef shredded with the vegetables and juices.']::text[], 'https://images.unsplash.com/photo-1586195833898-170cabf110c5', 'Unsplash contributor', 'https://unsplash.com/photos/sliced-meat-on-brown-wooden-chopping-board-y4YOJda6OIo', true),
  ('pressure-cooker-risotto', 'Pressure Cooker Risotto', 'dinner', array['vegetarian', 'gluten_free']::text[], 4, 30, false, 'Creamy risotto with no stirring — pressure does the work.', array['Sauté the onion in butter 3 minutes on sauté mode, add the rice and toast 1 minute.', 'Pour in the broth, seal and cook on high pressure 6 minutes; quick release.', 'Stir in the parmesan and season with salt; it finishes creamy as you stir.', 'Serve right away.']::text[], 'https://images.unsplash.com/photo-1767065584562-0127cdec486d', 'Unsplash contributor', 'https://unsplash.com/photos/gourmet-dish-with-melted-cheese-and-herbs-inpfP2cgUXU', true),
  ('quick-beef-broccoli', 'Quick Beef and Broccoli', 'dinner', array['high_protein', 'dairy_free']::text[], 4, 25, false, 'Thin-sliced beef and broccoli in a savory garlic-soy sauce over rice — faster than takeout.', array['Cook the rice according to the package directions.', 'Stir the soy sauce, brown sugar, garlic, ginger, cornstarch and half a cup of water in a small bowl.', 'Heat the oil in a large skillet over high heat and sear the beef in a single layer 2 to 3 minutes per side until browned; transfer to a plate.', 'Add the broccoli and a splash of water, cover and steam 2 minutes.', 'Return the beef, pour in the sauce and cook 1 to 2 minutes until glossy and thickened.', 'Serve over the rice.']::text[], 'https://images.unsplash.com/photo-1764850685940-4e8f06190cb9', 'Unsplash contributor', 'https://unsplash.com/photos/stir-fried-broccoli-with-chili-flakes-and-garlic-twJcB5sLvkw', true),
  ('quinoa-tabbouleh-with-chickpeas', 'Quinoa Tabbouleh with Chickpeas', 'lunch', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 35, true, 'A parsley-heavy lemon salad with quinoa, chickpeas, tomato and cucumber that gets better overnight.', array['Rinse the quinoa in a fine strainer under cold water for 30 seconds to remove its bitter coating.', 'Put it in a small pot with twice its volume of water and a pinch of the salt, bring to a boil over high heat, cover, turn the heat to low and cook 15 minutes, until the water is absorbed and the grains show little tails.', 'Spread the quinoa on a large plate and let it cool 10 minutes so it does not wilt the herbs.', 'Meanwhile, finely chop the parsley leaves and tender stems, dice the tomatoes and cucumber small, slice the green onions, mince the garlic, and drain and rinse the chickpeas.', 'Whisk the lemon juice, olive oil, garlic, pepper and remaining salt in a large bowl.', 'Add the quinoa, chickpeas, vegetables and parsley and toss well. Taste, add more salt or lemon if needed, and serve cold or at room temperature.']::text[], 'https://images.unsplash.com/photo-1656853834420-51980b12a920', 'Reza Eghtedari', 'https://unsplash.com/photos/a-plate-of-salad-epetkkA9lr0', true),
  ('ratatouille-rice', 'Ratatouille over Rice', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 45, true, 'Stewed eggplant, zucchini and tomatoes in herbs — simple and colorful.', array['Cook the rice according to the package directions.', 'Sauté the eggplant in olive oil 6 minutes until golden; set aside.', 'Add the onion and peppers 5 minutes, then the zucchini and garlic 4 minutes.', 'Return the eggplant with the tomatoes, thyme and salt; simmer 15 minutes until saucy.', 'Serve over rice with basil.']::text[], 'https://images.unsplash.com/photo-1788603907308-58eb4325dce1', 'Unsplash contributor', 'https://unsplash.com/photos/fried-rice-with-vegetables-on-plate-5Fii0b2wc3I', true),
  ('red-beans-and-rice-with-smoked-sausage', 'Red Beans and Rice with Smoked Sausage', 'dinner', array['dairy_free', 'gluten_free']::text[], 4, 45, true, 'Creamy simmered kidney beans with smoked sausage, onion, bell pepper and celery over white rice.', array['Heat the oil in a large pot over medium-high heat and brown the sliced sausage 4 minutes until the edges are dark golden.', 'Add the onion, bell pepper and celery and cook 6 minutes, stirring, until soft.', 'Stir in the garlic, smoked paprika, thyme and cayenne and cook 30 seconds until fragrant.', 'Add the kidney beans with their liquid, the broth and the salt and bring to a boil.', 'Lower the heat to medium-low and simmer uncovered 25 minutes, stirring now and then and mashing some of the beans against the side of the pot, until thick and creamy.', 'While the beans simmer, put the rice in a medium pot with twice its volume of water, bring to a boil over high heat, then cover and cook on low 15 minutes until the water is absorbed.', 'Fluff the rice with a fork and serve the beans spooned over it.']::text[], 'https://images.unsplash.com/photo-1686699782036-e101b4f5a02e', 'Ronald Vargas', 'https://unsplash.com/photos/a-bowl-of-food-on-a-wooden-table-4NxCbpyh8AY', true),
  ('refried-bean-corn-quesadillas', 'Refried Bean and Corn Quesadillas', 'dinner', array['pescatarian', 'vegetarian']::text[], 4, 25, false, 'Crisp flour tortillas filled with refried beans, corn, green chiles and melted cheddar.', array['In a bowl, stir the cumin, drained corn and green chiles into the refried beans until evenly mixed.', 'Spread the bean mixture over half of each tortilla, sprinkle with the cheddar and fold the other half over, pressing lightly.', 'Brush a large skillet with a little of the oil and heat it over medium heat for 1 minute.', 'Cook the quesadillas two at a time, 2 to 3 minutes per side, until the tortillas are crisp and golden and the cheese is melted; add a little more oil between batches.', 'Rest them 1 minute, cut each into wedges and serve with the salsa and sour cream.']::text[], 'https://images.unsplash.com/photo-1617990590988-895fe6cbabda', 'Lottie Griffiths', 'https://unsplash.com/photos/sliced-pizza-on-brown-wooden-table-FRObR62TyKk', true),
  ('roast-chicken-with-potatoes-and-carrots', 'Roast Chicken with Potatoes and Carrots', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 100, true, 'A whole chicken rubbed with garlic thyme butter and roasted over potatoes, carrots and onion.', array['Heat the oven to {425F}.', 'Toss the potatoes, carrots and onion with the oil and half the salt in a large roasting pan and spread them out.', 'Mash the softened butter with the garlic, thyme, pepper and remaining salt.', 'Pat the chicken dry with paper towels and rub the butter all over it, including under the breast skin where you can.', 'Put the lemon halves inside the chicken and set it breast-side up on top of the vegetables.', 'Roast 70 to 75 minutes, stirring the vegetables once halfway, until the skin is deep golden, the juices run clear and the thickest part of the thigh reaches {165F}.', 'Rest the chicken 10 minutes on a board so the juices settle, then carve and serve with the vegetables and pan juices.']::text[], 'https://images.unsplash.com/photo-1600575615458-5129e7cb960b', 'QUENTIN Mahe', 'https://unsplash.com/photos/roasted-chicken-on-white-ceramic-plate-exjZl4aydUc', true),
  ('rotisserie-chicken-black-bean-quesadillas', 'Rotisserie Chicken and Black Bean Quesadillas', 'dinner', array['high_protein']::text[], 4, 25, false, 'Crisp flour tortillas filled with shredded rotisserie chicken, black beans and melted cheddar.', array['Shred the chicken with two forks or your fingers, discarding the skin and bones, and mix it in a bowl with the black beans and cumin.', 'Sprinkle cheddar over half of each tortilla, spoon the chicken mixture on top and fold the tortilla closed.', 'Brush a large skillet with a little of the oil and heat it over medium heat.', 'Cook the quesadillas two at a time, 2 to 3 minutes per side, pressing lightly with a spatula, until golden and crisp and the cheese has melted; brush the pan with more oil between batches.', 'Rest them 1 minute, cut into wedges and serve with the salsa and sour cream.']::text[], 'https://images.unsplash.com/photo-1618040996337-56904b7850b9', 'Lottie Griffiths', 'https://unsplash.com/photos/sliced-pizza-on-brown-wooden-table-pvTgyioFSTY', true),
  ('rotisserie-chicken-enchiladas', 'Rotisserie Chicken Enchiladas', 'dinner', array['high_protein']::text[], 4, 40, true, 'Flour tortillas rolled around shredded chicken, green chiles and cheddar, baked in red enchilada sauce.', array['Heat the oven to {375F}.', 'Mix the shredded chicken in a bowl with the onion, green chiles, cumin, sour cream and half the cheddar.', 'Spread about a quarter of the enchilada sauce over the bottom of a large baking dish.', 'Spoon the filling down the center of each tortilla, roll it up tightly and place it seam-side down in the dish, snug against the next one.', 'Pour the remaining sauce over the top, spreading it to cover the edges of the tortillas, and sprinkle with the remaining cheddar.', 'Bake 20 minutes until the sauce bubbles at the edges and the cheese is melted and starting to brown.', 'Rest 5 minutes before serving.']::text[], 'https://images.unsplash.com/photo-1674135529596-cb1f707d231d', 'Aleksandra Gencheva', 'https://unsplash.com/photos/a-person-holding-a-dish-of-food-on-a-table-4vB9GNWnmbM', true),
  ('rotisserie-chicken-salad-lettuce-cups', 'Rotisserie Chicken Salad Lettuce Cups', 'lunch', array['dairy_free', 'gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 15, true, 'Shredded rotisserie chicken in a creamy lemon-mustard dressing, scooped into crisp romaine leaves.', array['Pull the meat off the chicken with your hands, discarding the skin and bones, and shred or chop it into bite-size pieces.', 'Dice the celery, thinly slice the green onions and squeeze the lemon.', 'In a large bowl, stir the mayonnaise, mustard, lemon juice, salt and pepper into a smooth dressing.', 'Add the chicken, celery and green onions and fold until everything is evenly coated. Taste and adjust the salt.', 'Separate the romaine into leaves, wash them and pat them dry so the filling does not slide off.', 'Spoon the chicken salad into the leaves and serve.', 'Store leftover chicken salad in a sealed container in the fridge up to 4 days and fill the leaves just before eating.']::text[], 'https://images.unsplash.com/photo-1612949060306-4c298ad7f34c', 'Christine Isakzhanova', 'https://unsplash.com/photos/vegetable-salad-on-white-ceramic-plate-xWcExN_8nTk', true),
  ('salmon-orzo-lemon', 'Salmon with Lemon Orzo', 'dinner', array['pescatarian', 'high_protein']::text[], 4, 30, false, 'Seared salmon over buttery lemon orzo with peas.', array['Season the salmon with salt and sear in hot olive oil 3 to 4 minutes per side; set aside.', 'Toast the orzo in butter 2 minutes, add the garlic and cook 30 seconds.', 'Add the broth and simmer 8 minutes until the orzo is tender, stirring in the peas for the last 2.', 'Stir in the lemon juice and serve the salmon on top.']::text[], 'https://images.unsplash.com/photo-1574484284002-952d92456975', 'Unsplash contributor', 'https://unsplash.com/photos/salmon-in-creamy-sauce-dinner-ND3edEmzcdQ', true),
  ('salmon-tacos-mango-style', 'Salmon Tacos with Slaw', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 25, false, 'Chili-rubbed salmon flaked into tortillas with a bright cabbage slaw.', array['Toss the slaw mix with the lime juice, cilantro and a pinch of salt.', 'Season the salmon with the chili powder, cumin and salt.', 'Cook in hot oiled skillet 3 to 4 minutes per side until it flakes; break into chunks.', 'Warm the tortillas and serve the salmon inside with the slaw.']::text[], 'https://images.unsplash.com/photo-1683062332605-4e1209d75346', 'Unsplash contributor', 'https://unsplash.com/photos/three-tacos-are-sitting-on-a-plate-next-to-a-glass-of-beer-5mpht0M5H0E', true),
  ('salsa-verde-pork', 'Pork in Salsa Verde', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 60, true, 'Tender pork simmered in tomatillo-style salsa verde, served with rice.', array['Cook the rice according to the package directions.', 'Season the pork with salt and brown it in hot oil in batches; set aside.', 'Sauté the onion 4 minutes, add the garlic and cumin and cook 1 minute.', 'Return the pork, add the salsa verde and a splash of water; cover and simmer 35 to 40 minutes until tender.', 'Serve over rice with cilantro.']::text[], 'https://images.unsplash.com/photo-1764158156827-0df193e9783c', 'Unsplash contributor', 'https://unsplash.com/photos/bowl-of-ramen-with-egg-pork-and-green-onions-iLDoHJrdf5s', true),
  ('sausage-and-egg-stuffed-peppers', 'Sausage and Egg Stuffed Peppers', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 2, 40, false, 'Bell pepper halves filled with browned breakfast sausage, beaten eggs and cheddar, baked until set and golden.', array['Heat the oven to {400F}. Cut the peppers in half lengthwise through the stem and remove the seeds and white ribs.', 'Set the halves cut-side up in a baking dish and bake 10 minutes, until they begin to soften.', 'Meanwhile, brown the sausage in a small skillet over medium-high heat 5 minutes, breaking it up, until no pink remains. Spoon off the excess fat.', 'Beat the eggs with the salt and pepper and stir in the sausage, the sliced green onion and half of the cheddar.', 'Spoon the mixture into the pepper halves, filling them almost to the rim, and sprinkle with the remaining cheddar.', 'Bake 18 to 20 minutes, until the filling is puffed and set in the center and the cheese is golden. Serve two halves per person.']::text[], 'https://images.unsplash.com/photo-1673646960062-9aeb2188335f', 'Natalia Gusakova', 'https://unsplash.com/photos/a-white-plate-topped-with-stuffed-bell-peppers-myfDbaJr6vA', true),
  ('sausage-egg-breakfast-casserole', 'Sausage and Egg Breakfast Casserole', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 50, true, 'A crustless bake of browned sausage, bell pepper, eggs and cheddar that cuts into squares for the week.', array['Heat the oven to {375F} and grease a medium square baking dish (8 inches, 20 cm) with the butter. Dice the bell pepper and slice the green onions.', 'Brown the sausage in a large skillet over medium-high heat 5 minutes, breaking it up with a spoon.', 'Add the bell pepper and cook 3 minutes more, until the sausage is no longer pink and the pepper begins to soften. Spoon off the excess fat.', 'Whisk the eggs, cream, salt and pepper in a large bowl until uniform, then stir in the green onions and most of the cheddar.', 'Spread the sausage and pepper in the dish, pour the egg mixture over the top and sprinkle with the remaining cheddar.', 'Bake 30 minutes, until puffed and golden and a knife inserted in the center comes out clean.', 'Let it rest 5 minutes, then cut into squares and serve.']::text[], 'https://images.unsplash.com/photo-1551978155-63d44a16fe24', 'sheri silver', 'https://unsplash.com/photos/baked-pastries--MNxKF8a6j0', true),
  ('sausage-egg-cheese-breakfast-burritos', 'Sausage Egg and Cheese Breakfast Burritos', 'breakfast', array['high_protein']::text[], 4, 25, true, 'Freezer-friendly burritos stuffed with sausage, hash browns, scrambled eggs, cheddar and salsa.', array['Crumble the sausage into a large nonstick skillet and cook over medium-high heat 5 minutes, breaking it up with a spoon, until browned with no pink left.', 'Add the hash browns straight from the freezer, spread them out and cook 5 minutes, stirring twice, until hot and crisp at the edges.', 'Crack the eggs into a bowl and beat them with a fork. Turn the heat down to medium, pour the eggs into the skillet and stir gently 2 minutes, until just set and no longer runny.', 'Tip the filling into a bowl and wipe out the skillet. Warm the tortillas in it one at a time over medium heat, 20 seconds per side, until soft and flexible so they fold without cracking.', 'Spoon the filling down the middle of each tortilla and top with the cheddar and the salsa.', 'Fold the two sides in over the filling, then roll up tightly from the bottom.', 'Eat now, or let the burritos cool, wrap each one in foil and freeze up to 2 months.']::text[], 'https://images.unsplash.com/photo-1662478839359-751ffc3cbbd8', 'Mikey Frost', 'https://unsplash.com/photos/a-plate-of-food-bmXDqfPf4Vo', true),
  ('sausage-egg-cheese-muffin-sandwiches', 'Sausage, Egg and Cheese Muffin Sandwiches', 'breakfast', array['high_protein', 'low_carb']::text[], 4, 20, true, 'Homemade drive-through style sandwiches: a sausage patty, a fried egg and melted cheese on a toasted English muffin.', array['Divide the sausage into 4 equal portions and flatten each into a thin patty a little wider than the muffins, since they shrink as they cook.', 'Cook the patties in a large skillet over medium heat 4 to 5 minutes per side, until well browned and no longer pink in the center ({160F}). Move them to a plate and wipe out most of the fat.', 'Split the muffins and toast them cut-side down in the skillet 1 to 2 minutes, until golden. Set aside.', 'Melt the butter in the skillet over medium-low heat, crack in the eggs, break the yolks with the corner of the spatula and season with the salt and pepper.', 'Cook the eggs 2 minutes, flip and cook 1 minute more, until set all the way through.', 'Stack a patty, an egg and a slice of cheese on each muffin bottom, close with the top and wait 1 minute so the cheese melts.']::text[], 'https://images.unsplash.com/photo-1569159316006-900e88b5dbc2', 'Duncan Kidd', 'https://unsplash.com/photos/baked-burger-on-wooden-surface-pnV8uZlFWrA', true),
  ('sausage-kale-cauliflower-soup', 'Sausage, Kale and Cauliflower Soup', 'dinner', array['gluten_free', 'keto', 'low_carb']::text[], 4, 40, true, 'A low-carb take on zuppa toscana: Italian sausage, kale and cauliflower in a creamy garlic broth.', array['Squeeze the sausage out of its casings into a large pot over medium-high heat and cook for 6 to 8 minutes, breaking it up with a spoon, until browned with no pink left.', 'Spoon off all but a thin layer of fat, add the onion and cook over medium heat for 4 minutes until soft.', 'Add the garlic and red pepper flakes and stir for 30 seconds until fragrant.', 'Add the cauliflower, broth and salt, bring to a boil over high heat, then lower the heat and simmer for 10 minutes until a knife slides easily into the cauliflower.', 'Strip the kale leaves from the stems, tear them into pieces, stir them in and simmer for 5 minutes until tender.', 'Stir in the cream and pepper, warm for 1 minute over low heat and serve.']::text[], 'https://images.unsplash.com/photo-1691501946447-34a08da5b930', 'Filipp Romanovski', 'https://unsplash.com/photos/a-white-bowl-filled-with-soup-next-to-a-plate-of-greens-wtwS_S3K6u4', true),
  ('sausage-pepper-egg-scramble', 'Sausage and Pepper Egg Scramble', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 2, 15, false, 'Breakfast sausage and bell pepper scrambled with eggs and finished with melted cheddar.', array['Dice the bell pepper. Crack the eggs into a bowl, add the salt and pepper and beat with a fork until blended.', 'Crumble the sausage into a nonstick skillet that has a lid and cook over medium-high heat 5 minutes, breaking it into small pieces, until browned with no pink left.', 'Add the bell pepper and cook 3 minutes, stirring, until softened. If there is a lot of fat in the skillet, spoon most of it off.', 'Turn the heat down to medium-low and pour in the eggs. Let them sit 20 seconds, then stir gently for about 2 minutes, folding from the edges, until softly set and still moist.', 'Sprinkle the cheddar over the top, cover and take off the heat for 1 minute, until the cheese melts.', 'Serve right away.']::text[], 'https://images.unsplash.com/photo-1662751331020-8a30ce0c78f6', 'Andrijana Bozic', 'https://unsplash.com/photos/a-plate-of-food-SBc3QKmqwpg', true),
  ('sausage-peppers-penne', 'Sausage and Peppers Pasta', 'dinner', array['high_protein']::text[], 4, 30, false, 'Italian sausage with peppers and onion in a light tomato sauce over penne.', array['Cook the penne in salted water; save a cup of the water before draining.', 'Brown the sausage in a large skillet 5 minutes, breaking it up; transfer to a plate.', 'Sauté the peppers and onion in the same pan 6 minutes until soft, add the garlic 1 minute.', 'Return the sausage with the diced tomatoes; simmer 8 minutes.', 'Toss with the pasta and a splash of its water; serve with parmesan.']::text[], 'https://images.unsplash.com/photo-1612929633738-8fe44f7ec841', 'Unsplash contributor', 'https://unsplash.com/photos/pasta-dish-on-black-plate-pbc2wXbQYpI', true),
  ('savory-cottage-cheese-breakfast-bowls', 'Savory Cottage Cheese Breakfast Bowls', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 2, 10, false, 'No-cook bowls of cottage cheese with cucumber, tomato and avocado, finished with olive oil and black pepper.', array['Dice the cucumber and the tomato and thinly slice the green onion.', 'Halve the avocado, remove the pit, scoop out the flesh with a spoon and slice it.', 'Divide the cottage cheese between two bowls and arrange the cucumber, tomato and avocado on top.', 'Drizzle with the olive oil, sprinkle with the salt, plenty of pepper and the green onion, and eat right away.']::text[], 'https://images.unsplash.com/photo-1657835813264-282b20ca950f', 'Anastasiia Chepinska', 'https://unsplash.com/photos/a-plate-of-food-lQ9rlsr7dD4', true),
  ('sesame-chicken-cabbage-salad', 'Sesame Chicken Cabbage Salad', 'lunch', array['dairy_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 15, true, 'Shredded rotisserie chicken and crunchy cabbage tossed in a sesame-ginger dressing with almonds and green onion.', array['Pull the meat off the chicken, discarding the skin and bones, and shred it into bite-size pieces with your fingers or two forks.', 'Grate the ginger and whisk it with the sesame oil, vegetable oil, soy sauce and rice vinegar in a large bowl.', 'Slice the green onions and roughly chop the cilantro and the almonds.', 'Add the coleslaw mix, chicken, green onions and cilantro to the bowl and toss 1 minute, until everything is evenly coated.', 'Let the salad stand 5 minutes so the cabbage softens slightly, then scatter the almonds on top and serve.']::text[], 'https://images.unsplash.com/photo-1678063460272-daeb9a9cf27c', 'Juno Jo', 'https://unsplash.com/photos/a-white-bowl-filled-with-lots-of-food-on-top-of-a-table-S-mXw4JCNm8', true),
  ('sheet-pan-chickpeas-vegetables-feta', 'Sheet-Pan Chickpeas and Vegetables', 'dinner', array['gluten_free', 'pescatarian', 'vegetarian']::text[], 4, 40, true, 'Chickpeas, sweet potato, broccoli and peppers roasted on one pan and finished with feta and lemon.', array['Heat the oven to {425F}.', 'In a large bowl, toss the sweet potato, bell pepper, red onion, zucchini and the drained, patted-dry chickpeas with the oil, smoked paprika, garlic powder, oregano and salt until evenly coated.', 'Spread over two sheet pans in a single layer, leaving space between the pieces so they roast instead of steam.', 'Roast 15 minutes, until the sweet potato starts to soften.', 'Divide the broccoli between the pans, toss and roast 12 to 15 minutes more, until the vegetables are browned at the edges and a fork slides easily into the sweet potato.', 'Cut the lemon in half, squeeze it over the pans and scatter the feta on top.']::text[], 'https://images.unsplash.com/photo-1578071768923-b3d68573028e', 'Louis Hansel', 'https://unsplash.com/photos/broccoli-and-carrots-on-white-plate-bPNvATD1cvc', true),
  ('sheet-pan-drumsticks-potatoes-carrots', 'Sheet-Pan Drumsticks with Potatoes and Carrots', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 45, false, 'Paprika-rubbed chicken drumsticks roasted on one pan with crispy potatoes and sweet carrots.', array['Heat the oven to {425F} and line a large sheet pan with foil.', 'Toss the potatoes and carrots on the pan with half the oil and half the salt and spread them into one layer.', 'Pat the drumsticks dry and rub them with the remaining oil, the paprika, garlic powder, onion powder, pepper and remaining salt.', 'Nestle the drumsticks among the vegetables, leaving a little space around each one.', 'Roast 35 to 40 minutes, turning the chicken and stirring the vegetables halfway, until the skin is crisp, the chicken reaches {175F} next to the bone and the potatoes are golden.', 'Spoon the pan juices over the chicken and vegetables and serve.']::text[], 'https://images.unsplash.com/photo-1599161146640-8d60bd2888e3', 'Branimir Petakov', 'https://unsplash.com/photos/brown-bread-with-yellow-fruits-HB0IbmJyyI8', true),
  ('sheet-pan-lemon-salmon-broccoli', 'Sheet-Pan Lemon Salmon & Broccoli', 'dinner', array['gluten_free', 'keto', 'low_carb', 'pescatarian']::text[], 4, 25, false, 'Salmon fillets and broccoli roasted together on one pan with garlic, butter and lemon.', array['Heat the oven to {425F}. Cut the broccoli into bite-size florets, mince the garlic and cut half the lemon into thin slices.', 'Toss the broccoli on a large sheet pan with the olive oil, garlic, pepper and most of the salt, spread it in one layer and roast 8 minutes.', 'Push the broccoli to the sides and lay the salmon in the middle, skin side down. Sprinkle the fish with the remaining salt, dot each fillet with butter and top with the lemon slices.', 'Roast 10 to 12 minutes until the salmon flakes easily with a fork and the broccoli is browned at the tips.', 'Squeeze the remaining lemon half over everything and serve.']::text[], 'https://images.unsplash.com/photo-1627857638952-642f8cbba8da', 'Ben Libby', 'https://unsplash.com/photos/brown-bread-on-white-ceramic-plate-xJBeGxiSYBE', true),
  ('sheet-pan-paprika-drumsticks-potatoes', 'Sheet-Pan Paprika Drumsticks & Potatoes', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 45, false, 'Budget drumsticks and potato wedges roasted together in a smoky paprika and garlic rub until crisp.', array['Heat the oven to {425F} and line a large sheet pan with foil.', 'Scrub the potatoes and cut each one lengthwise into 8 wedges. Pat the drumsticks dry with paper towels so the skin crisps.', 'On the pan, toss the drumsticks and potatoes with the olive oil, both paprikas, the garlic powder, onion powder, salt and pepper until evenly coated.', 'Spread everything in one layer, potatoes cut side down, with space between the pieces.', 'Roast 40 minutes, turning the chicken and potatoes once halfway, until the skin is crisp, the juices run clear near the bone ({165F}) and the wedges are golden and tender.']::text[], 'https://images.unsplash.com/photo-1705088295364-6e98d62a3146', 'Gourmet Lenz', 'https://unsplash.com/photos/a-plate-of-food-that-includes-chicken-potatoes-and-coleslaw-zlob_4tPETs', true),
  ('sheet-pan-pork-tenderloin-sweet-potatoes', 'Sheet-Pan Pork Tenderloin with Sweet Potatoes', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 45, false, 'Honey-mustard pork tenderloin roasted on one pan with sweet potatoes and green beans.', array['Heat the oven to {425F} and line a large sheet pan with foil.', 'Toss the sweet potatoes on the pan with half the oil and half the salt, spread them into one layer and roast 10 minutes.', 'Meanwhile, mix the mustard, honey, garlic powder, smoked paprika, pepper and remaining salt and rub it all over the pork.', 'Toss the green beans with the remaining oil.', 'Push the sweet potatoes to the sides of the pan, set the pork in the center and scatter the green beans around it.', 'Roast about 20 minutes until the pork reaches {145F} in the thickest part and the sweet potatoes are tender and browned at the edges.', 'Rest the pork 5 minutes on a board, slice it into rounds and serve with the vegetables.']::text[], 'https://images.unsplash.com/photo-1606258868842-79eb9eff76af', 'Samuel Regan-Asante', 'https://unsplash.com/photos/sliced-bread-on-blue-and-white-ceramic-plate-e3AA8nJMwTI', true),
  ('sheet-pan-teriyaki-salmon', 'Sheet Pan Teriyaki Salmon', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 30, false, 'Salmon and green beans roasted together with a homemade teriyaki glaze.', array['Heat the oven to {400F} and line a sheet pan with parchment.', 'Stir the soy sauce, sugar, vinegar, garlic and ginger in a small bowl.', 'Place the salmon on the pan with the green beans around it, brush everything with oil and season the beans with salt.', 'Roast 12 to 14 minutes, brushing the salmon with sauce twice, until it flakes easily.', 'Serve over rice with sesame seeds scattered on top.']::text[], 'https://images.unsplash.com/photo-1766701753139-352e46e51c01', 'Unsplash contributor', 'https://unsplash.com/photos/roast-vegetables-including-carrots-and-brussels-sprouts-on-table-JYnuDMMq68Q', true),
  ('shrimp-ajillo-tacos', 'Garlic Shrimp Tacos', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 20, false, 'Shrimp sizzled in garlic-lime butterless sauce, tucked into tortillas with slaw.', array['Toss the coleslaw mix with the lime juice and a pinch of salt; set aside.', 'Heat the oil in a large skillet over medium heat and cook the garlic and red pepper flakes 1 minute until fragrant.', 'Raise the heat, add the shrimp and cook 2 minutes per side until pink.', 'Serve in warm tortillas topped with the slaw.']::text[], 'https://images.unsplash.com/photo-1652957705092-b2f8d357c8a2', 'Unsplash contributor', 'https://unsplash.com/photos/a-white-plate-topped-with-shrimp-and-veggies-_aePGhfNhhI', true),
  ('shrimp-fried-rice', 'Shrimp Fried Rice', 'dinner', array['pescatarian', 'dairy_free']::text[], 4, 25, false, 'Garlicky shrimp fried rice with peas, carrots and egg ribbons.', array['Heat 1 tablespoon of oil in a large skillet over high heat and scramble the eggs 1 minute; transfer to a plate.', 'Add 1 more tablespoon of oil and cook the shrimp 2 minutes per side until pink; transfer to the plate.', 'Stir-fry the carrots and peas 3 minutes in the remaining oil, then add the garlic and cook 30 seconds.', 'Add the rice and fry 3 minutes until hot, breaking up clumps.', 'Return the shrimp and eggs with the soy sauce and sesame oil, toss 1 minute and serve.']::text[], 'https://images.unsplash.com/photo-1788603907442-253dd51b1aec', 'Unsplash contributor', 'https://unsplash.com/photos/fried-rice-with-mixed-vegetables-OZXQcw8W4H0', true),
  ('shrimp-puttanesca', 'Shrimp Puttanesca', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 25, false, 'Briny tomato-olive sauce with shrimp over spaghetti.', array['Cook the spaghetti in salted water; save a cup of the water before draining.', 'Sauté the garlic and red pepper flakes in olive oil 1 minute, add the tomatoes and olives; simmer 10 minutes.', 'Add the shrimp and simmer 3 to 4 minutes until pink and cooked.', 'Toss with the pasta and a splash of its water; serve with parsley.']::text[], 'https://images.unsplash.com/photo-1762631178192-f331d9549fc9', 'Unsplash contributor', 'https://unsplash.com/photos/spaghetti-with-shrimp-and-a-flower-garnish-kfFKc9jtB0s', true),
  ('sicilian-cauliflower-pasta', 'Sicilian-Style Cauliflower Pasta', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 35, false, 'Golden cauliflower with garlic, chili and breadcrumbs over pasta.', array['Cook the pasta in salted water; save a cup of the water before draining.', 'Sear the cauliflower in olive oil 8 minutes until deep golden and tender; add the garlic and pepper flakes 1 minute.', 'Toss with the pasta and a splash of its water.', 'Toast the breadcrumbs in a dry pan 2 minutes until crisp and scatter over the top.']::text[], 'https://images.unsplash.com/photo-1767065584295-e5879ad624c2', 'Unsplash contributor', 'https://unsplash.com/photos/fork-lifting-cheesy-lasagna-from-white-bowl-q6V1AvFZl3o', true),
  ('simple-pad-thai', 'Simple Pad Thai', 'dinner', array['dairy_free']::text[], 4, 30, false, 'Rice noodles with chicken, egg and peanuts in a tangy-sweet tamarind-style sauce.', array['Soak the rice noodles in hot tap water 15 minutes until pliable; drain.', 'Whisk the fish sauce, sugar, vinegar and soy sauce in a small bowl.', 'Heat the oil in a large skillet over high heat and cook the chicken 5 minutes until cooked through; push to one side.', 'Scramble the eggs in the empty space 1 minute, then add the noodles and sauce.', 'Toss 3 to 4 minutes until the noodles are tender and coated; serve with peanuts, green onion and lime.']::text[], 'https://images.unsplash.com/photo-1788927791589-aa6d59e892e5', 'Unsplash contributor', 'https://unsplash.com/photos/pad-thai-bowls-with-scrambled-eggs-cTUHI-LMR2Y', true),
  ('simple-ramen-egg-bowls', 'Simple Ramen and Egg Bowls', 'dinner', array['dairy_free']::text[], 4, 20, false, 'Upgrade instant ramen with a soft egg, greens and a savory soy-ginger broth.', array['Bring the broth to a simmer with the garlic, ginger and soy sauce in a pot over medium heat.', 'Add the ramen noodles and cook 3 minutes until just tender.', 'Lower to a gentle simmer, crack in the eggs spaced apart and poach 3 to 4 minutes until the whites set.', 'Stir in the spinach until wilted.', 'Ladle into bowls and top with green onion and a few drops of sesame oil.']::text[], 'https://images.unsplash.com/photo-1779453873118-0321c47aa1fd', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-ramen-with-pork-eggs-and-green-onions-bfzAPllbqb0', true),
  ('skillet-pork-chops-green-beans-potatoes', 'Skillet Pork Chops with Green Beans and Potatoes', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 30, false, 'Pan-seared seasoned pork chops with garlic butter green beans and tender baby potatoes.', array['Put the potatoes in a large pot, cover with cold water, add half the salt and bring to a boil over high heat.', 'Lower the heat to medium and simmer 10 to 12 minutes until a knife slides in easily, adding the green beans for the last 4 minutes so they turn bright green and crisp-tender; drain both.', 'While the potatoes cook, pat the pork chops dry and season both sides with the paprika, garlic powder, pepper and remaining salt.', 'Heat the oil in a large skillet over medium-high heat and sear the chops 4 to 5 minutes per side until deep golden and {145F} in the center.', 'Move the chops to a plate to rest, lower the heat to medium-low and melt the butter in the same pan with the garlic for 30 seconds until fragrant.', 'Add the potatoes and green beans, toss 1 to 2 minutes until coated in the garlic butter, and serve with the chops.']::text[], 'https://images.unsplash.com/photo-1703219342022-e3eb5c216c61', 'Hybrid Storytellers', 'https://unsplash.com/photos/a-close-up-of-a-plate-of-food-on-a-table-WlELSb2TEfU', true),
  ('skillet-shakshuka-with-feta', 'Skillet Shakshuka with Feta', 'dinner', array['gluten_free', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 25, false, 'Eggs poached in a smoky tomato and pepper sauce, finished with crumbled feta.', array['Heat the oil in a large skillet over medium heat and cook the onion and bell pepper for 6 minutes, stirring, until soft.', 'Stir in the garlic, tomato paste, cumin, smoked paprika and red pepper flakes and cook 1 minute, until fragrant.', 'Add the tomatoes with their juice and the salt and simmer 8 minutes, stirring now and then, until the sauce is thick enough to hold a line when you drag a spoon through it.', 'With the back of a spoon, make a well in the sauce for each egg and crack an egg into each one.', 'Cover and cook over medium-low heat for 5 to 7 minutes, until the whites are set and the yolks are still soft.', 'Scatter the feta and cilantro over the top and serve straight from the skillet.']::text[], 'https://images.unsplash.com/photo-1582492710145-d723e0a219f8', 'amirali mirhashemian', 'https://unsplash.com/photos/stainless-steel-bowl-with-food-K9oKpOebg84', true),
  ('skillet-tuna-melts', 'Skillet Tuna Melts', 'lunch', array['high_protein', 'low_carb', 'pescatarian']::text[], 2, 15, false, 'Tuna salad and melted cheese griddled between buttered bread until crisp and golden.', array['Drain the tuna well and flake it in a bowl. Finely dice the celery and mix it in with the mayonnaise, mustard and pepper.', 'Butter one side of each slice of bread.', 'Set two slices buttered-side down in a large cold skillet, spread the tuna salad to the edges, top each with a slice of cheese and close with the remaining bread, buttered-side up.', 'Cook over medium-low heat 3 to 4 minutes, until the underside is deep golden.', 'Flip carefully with a wide spatula and cook 3 minutes more, until golden and the cheese has melted.', 'Cut each sandwich in half and serve hot.']::text[], 'https://images.unsplash.com/photo-1537494792426-7c8526686fb9', 'Eiliv Aceron', 'https://unsplash.com/photos/sandwich-on-brown-board-AKBoj1mA7ck', true),
  ('sloppy-joes-with-quick-coleslaw', 'Sloppy Joes with Quick Coleslaw', 'dinner', array['dairy_free']::text[], 4, 20, false, 'Saucy sweet-and-tangy ground beef piled on toasted buns with a fast creamy coleslaw.', array['Toss the coleslaw mix with the mayonnaise, vinegar and half the salt in a bowl and chill it while you cook.', 'Heat a large skillet over medium-high heat and cook the ground beef with the onion and bell pepper 7 minutes, breaking up the meat, until no pink remains and the vegetables are soft; spoon off most of the fat.', 'Stir in the tomato sauce, ketchup, brown sugar, Worcestershire, mustard and remaining salt.', 'Lower the heat to medium and simmer 6 to 8 minutes, stirring now and then, until thick enough to mound on a spoon.', 'Split the buns and toast them cut-side down in a dry skillet over medium heat 1 to 2 minutes until golden.', 'Pile the beef onto the buns and serve with the coleslaw on the side or on top.']::text[], 'https://images.unsplash.com/photo-1432752641289-a25fc853fceb', 'Brandon Morgan', 'https://unsplash.com/photos/burger-and-fries-on-bowl-fGYeKt1E6hc', true),
  ('slow-cooker-beef-stew', 'Slow Cooker Beef Stew', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 6, 480, true, 'Classic beef stew with potatoes and carrots, ready when you walk in the door.', array['Season the beef with the salt and pepper.', 'Place the beef, potatoes, carrots, onion and garlic in the slow cooker.', 'Pour in the broth, tomato paste and worcestershire; stir.', 'Cook on low 8 hours until the beef is fork-tender; stir in the peas at the end.']::text[], 'https://images.unsplash.com/photo-1627366422957-3efa9c6df0fc', 'Unsplash contributor', 'https://unsplash.com/photos/soup-with-meat-in-white-ceramic-bowl-eI_Uk6uGCOQ', true),
  ('slow-cooker-chicken-chili', 'Slow Cooker Chicken Chili', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 6, 360, true, 'White-bean chicken chili that cooks itself — dump and walk away.', array['Place the chicken, beans, chiles, tomatoes, onion, garlic and spices in the slow cooker with a pinch of salt.', 'Cook on low 6 hours.', 'Shred the chicken right in the pot with two forks and stir everything together.', 'Serve with your favorite toppings.']::text[], 'https://images.unsplash.com/photo-1764314108477-f026172e32a9', 'Unsplash contributor', 'https://unsplash.com/photos/hearty-stew-with-chunks-of-meat-and-red-chili-peppers-a-p0M2ZTlj0', true),
  ('slow-cooker-green-chile-pork-stew', 'Slow Cooker Green Chile Pork Stew', 'dinner', array['dairy_free', 'high_protein']::text[], 6, 450, true, 'Pork shoulder, potatoes and green chiles cooked low and slow until the meat falls apart, served with warm tortillas.', array['Trim the thick outer fat from the pork and cut the meat into large chunks, about the size of an egg.', 'Put the pork in the slow cooker with the onion, garlic, potatoes, green chiles, cumin, oregano, salt and pepper.', 'Pour in the broth, stir, cover and cook on low for 7 hours (or on high for 4 hours) until the pork pulls apart easily with a fork.', 'Break the pork into smaller pieces with a spoon and mash a few of the potatoes into the broth to thicken it.', 'Stir in the lime juice and half of the cilantro, taste and adjust the salt.', 'Serve in bowls with the rest of the cilantro and the tortillas.']::text[], 'https://images.unsplash.com/photo-1792427566393-5c55fb19adb7', 'Michael Navarro', 'https://unsplash.com/photos/green-soup-with-meat-and-corn-4zjhGV486rc', true),
  ('slow-cooker-lentil-soup', 'Slow Cooker Lentil Soup', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 6, 360, true, 'Hands-off lentil soup with carrots, tomatoes and cumin — cheap and filling.', array['Place the lentils, carrot, onion, celery, garlic, tomatoes and cumin in the slow cooker.', 'Pour in the broth and stir once to combine.', 'Cook on low 6 hours until the lentils are completely tender.', 'Stir in the vinegar and salt, taste and serve.']::text[], 'https://images.unsplash.com/photo-1608500219063-e5164085cd6f', 'Unsplash contributor', 'https://unsplash.com/photos/white-ceramic-bowl-with-food-JXYdIWqA5IM', true),
  ('slow-cooker-pot-roast', 'Slow Cooker Pot Roast', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 6, 480, true, 'Fall-apart pot roast with vegetables and rich gravy.', array['Season the roast with salt and pepper and place it in the slow cooker.', 'Arrange the potatoes, carrots and onion around it.', 'Pour in the broth and worcestershire.', 'Cook on low 8 hours until the roast shreds; serve with the vegetables and juices.']::text[], 'https://images.unsplash.com/photo-1509402308-817902776267', 'Unsplash contributor', 'https://unsplash.com/photos/roast-meat-top-with-slice-limes-a2scGjpiI5E', true),
  ('slow-cooker-pulled-pork', 'Slow Cooker Pulled Pork', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 6, 480, true, 'Set-and-forget pork shoulder that shreds itself, for sandwiches, tacos or rice bowls.', array['Season the pork with the salt, paprika, cumin and brown sugar.', 'Place the onion and garlic in the slow cooker, set the pork on top and add half a cup of water.', 'Cook on low 8 hours until the pork shreds easily with a fork.', 'Shred it in the pot, toss with the juices and serve.']::text[], 'https://images.unsplash.com/photo-1679744034962-c0650a2a20b3', 'Unsplash contributor', 'https://unsplash.com/photos/a-person-holding-a-sandwich-in-their-hand-q6bnRITHmEY', true),
  ('slow-cooker-pulled-pork-sandwiches', 'Slow Cooker Pulled Pork Sandwiches', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 450, true, 'Pork shoulder slow-cooked until it shreds, tossed in BBQ sauce and piled on buns with creamy coleslaw.', array['Mix the brown sugar, smoked paprika, garlic powder and most of the salt and rub it all over the pork.', 'Spread the sliced onion in the slow cooker, set the pork on top and pour in half the vinegar and half a cup of water.', 'Cover and cook on low 7 hours until the pork falls apart when pressed with a fork.', 'Lift the pork onto a board, shred it with two forks and discard any large pieces of fat.', 'Pour off most of the liquid from the slow cooker, return the pork to the onions and stir in the BBQ sauce; cover and warm on low 10 minutes.', 'Toss the coleslaw mix with the mayonnaise, the remaining vinegar and the remaining salt.', 'Pile the pork and coleslaw onto the buns and serve.']::text[], 'https://images.unsplash.com/photo-1680404971036-33eaa1d2d840', 'Thomas Wavid Johns', 'https://unsplash.com/photos/a-pulled-pork-sandwich-with-a-side-of-tater-tots-L-2p59uIP1E', true),
  ('slow-cooker-pulled-pork-slaw-bowls', 'Slow-Cooker Pulled Pork Slaw Bowls', 'dinner', array['dairy_free', 'gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 480, true, 'Spice-rubbed pork shoulder cooked low and slow, shredded and piled over tangy slaw and spinach.', array['Mix the smoked paprika, garlic powder, onion powder, cumin, salt and pepper and rub the mix all over the pork.', 'Put the pork in the slow cooker, pour the broth and half the vinegar around it, cover and cook on low 7 to 8 hours, until the meat falls apart when pressed with a fork.', 'Lift the pork into a large bowl and shred it with two forks, discarding any large pieces of fat.', 'Stir a few spoonfuls of the cooking juices into the shredded pork until it is moist but not soupy.', 'In another bowl toss the coleslaw mix with the mayo, mustard and remaining vinegar until evenly coated.', 'Divide the spinach and slaw among bowls and pile the pork on top.']::text[], 'https://images.unsplash.com/photo-1622756144420-6877b1b7476e', 'Grooveland Designs', 'https://unsplash.com/photos/cooked-food-on-stainless-steel-bowl-8kkTIumkHxU', true),
  ('slow-cooker-salsa-chicken', 'Slow Cooker Salsa Chicken', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 300, true, 'Two-ingredient shredded chicken for tacos, bowls and burritos all week.', array['Place the chicken in the slow cooker and pour the salsa over it.', 'Cook on low 5 hours.', 'Shred it in the pot and stir it into the sauce.', 'Serve in tacos, over rice or in bowls.']::text[], 'https://images.unsplash.com/photo-1545093149-618ce3bcf49d', 'Unsplash contributor', 'https://unsplash.com/photos/taco-with-vegetables-s6SOj6uYjXI', true),
  ('slow-cooker-turkey-tacos', 'Slow Cooker Turkey Taco Meat', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 6, 300, true, 'A big batch of saucy taco turkey for the week''s tacos, bowls and burritos.', array['Place the turkey in the slow cooker.', 'Pour the salsa, taco seasoning and green chiles over it and stir to coat.', 'Cook on low 5 hours, breaking it up once halfway.', 'Stir well and serve in tacos or bowls.']::text[], 'https://images.unsplash.com/photo-1767354063743-a296165b0685', 'Unsplash contributor', 'https://unsplash.com/photos/a-large-metal-bowl-filled-with-a-spicy-meat-dish-m4vcvVjIlVQ', true),
  ('smashed-chickpea-salad-sandwiches', 'Smashed Chickpea Salad Sandwiches', 'lunch', array['dairy_free', 'pescatarian']::text[], 4, 15, true, 'A no-cook sandwich filling of mashed chickpeas with mayo, mustard, lemon and celery, served with lettuce and tomato.', array['Drain and rinse the chickpeas, pat them dry and put them in a medium bowl.', 'Mash them with a fork or potato masher until most are broken up but some chunks remain.', 'Finely dice the celery and slice the green onion. Add them to the bowl with the mayonnaise, mustard, lemon juice, salt and pepper and stir until creamy.', 'Taste and adjust the salt and lemon. Slice the tomato and separate the romaine leaves.', 'Spread the chickpea salad on half of the bread slices, top with lettuce and tomato, close with the remaining bread and cut each sandwich in half.']::text[], 'https://images.unsplash.com/photo-1540713434306-58505cf1b6fc', 'Pille R. Priske', 'https://unsplash.com/photos/clubhouse-sandwich-U0PiIS4Uvkc', true),
  ('smoked-sausage-cabbage-potato-skillet', 'Smoked Sausage, Cabbage and Potato Skillet', 'dinner', array['gluten_free']::text[], 4, 30, false, 'Browned smoked sausage fried with tender cabbage, diced potatoes and onion in one skillet.', array['Heat the oil in a large skillet over medium-high heat and brown the sliced sausage 4 minutes, turning once, until the edges are dark golden; lift it out onto a plate.', 'Lower the heat to medium, melt the butter in the same pan and add the potatoes in one layer.', 'Cover and cook 10 minutes, stirring two or three times, until the potatoes are golden and almost tender.', 'Add the onion, cabbage, garlic, salt and pepper and cook uncovered 8 minutes, stirring often, until the cabbage is wilted and tender and a knife slides easily into the potatoes.', 'Return the sausage to the pan and stir in the mustard and vinegar.', 'Cook 1 more minute, scraping up the browned bits from the bottom, and serve hot.']::text[], 'https://images.unsplash.com/photo-1592259695987-4aa79c3c34a6', 'Amr Taha™', 'https://unsplash.com/photos/sliced-vegetables-on-brown-wooden-chopping-board-KtbmX7bBR-U', true),
  ('smoked-sausage-lentil-stew', 'Smoked Sausage and Lentil Stew', 'dinner', array['dairy_free', 'gluten_free']::text[], 4, 50, true, 'Dry lentils simmered with browned smoked sausage, vegetables, tomatoes and spinach into a thick, smoky stew.', array['Heat the oil in a large pot over medium-high heat and brown the sausage for 5 minutes until the edges are deep golden.', 'Add the onion, carrot and celery and cook over medium heat for 6 minutes until soft.', 'Add the garlic, smoked paprika and thyme and stir for 30 seconds until fragrant.', 'Rinse the lentils and add them with the tomatoes and their juice and the broth, then bring to a boil over high heat.', 'Lower the heat, partly cover and simmer for 25 to 30 minutes, stirring now and then, until the lentils are tender but not mushy.', 'Stir in the spinach, salt and pepper and cook for 2 minutes until the spinach wilts.', 'Stir in the vinegar, taste, adjust the salt and serve.']::text[], 'https://images.unsplash.com/photo-1621179815459-073503f7b444', 'Marlon Alves', 'https://unsplash.com/photos/white-ceramic-bowl-with-soup-nHmr9pU3tNs', true),
  ('smoked-sausage-pepper-cabbage-skillet', 'Smoked Sausage, Pepper & Cabbage Skillet', 'dinner', array['gluten_free', 'keto', 'low_carb']::text[], 4, 25, false, 'Sliced smoked sausage fried with cabbage, onion and green pepper for a cheap, filling one-pan dinner.', array['Slice the sausage into coins, chop the cabbage into bite-size pieces, slice the onion, cut the bell pepper into strips and mince the garlic.', 'Heat a large skillet over medium-high heat. Add the sausage (no oil is needed) and cook 4 to 5 minutes, turning the pieces, until browned on both sides.', 'Add the butter, onion and bell pepper and cook 3 minutes until they start to soften.', 'Add the cabbage, garlic, smoked paprika and pepper and stir well.', 'Cook 8 to 10 minutes, stirring every couple of minutes, until the cabbage is tender and browned at the edges.', 'Stir in the vinegar, scrape up the browned bits from the pan and serve.']::text[], 'https://images.unsplash.com/photo-1726177974269-a03507107f71', 'Victor Birai', 'https://unsplash.com/photos/a-wooden-spoon-in-a-pot-of-food-Rc1iuBwnb0A', true),
  ('smoky-black-bean-soup', 'Smoky Black Bean Soup', 'lunch', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 30, true, 'Canned black beans simmered with onion, pepper, cumin and smoked paprika, partly mashed and finished with lime.', array['Dice the onion and bell pepper and mince the garlic.', 'Heat the olive oil in a large pot over medium heat and cook the onion and pepper 6 minutes, until soft.', 'Stir in the garlic, cumin, oregano and smoked paprika for 30 seconds, until fragrant.', 'Add the beans with their liquid, the broth, salt and pepper. Bring to a boil over high heat, then lower the heat to medium-low and simmer uncovered 15 minutes, until slightly thickened.', 'Mash about a third of the beans against the side of the pot with a potato masher or the back of a spoon, until the soup is creamy but still chunky.', 'Stir in the lime juice, taste for salt, and serve topped with the chopped cilantro.']::text[], 'https://images.unsplash.com/photo-1659603606213-cb19636f9f34', 'Green And Great', 'https://unsplash.com/photos/a-bowl-of-soup-aHko8K3U7as', true),
  ('sopa-de-tortilla', 'Tortilla Soup', 'dinner', array['gluten_free', 'dairy_free']::text[], 4, 35, true, 'Tomato-chile broth with chicken, topped with crispy tortilla strips and avocado.', array['Bake the tortilla strips at {400F} 8 minutes until crisp (or fry them in a little oil).', 'Sauté the onion in hot oil 4 minutes, add the garlic, cumin and chili powder and cook 1 minute.', 'Add the tomatoes, broth and chicken; simmer 15 minutes.', 'Season with salt and lime juice; serve topped with the tortilla strips, avocado and cilantro.']::text[], 'https://images.unsplash.com/photo-1786052599180-aea3127970b6', 'Unsplash contributor', 'https://unsplash.com/photos/plate-of-chili-with-rice-radish-and-a-tortilla-chip-g5rB3Zg4gzI', true),
  ('southwest-quinoa-black-bean-salad', 'Southwest Quinoa and Black Bean Salad', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 30, true, 'Quinoa tossed with black beans, corn, peppers and avocado in a cumin lime dressing.', array['Rinse the quinoa in a fine strainer under cold water for 30 seconds to wash off its bitter coating.', 'Put it in a saucepan with twice as much water as quinoa, bring to a boil, cover and cook over low heat for 15 minutes, until the water is absorbed and the grains show little white tails.', 'Spread the quinoa on a large plate and let it cool for 10 minutes.', 'Meanwhile, whisk the juice of the limes, the oil, cumin, chili powder and salt in a large bowl.', 'Add the drained beans and corn, the bell pepper, tomato and green onion and toss.', 'Fold in the cooled quinoa and the cilantro, and top with the avocado just before serving.']::text[], 'https://images.unsplash.com/photo-1505576633757-0ac1084af824', 'Mariana Medvedeva', 'https://unsplash.com/photos/plate-full-of-salad-with-spice-on-top-of-brown-board-fk6IiypMWss', true),
  ('spicy-tuna-sushi-bowls', 'Spicy Tuna Sushi Bowls', 'dinner', array['pescatarian', 'dairy_free', 'high_protein']::text[], 4, 20, false, 'Deconstructed sushi bowls with spicy tuna, cucumber, avocado and seasoned rice.', array['Cook the rice, then fold in the vinegar, sugar and a pinch of salt while warm.', 'Drain the tuna and mix it with the mayo, sriracha and half the green onion.', 'Divide the rice between bowls and top with the tuna, cucumber and avocado.', 'Drizzle with soy sauce and finish with the remaining green onion and sesame seeds.']::text[], 'https://images.unsplash.com/photo-1780805663576-48cdd496138d', 'Unsplash contributor', 'https://unsplash.com/photos/fresh-colorful-poke-bowl-on-a-round-wooden-table-H-DKnqVDOUk', true),
  ('spinach-feta-oven-frittata', 'Spinach and Feta Oven Frittata', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 35, false, 'A thick baked egg frittata packed with spinach, cottage cheese, feta and cheddar.', array['Heat the oven to {400F}.', 'Melt the butter with the oil in a large oven-safe skillet over medium heat and cook the onion for 4 minutes, until soft.', 'Add the garlic, then the spinach a handful at a time, and stir 2 minutes, until the spinach is wilted and the pan is nearly dry.', 'Whisk the eggs in a bowl with the cottage cheese, cheddar, salt and pepper until combined.', 'Pour the eggs over the spinach, stir once to spread everything out and scatter the feta on top.', 'Cook 2 minutes without stirring, until the edges begin to set, then move the skillet to the oven.', 'Bake 14 to 16 minutes, until puffed and the center no longer jiggles when you shake the pan.', 'Rest 5 minutes, then cut into wedges; use an oven mitt, because the handle stays hot.']::text[], 'https://images.unsplash.com/photo-1607877200978-3cab430e00cd', 'Carlos Perales', 'https://unsplash.com/photos/sliced-pizza-with-red-sauce-on-white-ceramic-plate-aIfV9vtoHn4', true),
  ('spinach-ricotta-stuffed-shells', 'Stuffed Shells-Style Pasta', 'dinner', array['vegetarian']::text[], 4, 50, true, 'Ricotta-spinach filling under marinara and mozzarella — simplified stuffed shells.', array['Heat the oven to {375F} and cook the pasta 2 minutes less than the package; drain.', 'Squeeze the spinach dry and mix it with the ricotta, half the mozzarella, the parmesan and a pinch of salt.', 'Fold the filling through the pasta in a baking dish.', 'Cover with marinara and the remaining mozzarella; bake 25 minutes until bubbly.']::text[], 'https://images.unsplash.com/photo-1788464730134-333936411dc2', 'Unsplash contributor', 'https://unsplash.com/photos/baked-spinach-and-cheese-casserole-avoA6dZXjyw', true),
  ('steak-fajitas-skillet', 'Skillet Steak Fajitas', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 30, false, 'Charred steak strips with peppers and onions, warm tortillas and lime.', array['Season the steak with salt and sear it in a very hot oiled skillet 3 minutes per side; transfer to a board to rest.', 'Add the peppers and onion to the same pan and stir-fry 5 minutes until charred at the edges.', 'Slice the steak thin against the grain and return it to the pan with any juices; toss 1 minute.', 'Warm the tortillas in a dry skillet.', 'Serve the steak and vegetables in the tortillas with lime wedges.']::text[], 'https://images.unsplash.com/photo-1723531055833-49fb132cbaab', 'Unsplash contributor', 'https://unsplash.com/photos/a-white-plate-topped-with-meat-and-veggies-rEEvc3q_vrk', true),
  ('strawberry-cottage-cheese-granola-bowls', 'Strawberry Cottage Cheese Granola Bowls', 'breakfast', array['high_protein', 'pescatarian']::text[], 2, 5, false, 'Protein-packed cottage cheese topped with sliced strawberries, crunchy granola and a drizzle of honey.', array['Rinse the strawberries under cold water and pat them dry with a paper towel.', 'Cut off the green tops and slice the strawberries; just halve the small ones.', 'Stir the cottage cheese and divide it between bowls, one per serving.', 'Arrange the strawberries on top and scatter the granola over them.', 'Drizzle with the honey and eat right away, while the granola is crunchy.']::text[], 'https://images.unsplash.com/photo-1614630536994-a6b781d56e15', 'Olena Bohovyk', 'https://unsplash.com/photos/strawberry-and-blackberry-on-white-ceramic-bowl-odLdpSRRZtQ', true),
  ('stuffed-pepper-soup', 'Stuffed Pepper Soup', 'dinner', array['gluten_free']::text[], 6, 45, true, 'Everything in a stuffed pepper, in a pot: ground beef, bell peppers, tomatoes and rice in a savory broth.', array['Brown the ground beef in a large pot over medium-high heat for 6 to 8 minutes, breaking it up with a spoon, until no pink remains, then spoon off most of the fat.', 'Add the oil, onion and bell peppers and cook over medium heat for 6 minutes until they begin to soften.', 'Add the garlic and Italian seasoning and stir for 1 minute until fragrant.', 'Add the tomatoes with their juice, tomato sauce, broth, salt and pepper and bring to a boil over high heat.', 'Stir in the rice, lower the heat, cover and simmer for 18 to 20 minutes, stirring once or twice, until the rice is tender.', 'Taste, adjust the salt and serve sprinkled with the parmesan.']::text[], 'https://images.unsplash.com/photo-1666819632298-fe15dc7d4c34', 'Leanna Myers', 'https://unsplash.com/photos/a-bowl-of-soup-with-a-spoon-omP-kDbTc8w', true),
  ('sweet-chili-shrimp', 'Sweet Chili Shrimp', 'dinner', array['pescatarian', 'gluten_free', 'dairy_free', 'high_protein']::text[], 4, 20, false, 'Seared shrimp glazed in a quick sweet chili-lime sauce over rice.', array['Cook the rice according to the package directions.', 'Stir the sugar, vinegar, sriracha, fish sauce and garlic in a small bowl.', 'Pat the shrimp dry, season with salt and sear in hot oil 2 minutes per side until pink.', 'Pour in the sauce, toss 1 minute until it coats the shrimp and serve over rice with green onion.']::text[], 'https://images.unsplash.com/photo-1768326119244-6b7055143e5f', 'Unsplash contributor', 'https://unsplash.com/photos/a-bowl-of-rice-with-toppings-chili-oil-and-chopsticks-EXfWNPsiu8s', true),
  ('teriyaki-chicken-bowls', 'Teriyaki Chicken Bowls', 'dinner', array['high_protein', 'dairy_free']::text[], 4, 30, true, 'Sweet-savory teriyaki chicken over rice with quick-pickled cucumber and carrots.', array['Cook the rice according to the package directions.', 'Stir the soy sauce, sugar, vinegar, garlic and ginger in a small bowl to make the teriyaki sauce.', 'Toss the cucumber and carrot with a pinch of salt and a tablespoon of the sauce; set aside to pickle lightly.', 'Heat the oil in a large skillet over medium-high heat and cook the chicken 6 to 7 minutes until golden and cooked through.', 'Pour in the rest of the sauce and simmer 2 minutes until it thickens and glazes the chicken.', 'Serve over rice with the pickled vegetables and green onion.']::text[], 'https://images.unsplash.com/photo-1783788357923-649e29b7b006', 'Unsplash contributor', 'https://unsplash.com/photos/two-grilled-chicken-skewers-with-an-egg-yolk-dip-tKJ1T1Vvvnw', true),
  ('thai-coconut-curry-chicken-soup', 'Thai Coconut Curry Chicken Soup', 'dinner', array['dairy_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 30, true, 'Sliced chicken, mushrooms and peppers in a red curry and coconut milk broth with lime and cilantro.', array['Heat the oil in a large pot over medium heat, add the curry paste, ginger and garlic and stir for 1 minute until fragrant.', 'Pour in the coconut milk and broth, stir until the paste dissolves and bring to a gentle boil.', 'Add the chicken, mushrooms and bell pepper, lower the heat and simmer for 8 to 10 minutes until the chicken is white all the way through.', 'Stir in the spinach and soy sauce and cook for 1 minute until the spinach wilts.', 'Take the pot off the heat, squeeze in the lime juice, taste and add a little more soy sauce if it needs salt.', 'Ladle into bowls and top with the cilantro.']::text[], 'https://images.unsplash.com/photo-1548943487-a2e4e43b4853', 'Nick Karvounis', 'https://unsplash.com/photos/seafood-ramen-platter-YmyFBvW7oG8', true),
  ('thai-red-curry-chicken', 'Thai Red Curry Chicken', 'dinner', array['dairy_free', 'high_protein']::text[], 4, 30, true, 'Chicken and bell peppers simmered in a creamy red curry coconut sauce over rice.', array['Cook the rice according to the package directions.', 'Heat the oil in a large skillet over medium-high heat and brown the chicken 4 minutes; it does not need to cook through.', 'Add the curry paste and cook 1 minute until fragrant, stirring constantly.', 'Pour in the coconut milk, soy sauce, brown sugar and the bell pepper; simmer 10 minutes until the chicken is cooked and the sauce thickens slightly.', 'Stir in the lime juice and serve over rice with cilantro.']::text[], 'https://images.unsplash.com/photo-1764304733301-3a9f335f0c67', 'Unsplash contributor', 'https://unsplash.com/photos/chicken-curry-in-a-white-bowl-with-sauce-VtNLbOAeO68', true),
  ('three-bean-vegetarian-chili', 'Three-Bean Vegetarian Chili', 'dinner', array['dairy_free', 'gluten_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 50, true, 'A thick meatless chili with black, kidney and pinto beans, corn and peppers.', array['Heat the oil in a large pot over medium heat and cook the onion and bell pepper 6 minutes, stirring, until soft.', 'Stir in the garlic, chili powder, cumin and smoked paprika and cook 1 minute, until the spices smell toasted.', 'Add the crushed and diced tomatoes, the drained beans and the broth and bring to a boil over high heat.', 'Lower to medium-low and simmer partly covered 30 minutes, stirring every 10 minutes, until thick enough that a spoon leaves a trail on the bottom of the pot.', 'Stir in the corn and cook 5 minutes more, until hot.', 'Taste, adjust the seasoning and serve.']::text[], 'https://images.unsplash.com/photo-1591266798549-32fa7cd32f45', 'micheile henderson', 'https://unsplash.com/photos/red-and-green-chili-peppers-in-white-ceramic-bowl-FhMB8pMge5U', true),
  ('tofu-broccoli-stir-fry', 'Tofu and Broccoli Stir-Fry', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 25, false, 'Crispy tofu and broccoli in a garlicky soy sauce over rice.', array['Cook the rice according to the package directions.', 'Toss the tofu cubes with the cornstarch and a pinch of salt.', 'Heat the oil in a large skillet over medium-high heat and fry the tofu 6 to 8 minutes, turning, until golden on most sides; transfer to a plate.', 'Stir-fry the broccoli 3 minutes with a splash of water until crisp-tender, then add the garlic.', 'Return the tofu, add the soy sauce, sesame oil and vinegar, toss 2 minutes and serve over rice.']::text[], 'https://images.unsplash.com/photo-1585032226651-759b368d7246', 'Unsplash contributor', 'https://unsplash.com/photos/stir-fried-noodles-with-vegetables-wEBg_pYtynw', true),
  ('tofu-egg-roll-bowls', 'Tofu Egg Roll in a Bowl', 'dinner', array['dairy_free', 'keto', 'low_carb', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 20, false, 'Crumbled tofu and cabbage stir-fried with ginger, garlic and soy sauce.', array['Press the tofu between paper towels to dry it and crumble it into bite-size pieces.', 'Heat the vegetable oil in a large skillet or wok over high heat and cook the tofu 6 minutes, stirring only now and then, until browned in spots.', 'Pour in the soy sauce mixture and toss everything for 1 minute until coated and glossy.', 'Add the garlic, ginger and coleslaw mix and stir-fry 3 to 4 minutes, until the cabbage wilts but still has some crunch.', 'Stir in the soy sauce, vinegar and sesame oil and cook 30 seconds more.', 'Serve in bowls topped with the green onion and a drizzle of sriracha.']::text[], 'https://images.unsplash.com/photo-1788536442033-abf6a485fef7', 'Zoshua Colah', 'https://unsplash.com/photos/tofu-salad-bowl-for-lunch-vAQ8bEmdKTk', true),
  ('tofu-scramble-black-bean-burritos', 'Tofu Scramble Black Bean Burritos', 'dinner', array['dairy_free', 'high_protein', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 25, false, 'Spiced scrambled tofu, black beans, peppers rolled into warm flour tortillas.', array['Drain the tofu, press it between paper towels to dry it, and crumble it with your hands into pieces the size of scrambled egg.', 'Heat the oil in a large skillet over medium-high heat and cook the onion and bell pepper for 4 minutes, stirring, until softened.', 'Add the tofu, cumin, chili powder, turmeric and salt and cook 6 minutes, stirring now and then, until the tofu looks dry and lightly browned.', 'Stir in the drained beans and cook 2 minutes, until hot all the way through.', 'Warm the tortillas one at a time in a dry skillet over medium heat, about 20 seconds per side, until soft and flexible.', 'Spoon the scramble down the center of each tortilla, top with salsa, fold in the sides and roll up tightly.']::text[], 'https://images.unsplash.com/photo-1566740933430-b5e70b06d2d5', 'Creative Headline', 'https://unsplash.com/photos/cooked-food-F10nTHkCiW8', true),
  ('tomato-basil-tortellini', 'Tortellini in Tomato-Basil Broth', 'dinner', array['vegetarian']::text[], 4, 25, true, 'Cheese tortellini simmered in a light tomato-basil broth.', array['Sauté the garlic in olive oil 1 minute, add the tomatoes and broth; simmer 8 minutes.', 'Add the tortellini and cook 4 minutes until tender.', 'Stir in the spinach until wilted and the basil.', 'Serve with parmesan on top.']::text[], 'https://images.unsplash.com/photo-1784751722792-83189db3ca61', 'Unsplash contributor', 'https://unsplash.com/photos/fresh-caprese-salad-with-sliced-tomatoes-mozzarella-pesto-and-basil-2qsJ_jZ7aTQ', true),
  ('tomato-cucumber-panzanella', 'Tomato and Cucumber Panzanella', 'lunch', array['dairy_free', 'low_carb', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 30, false, 'Italian bread salad: toasted bread cubes soaked in the juices of ripe tomatoes with cucumber, red onion and basil.', array['Heat the oven to {400F}. Tear or cut the bread into bite-size cubes and toss them on a sheet pan with a third of the olive oil and a pinch of the salt.', 'Bake 10 minutes, shaking the pan once, until golden and crisp outside but still a little chewy in the center. Let cool.', 'Cut the tomatoes into chunks, put them in a large bowl with the remaining salt, toss and let them sit 10 minutes to release their juices.', 'Slice the cucumber into half-moons, thinly slice the onion and mince the garlic.', 'Stir the remaining olive oil, the vinegar, garlic and pepper into the tomatoes and their juices.', 'Add the bread, cucumber, onion and torn basil leaves, toss well and let stand 10 minutes, tossing once, until the bread has soaked up the dressing without turning mushy.']::text[], 'https://images.unsplash.com/photo-1592417817098-8fd3d9eb14a5', 'Luisa Brimble', 'https://unsplash.com/photos/sliced-tomato-and-green-leaf-vegetable-on-white-ceramic-plate-vIm26fn_QKg', true),
  ('tuna-egg-salad-stuffed-avocados', 'Tuna Egg Salad Stuffed Avocados', 'lunch', array['dairy_free', 'gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian']::text[], 2, 25, false, 'Avocado halves filled with a lemony tuna and hard-boiled egg salad.', array['Put the eggs in a small pot and cover with cold water by about a finger''s width. Bring to a full boil over high heat, about 5 minutes.', 'Cover the pot, turn off the heat and let stand 11 minutes. Drain, cover the eggs with cold water for 3 minutes, then peel and chop them.', 'While the eggs cook, drain the tuna well, pressing out the liquid, and flake it into a bowl. Finely dice the celery and squeeze the lemon.', 'Add the chopped eggs, mayonnaise, celery, lemon juice, salt and pepper to the tuna and stir until creamy.', 'Just before serving, cut the avocados in half lengthwise around the pit, twist the halves apart and remove the pits.', 'Pile the salad into and over the avocado halves and serve with a spoon.']::text[], 'https://images.unsplash.com/photo-1715611935696-a59ebf388252', 'Elena Leya', 'https://unsplash.com/photos/a-white-plate-topped-with-two-stuffed-avocados-O7p7LgVC5KA', true),
  ('tuna-noodle-casserole-with-peas', 'Tuna Noodle Casserole with Peas', 'dinner', array['high_protein', 'pescatarian']::text[], 4, 40, true, 'Egg noodles, canned tuna and peas in a creamy cheddar sauce, baked with a crunchy breadcrumb top.', array['Bring a large pot of water to a boil over high heat and heat the oven to {400F}.', 'Boil the egg noodles 2 minutes less than the package says, then drain; they finish cooking in the oven.', 'Meanwhile, melt the butter in a second large pot over medium heat and cook the onion 4 minutes until soft.', 'Stir in the flour for 1 minute, then whisk in the milk a little at a time and simmer 4 to 5 minutes, whisking, until the sauce coats the back of a spoon.', 'Take the pot off the heat and stir in the cheddar, salt and pepper until melted, then fold in the noodles, tuna and peas.', 'Spread the mixture in a medium baking dish and sprinkle the breadcrumbs over the top.', 'Bake 18 minutes until bubbling at the edges and golden on top.']::text[], 'https://images.unsplash.com/photo-1611098876665-5384d4e39a1e', 'Brigitta Baranyi', 'https://unsplash.com/photos/rice-with-sliced-tomato-and-green-vegetable-in-clear-plastic-container-bCO7CphRIpM', true),
  ('turkey-and-spinach-lasagna', 'Turkey and Spinach Lasagna', 'dinner', array['high_protein']::text[], 4, 80, true, 'Layers of noodles, ground turkey marinara, spinach, cottage cheese and melted mozzarella.', array['Bring a large pot of water to a boil over high heat and heat the oven to {375F}.', 'Boil the lasagna noodles 6 to 8 minutes until just pliable, drain and lay them flat on a clean towel so they do not stick together.', 'Meanwhile, cook the turkey with the garlic and Italian seasoning in a large skillet over medium-high heat 6 minutes, breaking it up, until no pink remains, then stir in the marinara and half the salt.', 'Mix the cottage cheese with the egg, parmesan, spinach and remaining salt in a bowl.', 'Spread a thin layer of sauce in a square baking dish, then layer noodles, a third of the cottage cheese mixture, a third of the remaining sauce and a third of the mozzarella; repeat twice, trimming the noodles to fit and ending with mozzarella.', 'Cover with foil and bake 30 minutes, then uncover and bake 15 minutes more until bubbling at the edges and golden on top.', 'Rest 10 minutes so the layers set before slicing.']::text[], 'https://images.unsplash.com/photo-1625555897305-136548cc968c', 'Stefen Tan', 'https://unsplash.com/photos/brown-bread-on-white-ceramic-plate-8-r-1CZUcbA', true),
  ('turkey-bacon-avocado-wraps', 'Turkey, Bacon and Avocado Wraps', 'lunch', array['high_protein']::text[], 2, 15, false, 'Club-sandwich fillings rolled in a flour tortilla: deli turkey, crisp bacon, avocado, cheese, lettuce and tomato.', array['Lay the bacon in a cold skillet and cook over medium heat 8 minutes, turning now and then, until crisp. Drain on a paper towel.', 'Shred the romaine, slice the tomato thinly and slice the avocado.', 'Wipe out the skillet and warm each tortilla in it over medium heat 10 seconds per side, so it rolls without cracking.', 'Spread the mayonnaise over each tortilla, leaving a border, and layer the cheese, turkey, bacon, avocado, tomato and romaine in a line across the lower third.', 'Fold in the sides, roll up tightly from the bottom and cut each wrap in half on the diagonal.']::text[], 'https://images.unsplash.com/photo-1667451519899-793b85160223', 'Luther Yonel', 'https://unsplash.com/photos/a-group-of-coins-in-a-cup-yA9guldcm54', true),
  ('turkey-bolognese-zucchini-noodles', 'Turkey Bolognese Zucchini Noodles', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 30, false, 'A hearty ground turkey and tomato sauce spooned over tender zucchini noodles with plenty of parmesan.', array['Cut the zucchini into long thin noodles with a spiralizer, or shave them into wide ribbons with a vegetable peeler, stopping when you reach the seedy core. Mince the garlic.', 'Heat the olive oil in a large skillet over medium-high heat. Add the turkey and cook 6 to 7 minutes, breaking it up, until no pink remains; stir in the garlic and cook 30 seconds.', 'Stir in the crushed tomatoes, tomato paste, Italian seasoning and salt. When it bubbles, lower the heat to medium-low and simmer 12 minutes, stirring now and then, until thick.', 'While the sauce simmers, heat a second, dry skillet over medium-high heat and cook the zucchini noodles 2 to 3 minutes, tossing, until just tender but not limp; pour off any liquid.', 'Divide the noodles among plates, spoon the sauce over them and finish with the parmesan.']::text[], 'https://images.unsplash.com/photo-1671225548130-7ed32615ff3e', 'Sergi Ferrete', 'https://unsplash.com/photos/a-wooden-bowl-filled-with-pasta-and-vegetables-qdizmyoK3ig', true),
  ('turkey-cheddar-lettuce-roll-ups', 'Turkey and Cheddar Lettuce Roll-Ups', 'lunch', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 2, 10, false, 'No-cook, no-bread roll-ups of deli turkey and cheese in romaine leaves, with cucumber sticks.', array['Separate the romaine into its largest leaves, wash them and pat them completely dry so the spread sticks.', 'Stir the mayonnaise and mustard together in a small bowl.', 'Cut the cheese slices in half and the cucumber into sticks about as long as your finger.', 'Spread a thin line of the mustard mayonnaise down the center of each leaf.', 'Lay the turkey along each leaf, add a piece of cheese and roll up tightly from one long side. Rest the rolls seam side down or secure them with a toothpick.', 'Serve with the cucumber sticks, or pack both in a container and keep cold until lunch.']::text[], 'https://images.unsplash.com/photo-1622620283268-5cf46da1df39', 'Alexandra Tran', 'https://unsplash.com/photos/green-vegetable-on-red-ceramic-bowl-sVl2DJ4P9G8', true),
  ('turkey-taco-salad-bowls', 'Turkey Taco Salad Bowls', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb']::text[], 4, 20, false, 'Taco-seasoned ground turkey over crisp romaine with tomato, cheddar, avocado, salsa and sour cream; no chips needed.', array['Heat a large skillet over medium-high heat and add the turkey; cook 7 to 8 minutes, breaking it up, until browned and no pink remains.', 'Stir in the taco seasoning and a splash of water, lower the heat to medium and simmer 2 minutes until the liquid thickens and coats the meat.', 'While the turkey cooks, chop the romaine and dice the tomatoes and avocado.', 'Divide the romaine among 4 bowls and top with the warm turkey, tomato, cheddar and avocado.', 'Finish each bowl with a spoonful of salsa and one of sour cream.']::text[], 'https://images.unsplash.com/photo-1707080019893-bf8fc3d55f08', 'Caroline Ross', 'https://unsplash.com/photos/a-white-bowl-filled-with-lettuce-and-meat-D1u7ibM8vKU', true),
  ('turkey-two-bean-chili', 'Turkey & Two-Bean Chili', 'dinner', array['dairy_free', 'gluten_free', 'high_protein']::text[], 4, 45, true, 'A big pot of ground turkey chili with kidney and black beans, peppers and tomatoes; better the next day.', array['Dice the onion and bell pepper, mince the garlic, and drain and rinse both cans of beans.', 'Heat the olive oil in a large pot over medium-high heat. Add the turkey, onion and bell pepper and cook 7 to 8 minutes, breaking up the meat, until it is no longer pink and the vegetables are soft.', 'Stir in the garlic, chili powder, cumin and salt and cook 1 minute until fragrant.', 'Add the diced tomatoes with their juice, the tomato sauce, broth and beans and bring to a boil.', 'Lower the heat to medium-low and simmer uncovered 25 minutes, stirring now and then, until the chili is thick.', 'Taste, add a little more salt or chili powder if you like, and serve in bowls.']::text[], 'https://images.unsplash.com/photo-1576020956260-490f5c5fc892', 'Brooke Lark', 'https://unsplash.com/photos/cooked-viand-on-white-container-kFYjbRnklo4', true),
  ('turkish-eggs-with-garlic-yogurt', 'Turkish Eggs with Garlic Yogurt', 'breakfast', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 2, 15, false, 'Poached eggs on a bed of garlicky Greek yogurt, finished with warm paprika and chile butter.', array['Mince the garlic as finely as you can and stir it into the yogurt with half of the salt. Spread the yogurt in two shallow bowls and leave it out so it loses its chill.', 'Fill a medium pot with water to the depth of three fingers, bring it to a bare simmer over medium heat and add the vinegar.', 'Crack each egg into a small cup and slide them into the water one at a time. Cook 3 minutes at a bare simmer, until the whites are set and the yolks are still soft.', 'Lift the eggs out with a slotted spoon and drain them briefly on a paper towel.', 'Meanwhile, melt the butter in a small skillet over medium-low heat. When it foams, stir in the paprika and red pepper flakes for 30 seconds, until red and fragrant, then take it off the heat.', 'Set two eggs on each bowl of yogurt, spoon the spiced butter over them and finish with the remaining salt and the chopped parsley.']::text[], 'https://images.unsplash.com/photo-1762638896659-71c459861a45', 'Amin Zabardast', 'https://unsplash.com/photos/poached-eggs-with-yogurt-and-herbs-iCAeN-87L6w', true),
  ('tuscan-chicken-pasta', 'Tuscan-Style Chicken Pasta', 'dinner', array['high_protein']::text[], 4, 30, false, 'Chicken in a creamy garlic sauce with spinach and tomatoes over pasta.', array['Cook the pasta in salted water; save a cup of the water before draining.', 'Season the chicken with salt and Italian seasoning, sear in olive oil 4 minutes per side; slice.', 'Sauté the garlic 1 minute, add the cream and tomatoes; simmer 4 minutes until slightly thick.', 'Stir in the spinach until wilted, return the chicken and pasta, toss and serve with parmesan.']::text[], 'https://images.unsplash.com/photo-1781802768049-c14dd5b37bf3', 'Unsplash contributor', 'https://unsplash.com/photos/pasta-sauce-and-hot-dogs-cooking-on-a-kitchen-stove-WpqGmuCovwg', true),
  ('tuscan-white-bean-kale-soup', 'Tuscan White Bean and Kale Soup', 'dinner', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 40, true, 'Rustic soup of cannellini beans, kale and vegetables in a garlicky tomato broth, served with toasted bread.', array['Heat the oil in a large pot over medium heat and cook the onion, carrot and celery for 8 minutes, stirring now and then, until soft.', 'Add the garlic, Italian seasoning and red pepper flakes and stir for 1 minute until fragrant.', 'Add the beans, tomatoes with their juice, broth and salt and bring to a boil over high heat.', 'Strip the kale leaves from the stems, tear them into pieces and stir them into the pot.', 'Lower the heat and simmer uncovered for 15 minutes until the kale is tender and the broth has thickened slightly.', 'Mash a few spoonfuls of beans against the side of the pot, stir, and serve with the bread for dipping.']::text[], 'https://images.unsplash.com/photo-1659603646708-2e6db467b5e4', 'Green And Great', 'https://unsplash.com/photos/a-bowl-of-food--k7U_-Og15A', true),
  ('two-bean-minestrone-soup', 'Two-Bean Minestrone Soup', 'dinner', array['dairy_free', 'pescatarian', 'vegan', 'vegetarian']::text[], 4, 50, true, 'A big pot of vegetable soup with cabbage, zucchini, beans and elbow pasta in tomato broth.', array['Heat the oil in a large pot over medium heat and cook the onion, carrot and celery 6 minutes, stirring, until soft.', 'Stir in the garlic and Italian seasoning and cook 1 minute, until fragrant.', 'Add the tomatoes, broth, cabbage, zucchini and salt and bring to a boil over high heat.', 'Lower to medium-low and simmer uncovered 15 minutes, until the carrots are tender.', 'Stir in the drained beans and the pasta and cook 8 to 10 minutes, stirring now and then so the pasta does not stick, until the pasta is tender.', 'If the soup is thicker than you like, thin it with a little water, then taste and adjust the seasoning.', 'Ladle into bowls and serve.']::text[], 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d', 'Victoria Shes', 'https://unsplash.com/photos/stainless-steel-spoon-on-white-ceramic-bowl-90Z4qIxWc8Y', true),
  ('unstuffed-cabbage-roll-skillet', 'Unstuffed Cabbage Roll Skillet', 'dinner', array['dairy_free', 'gluten_free', 'keto', 'low_carb']::text[], 4, 35, true, 'All the flavor of cabbage rolls without the rolling: ground beef and chopped cabbage simmered in tomato sauce.', array['Dice the onion, mince the garlic and chop the cabbage into bite-size pieces, discarding the hard core.', 'Heat the olive oil in a large deep skillet or pot over medium-high heat. Add the beef and onion and cook 6 to 7 minutes, breaking up the meat, until it is browned and the onion is soft.', 'Stir in the garlic and paprika and cook 30 seconds until fragrant.', 'Add the cabbage, the diced tomatoes with their juice, the tomato sauce, broth, salt and pepper and stir; the cabbage piles high at first but cooks down.', 'Bring to a boil, then cover, lower the heat to medium-low and simmer 20 minutes, stirring now and then, until the cabbage is tender.', 'Taste, add a little more salt or pepper if it needs it, and serve in bowls.']::text[], 'https://images.unsplash.com/photo-1743148601298-655e3d10303e', 'András Gal', 'https://unsplash.com/photos/delicious-stew-simmers-in-a-large-pot-UkwpejZLgGI', true),
  ('vegetable-curry-tofu', 'Vegetable Curry with Tofu', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 30, true, 'Golden tofu and vegetables in a mild coconut curry over rice.', array['Cook the rice according to the package directions.', 'Heat the oil in a large skillet over medium-high heat and brown the tofu cubes 6 to 8 minutes, turning once; transfer to a plate.', 'Add the onion and cook 3 minutes, then stir in the curry paste and ginger and cook 1 minute.', 'Pour in the coconut milk with the cauliflower, cover and simmer 8 minutes until tender.', 'Return the tofu, warm through 2 minutes, season with salt and serve over rice.']::text[], 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db', 'Unsplash contributor', 'https://unsplash.com/photos/green-vegetable-on-white-ceramic-plate-PqsImnjuElM', true),
  ('vegetable-egg-fried-rice', 'Vegetable Egg Fried Rice', 'dinner', array['dairy_free', 'pescatarian', 'vegetarian']::text[], 4, 30, false, 'Rice stir-fried with scrambled eggs, frozen mixed vegetables, garlic and soy sauce.', array['Put the rice in a saucepan with a little less than twice as much water as rice, bring to a boil, cover and cook over low heat for 16 minutes, until the water is absorbed.', 'Spread the hot rice on a tray or large plate for 5 minutes so the steam escapes and the grains dry out.', 'While the rice cooks, beat the eggs. Heat half the vegetable oil in a large skillet or wok over medium heat, pour in the eggs and stir 1 to 2 minutes, until just set; move them to a plate.', 'Raise the heat to high, add the remaining oil and stir-fry the frozen vegetables and garlic 3 minutes, until hot and no water is left in the pan.', 'Add the rice and fry 4 minutes, pressing out clumps with the spoon, until the grains are separate and a few start to toast.', 'Stir in the eggs, soy sauce, sesame oil and green onion, toss 1 minute and serve.']::text[], 'https://images.unsplash.com/photo-1788603907381-018a23c26c81', 'Zoshua Colah', 'https://unsplash.com/photos/fried-rice-with-vegetables-Mrr4elxhksk', true),
  ('vegetable-lo-mein', 'Vegetable Lo Mein', 'dinner', array['vegetarian', 'vegan']::text[], 4, 25, false, 'Chewy noodles tossed with stir-fried vegetables in a sesame-soy sauce.', array['Cook the noodles according to the package directions, drain and rinse briefly.', 'Heat the oil in a large skillet or wok over high heat and stir-fry the vegetables and garlic 4 to 5 minutes until crisp-tender.', 'Add the noodles, soy sauce, sesame oil, vinegar and sugar, and toss 2 minutes until everything is coated and hot.', 'Scatter the green onions over the top and serve.']::text[], 'https://images.unsplash.com/photo-1774717530911-2ceb99449f7a', 'Unsplash contributor', 'https://unsplash.com/photos/glass-noodles-with-chicken-and-vegetables-in-a-bowl-96jPnoBCMGg', true),
  ('vegetable-tempura-rice-bowls', 'Crispy Vegetable Rice Bowls', 'dinner', array['vegetarian', 'vegan', 'dairy_free']::text[], 4, 30, false, 'Cornstarch-crisped vegetables over rice with a soy-ginger dipping sauce.', array['Cook the rice according to the package directions.', 'Stir the soy sauce, vinegar, ginger and a pinch of sugar in a small bowl for the sauce.', 'Toss the vegetables with the cornstarch and a pinch of salt until lightly coated.', 'Heat the oil in a large skillet over medium-high heat and fry the vegetables in two batches 4 to 5 minutes until crisp; drain on paper.', 'Serve over rice with the dipping sauce and sesame seeds.']::text[], 'https://images.unsplash.com/photo-1761315413537-b7bf6248050e', 'Unsplash contributor', 'https://unsplash.com/photos/fresh-spring-rolls-filled-with-vegetables-and-avocado-kJ2Kmqs3FX8', true),
  ('veggie-pita-pizzas', 'Veggie Pita Pizzas', 'lunch', array['high_protein', 'pescatarian', 'vegetarian']::text[], 2, 20, false, 'Pita rounds baked crisp with marinara, mozzarella, mushrooms, bell pepper and red onion.', array['Heat the oven to {425F}. Thinly slice the bell pepper, mushrooms and onion.', 'Arrange the pitas on a large sheet pan and bake 3 minutes, until the surface feels dry.', 'Spread the marinara over each pita, leaving a small border, and cover with the mozzarella.', 'Top with the vegetables, sprinkle with the Italian seasoning and drizzle with the olive oil.', 'Bake 8 to 10 minutes, until the cheese is bubbling and browned in spots and the pita edges are crisp.', 'Let cool 2 minutes, cut into quarters and serve two pizzas per person.']::text[], 'https://images.unsplash.com/photo-1627461985459-51600559fffe', 'georgia z', 'https://unsplash.com/photos/pizza-with-cheese-and-green-leaves-JG5lgvc57qE', true),
  ('veggie-ramen-stir-fry-eggs', 'Veggie Ramen Stir-Fry with Eggs', 'dinner', array['dairy_free', 'pescatarian', 'vegetarian']::text[], 4, 20, false, 'Ramen noodles tossed with stir-fry vegetables, scrambled eggs and a garlic soy sauce.', array['Bring a pot of water to a boil over high heat, cook the ramen noodles 2 minutes, until just loosened, and drain; leave out the seasoning packets.', 'In a small bowl, mix the soy sauce, brown sugar, sriracha and sesame oil until the sugar dissolves.', 'Beat the eggs. Heat half the vegetable oil in a large skillet or wok over medium heat, pour in the eggs and stir 1 to 2 minutes, until just set; move them to a plate.', 'Raise the heat to high, add the remaining oil and stir-fry the frozen vegetables, garlic and ginger 5 minutes, until hot and tender but still crisp.', 'Add the noodles, eggs and sauce and toss 1 to 2 minutes, until the noodles soak up the sauce.', 'Serve topped with the green onion.']::text[], 'https://images.unsplash.com/photo-1553621043-f607bfbf6640', 'Riccardo Bergamini', 'https://unsplash.com/photos/pasta-on-plate-Xe14NrSK9io', true),
  ('weeknight-chicken-tikka-masala-rice', 'Weeknight Chicken Tikka Masala with Rice', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 40, true, 'Chicken simmered in a creamy spiced tomato sauce from pantry staples, served over white rice.', array['Put the rice in a pot with twice its volume of water. Bring to a boil over high heat, then cover, turn the heat to low and cook 15 minutes until the water is absorbed; leave it covered off the heat until serving.', 'Cut the chicken into bite-size pieces and toss with the yogurt, half the curry powder and the salt. Dice the onion, mince the garlic and grate the ginger.', 'Melt the butter in a large deep skillet over medium-high heat. Add the chicken and cook 6 minutes, stirring a few times, until lightly browned.', 'Add the onion, garlic and ginger and cook 3 minutes until the onion softens.', 'Stir in the remaining curry powder, the cumin and paprika, then the tomato sauce and tomato paste. Lower the heat to medium-low and simmer 12 minutes, stirring now and then, until the sauce thickens and the chicken is cooked through.', 'Stir in the cream and heat 1 to 2 minutes over low heat without letting it boil hard.', 'Fluff the rice with a fork and serve the chicken and sauce over it.']::text[], 'https://images.unsplash.com/photo-1788462613018-40916ff6415c', 'gabbiistudios', 'https://unsplash.com/photos/chicken-tikka-masala-dinner-plate-7ZGOtqVZtAk', true),
  ('weeknight-spaghetti-with-meat-sauce', 'Weeknight Spaghetti with Meat Sauce', 'dinner', array['high_protein']::text[], 4, 25, false, 'Spaghetti tossed in a quick ground beef and marinara sauce with onion, garlic and parmesan.', array['Bring a large pot of water to a boil over high heat and add the salt.', 'Meanwhile, heat the oil in a large skillet over medium heat and cook the onion 4 minutes, stirring, until soft and translucent.', 'Raise the heat to medium-high, add the ground beef and garlic and cook 6 to 8 minutes, breaking up the meat, until no pink remains; spoon off most of the fat.', 'Stir in the marinara and Italian seasoning, lower the heat to medium-low and simmer 8 minutes, stirring now and then, until slightly thickened.', 'While the sauce simmers, boil the spaghetti for the time on the package, usually 9 to 11 minutes, until tender but still firm to the bite, then drain.', 'Toss the spaghetti with the sauce in the skillet for 1 minute and serve topped with the parmesan.']::text[], 'https://images.unsplash.com/photo-1622973536968-3ead9e780960', 'Homescreenify', 'https://unsplash.com/photos/spaghetti-on-white-ceramic-plate-sA3wymYqyaI', true),
  ('white-bean-kale-soup', 'White Bean and Kale Soup', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 35, true, 'A garlicky bean and kale soup in tomato broth — ribollita-style.', array['Sauté the onion and carrot in olive oil 5 minutes, add the garlic and cook 1 minute.', 'Add the tomatoes, broth and beans; simmer 15 minutes, mashing a few beans.', 'Stir in the kale and cook 5 minutes until tender.', 'Season with salt and serve with olive oil on top.']::text[], 'https://images.unsplash.com/photo-1721314678207-8b7bd43e677b', 'Unsplash contributor', 'https://unsplash.com/photos/a-plate-of-food-on-a-red-and-white-table-cloth-xGUGTo8779I', true),
  ('white-bean-tomato-stew', 'White Bean and Tomato Stew', 'dinner', array['vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], 4, 30, true, 'Rustic Italian beans stewed with tomato, garlic and rosemary, over toast.', array['Sauté the garlic in olive oil 1 minute, add the tomatoes and simmer 8 minutes until slightly thick.', 'Add the beans with a splash of water and simmer 8 minutes more, mashing a few to thicken.', 'Stir in the spinach until it wilts and season with salt.', 'Serve with olive oil drizzled on top.']::text[], 'https://images.unsplash.com/photo-1759392773285-0f86affdf1df', 'Unsplash contributor', 'https://unsplash.com/photos/bowl-of-braised-pork-knuckle-with-green-beans-K2O7ApS6Y4w', true),
  ('white-chicken-chili', 'White Chicken Chili', 'dinner', array['high_protein', 'gluten_free']::text[], 4, 45, true, 'Shredded chicken, white beans, corn and green chiles in a creamy cumin broth with lime and cilantro.', array['Heat the oil in a large pot over medium heat and cook the onion and jalapeño for 5 minutes until soft.', 'Add the garlic, cumin and oregano and stir for 1 minute until fragrant.', 'Add the broth, green chiles, beans and salt, nestle in the whole chicken breasts and bring to a boil over high heat.', 'Lower the heat, cover and simmer for 15 to 18 minutes until the chicken reaches {165F} in the thickest part or shows no pink when cut.', 'Lift the chicken onto a plate and shred it with two forks; meanwhile mash some of the beans against the side of the pot to thicken the chili.', 'Return the chicken to the pot with the corn and simmer uncovered for 5 minutes.', 'Take the pot off the heat, stir in the sour cream and lime juice and serve topped with the cilantro.']::text[], 'https://images.unsplash.com/photo-1715733448307-9a5010aaafbb', 'Tim McErston', 'https://unsplash.com/photos/a-person-holding-a-bowl-of-soup-in-front-of-a-crock-pot-k4MaXzTx1Qk', true),
  ('yuca-style-potato-stew', 'Beef and Potato Stew', 'dinner', array['gluten_free', 'dairy_free', 'high_protein']::text[], 4, 60, true, 'A Latin-style beef stew with potatoes, tomatoes and cumin — Sunday food.', array['Season the beef with salt and brown it in hot oil in batches, 4 minutes per batch; set aside.', 'Sauté the onion and bell pepper 5 minutes, add the garlic, cumin and oregano and cook 1 minute.', 'Return the beef, add the tomatoes, broth and potatoes; bring to a simmer.', 'Cover and cook 35 to 40 minutes until the beef and potatoes are tender.', 'Serve with cilantro and lime.']::text[], 'https://images.unsplash.com/photo-1775229910950-0b7a99bf8674', 'Unsplash contributor', 'https://unsplash.com/photos/hearty-stew-with-meat-and-vegetables-in-a-ceramic-pot-icRCFbPR0_0', true),
  ('zucchini-cottage-cheese-lasagna', 'Zucchini and Cottage Cheese Lasagna', 'dinner', array['gluten_free', 'high_protein', 'keto', 'low_carb', 'pescatarian', 'vegetarian']::text[], 4, 70, true, 'Roasted zucchini planks stand in for noodles, layered with cottage cheese, marinara and mozzarella.', array['Heat the oven to {425F} and line two sheet pans with parchment paper.', 'Slice the zucchini lengthwise into thin planks, about as thick as a pencil, lay them on the pans in one layer and sprinkle with the salt.', 'Roast 12 minutes, until the planks are limp and starting to brown at the edges, then press them between paper towels to blot away the moisture.', 'Lower the oven to {375F}.', 'Mix the cottage cheese with the egg, garlic, Italian seasoning, pepper, half the parmesan and half the mozzarella.', 'Spread a thin layer of marinara in a medium square baking dish, then add a layer of zucchini, a third of the cottage cheese mixture and a little more marinara; repeat twice more.', 'Top with the remaining mozzarella and parmesan.', 'Bake uncovered 30 minutes, until bubbling and browned on top, then rest 10 minutes so the slices hold together.']::text[], 'https://images.unsplash.com/photo-1632229095740-8c75082087c5', 'Moira Nazzari', 'https://unsplash.com/photos/a-dish-of-food-on-a-wooden-table-Y9iaZNbUHtQ', true)
